(window.WCD=window.WCD||[]).push(["belgique",[["Q333466",1,"ville","Andenne","C","Andenne est une ville francophone de Belgique située en Région wallonne dans la province de Namur.",null,"fr:Andenne","c:0/05/Hotel_de_Ville_Andenne.JPG",{"cats":["belgique","geo"]}],["Q12892",2,"ville","Anvers","E","Anvers est une ville belge dans la Région flamande, chef-lieu de la province d'Anvers et de l'arrondissement administratif du même nom, située au cœur de la Dorsale européenne.",108,"fr:Anvers","c:2/2a/Grote_Markt_in_Antwerpen.jpg",{"cats":["belgique","geo"]}],["Q675960",3,"ville","Arlon","PC","Arlon est une ville de Belgique, en Wallonie. Elle est historiquement germanophone et officiellement francophone. Il s'agit du chef-lieu de la province belge de Luxembourg, elle est également chef-lieu de son arrondissement administratif.","Arlon est une ville de Belgique, en Wallonie.","fr:Arlon","c:7/7a/Arlon_E1aJPG.jpg"],["Q34021",4,"ville","Bastogne","PC","Bastogne est une ville francophone de Belgique et un chef-lieu d'arrondissement situé en Région wallonne dans la province de Luxembourg.",112,"fr:Bastogne","c:9/99/Bastogne_JPG02.jpg"],["Q95121",5,"ville","Binche","C","Binche est une ville francophone de Belgique située en Région wallonne dans la province de Hainaut. La ville est située dans la région du Centre sur l'axe reliant les villes de Mons et de Charleroi.","Binche est une ville francophone de Belgique située en Région wallonne dans la province de Hainaut.","fr:Binche","c:7/79/Binche_9-05-2021_13-31-53.jpg"],["Q217216",6,"ville","Bouillon","PC","Bouillon est une ville francophone de Belgique, située en Région wallonne et en Ardenne belge dans la province de Luxembourg.",113,"fr:Bouillon_(Belgique)","c:1/14/Bouillon_-_Ch%C3%A2teau-fort_et_cit%C3%A9_%281%29.jpg"],["Q12994",7,"ville","Bruges","E","Bruges est une ville de Belgique située en région flamande, chef-lieu et plus grande ville de la province de Flandre-Occidentale.",108,"fr:Bruges","c:9/9a/Br%C3%BCgge_Blick_vom_Belfried_4.jpg",{"cats":["belgique","geo"]}],["Q9005",8,"ville","Bruxelles","PC","Bruxelles, aussi appelé aire urbaine de Bruxelles ou Grand Bruxelles ou aire métropolitaine de Bruxelles, est une agglomération de Belgique. Celle-ci s'étend au-delà des limites administratives de la Région de Bruxelles-Capitale pour englober des parties du Brabant flamand et du Brabant wallon. En son centre se trouve la commune de Bruxelles proprement dite, dont le nom utilisé par la constitution belge est ville de Bruxelles.",113,"fr:Bruxelles","c:1/1f/Agglomeratie_Brussel.png"],["Q81046",9,"ville","Charleroi","R","Charleroi est une ville francophone de Belgique, située en Wallonie, province de Hainaut, sur la Sambre. C'est le chef-lieu de l'arrondissement administratif de Charleroi englobant 12 communes sur une superficie totale de 472,19 km2.","Charleroi est une ville francophone de Belgique, située en Wallonie, province de Hainaut, sur la Sambre.","fr:Charleroi","c:0/04/Charleroi_-_place_Vauban_-_jets_d%27eau_-_2024-07-14_-_01.jpg",{"cats":["belgique","geo"]}],["Q95144",10,"ville","Châtelet","C","Châtelet est une ville de Belgique située en Région wallonne dans la province de Hainaut. Depuis la fusion des communes de 1977, la ville de Châtelet regroupe Bouffioulx, Châtelet et Châtelineau. Toutefois, les identités propres à ces trois communes sont restées importantes. Il est donc fréquent d'entendre les gentilés respectifs: Bouffaloniens, Châtelettain et Castellinois.","Châtelet est une ville de Belgique située en Région wallonne dans la province de Hainaut.","fr:Châtelet_(Belgique)","c:3/36/Ch%C3%A2telet_%28Belgique%29_-_h%C3%B4tel_de_ville_-_01.jpg",{"cats":["belgique","geo"]}],["Q2712642",11,"ville","Châtelineau","C","Châtelineau est une section de la ville belge de Châtelet située en Région wallonne dans la province de Hainaut. C'était une commune à part entière avant la fusion des communes de 1977. Ses habitants sont appelés les Castellinois.","Châtelineau est une section de la ville belge de Châtelet située en Région wallonne dans la province de Hainaut.","fr:Châtelineau","c:b/b5/Charbonnage_du_Gouffre_02.JPG"],["Q456490",12,"ville","Ciney","C","Ciney est une ville francophone de Belgique située en Wallonie dans la province de Namur.",null,"fr:Ciney","c:8/85/Ciney_JPG02.jpg"],["Q573179",13,"ville","Couillet","C","Couillet est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut. Au XIXe siècle et au XXe siècle, la localité a été un grand centre industriel de production charbonnière, métallurgique et chimique.","Couillet est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.","fr:Couillet","c:8/8d/Couillet_-_Maison_communale_-_2026-08-01_-_01.jpg"],["Q12995",14,"ville","Courtrai","PC","Courtrai est une ville de Belgique située en Région flamande, chef-lieu d'arrondissement en province de Flandre-Occidentale.",103,"fr:Courtrai","c:4/4f/Kortrijk_-_Beguinage_and_Sint-Maartenskerk.jpg"],["Q2014292",15,"ville","Coutisse","C","Coutisse est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.",null,"fr:Coutisse",""],["Q326771",16,"ville","Couvin","C","Couvin est une ville francophone de Belgique située en Région wallonne dans la province de Namur et faisant partie de l'arrondissement de Philippeville. Située en Calestienne et frontalière avec la France, Couvin a été le berceau de la fabrication des raquettes de tennis Donnay. Couvin est le chef-lieu du canton regroupant sa propre commune et celle de Viroinval et se situe dans le parc national de l'Entre-Sambre-et-Meuse.",117,"fr:Couvin","c:5/59/Couvin_JPG00.jpg"],["Q108247",17,"ville","Dinant","PC","Dinant est une ville francophone de Belgique située en Région wallonne, chef-lieu d'arrondissement en province de Namur.",null,"fr:Dinant","c:f/f7/Dinant_reflected.jpg",{"cats":["belgique","geo"]}],["Q497697",18,"ville","Durbuy","PC","Durbuy est une ville historique de Belgique située en Région wallonne dans la province de Luxembourg. Bâtie dans un méandre de l'Ourthe et ancien chef-lieu du comté de Durbuy, elle est souvent appelée « la plus petite ville du monde ». Depuis la fusion des communes intervenue en 1977, Durbuy a donné son nom et son titre de ville à une nouvelle commune très vaste, avec Barvaux-sur-Ourthe comme centre administratif, dont certains villages sont bien plus peuplés qu'elle.","Durbuy est une ville historique de Belgique située en Région wallonne dans la province de Luxembourg.","fr:Durbuy","c:7/7f/L%27ancien_couvent_des_R%C3%A9collets%2C_l%27%C3%A9glise_Saint-Nicolas_et_le_ch%C3%A2teau_de_Durbuy.jpg"],["Q151831",19,"ville","Eupen","PC","Eupen est une ville germanophone de Belgique située dans la province de Liège en Région wallonne.",null,"fr:Eupen","c:e/ee/63023-CLT-0063-01_Regierung_der_Deutschsprachigen_Gemeinschaft_Belgiens_%282%29.jpg"],["Q314922",20,"ville","Fleurus","C","Fleurus est une ville francophone de Belgique située en Région wallonne dans la province de Hainaut au nord-est de Charleroi.",114,"fr:Fleurus","c:f/f9/Fleurus_-_Ch%C3%A2teau_de_la_Paix_-_2023-04-29_-_01.jpg"],["Q578583",21,"ville","Floreffe","C","Floreffe est un village en bord la Sambre, à la sortie de Namur, en province de Namur. Administrativement c'est une commune francophone de Belgique issue de la fusion en 1977 de Floreffe,","Floreffe est un village en bord la Sambre, à la sortie de Namur, en province de Namur.","fr:Floreffe","c:4/40/Abdij_van_Floreffe_29-03-2025_12-03-15.jpg"],["Q720478",22,"ville","Fosses-la-Ville","C","Fosses-la-Ville est une ville francophone de Belgique située en Wallonie dans la province de Namur. Sise dans l’Entre-Sambre-et-Meuse, elle est arrosée par la Biesme.","Fosses-la-Ville est une ville francophone de Belgique située en Wallonie dans la province de Namur.","fr:Fosses-la-Ville","c:9/90/Fosses-la-Ville_JPG002.jpg"],["Q1296",23,"ville","Gand","E","Gand, est une ville belge néerlandophone, située en Région flamande au confluent de la Lys et de l'Escaut. Elle est le chef-lieu de la province de Flandre-Orientale et depuis 1559 le siège de l'évêché de Gand. Avec 274 042 habitants, elle est la deuxième commune de Belgique, après Anvers. L'agglomération gantoise compte environ 455 000 habitants.","Gand, est une ville belge néerlandophone, située en Région flamande au confluent de la Lys et de l'Escaut.","fr:Gand","c:9/90/Gent%2C_de_Graslei_vanaf_de_Korenlei_met_oeg24758tm61%2B25159_IMG_0447_2021-08-13_18.37.jpg",{"cats":["belgique","geo"]}],["Q223927",24,"ville","Gembloux","C","Gembloux est une ville francophone de Belgique située en Région wallonne dans la province de Namur. Elle se trouve sur l'axe routier et l'axe ferroviaire Bruxelles-Namur, à l'extrémité nord de la province.","Gembloux est une ville francophone de Belgique située en Région wallonne dans la province de Namur.","fr:Gembloux","c:2/26/Town_hall_of_Gembloux_with_belfry_visible_in_the_background_%28DSCF7616%29.jpg",{"cats":["belgique","geo"]}],["Q388879",25,"ville","Gesves","C","Gesves est une commune francophone de Belgique située en Région wallonne dans la province de Namur, ainsi qu'une localité où siège son administration.",112,"fr:Gesves","c:4/47/Gesves_JPG01.jpg"],["Q900766",26,"ville","Gilly","C","Gilly est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut. Elle constituait l'une des quatorze communes qui ont fusionné en 1977 avec Charleroi.","Gilly est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.","fr:Gilly_(Charleroi)","c:4/47/Maison_communale_annexe_Gilly_01.jpg",{"cats":["belgique","geo"]}],["Q900761",27,"ville","Gosselies","C","Gosselies est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut. C'était une commune à part entière et une ville avant la fusion des communes de 1977.","Gosselies est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.","fr:Gosselies","c:8/89/Gosselies_-_%C3%A9glise_Saint-Jean-Baptiste_et_tour_de_l%27ancien_ch%C3%A2teau_-_01.jpg"],["Q1026218",28,"ville","Han-sur-Lesse","C","Han-sur-Lesse est une section et un village de la ville belge de Rochefort situés en Région wallonne, dans la province de Namur et l'arrondissement de Dinant.",118,"fr:Han-sur-Lesse","c:9/9e/Han-sur-Lesse_Riv1JPG.jpg"],["Q58780",29,"ville","Hasselt","R","Hasselt est une ville néerlandophone de Belgique située en Région flamande, chef-lieu de la province de Limbourg et chef-lieu de l'arrondissement du même nom.",115,"fr:Hasselt","c:d/d1/Hasselt-Rathaus-20060906.jpg"],["Q207095",30,"ville","Huy","PC","Huy est une ville francophone de la Belgique traversée par la Meuse, chef-lieu d'arrondissement en province de Liège en Région wallonne.",119,"fr:Huy","c:a/a0/0_Huy_-_Grand%27Place_%281%29.JPG",{"cats":["belgique","geo"]}],["Q208713",31,"ville","Ixelles","PC","Ixelles est l'une des 581 communes belges et une des 19 communes bilingues de la Région de Bruxelles-Capitale.",null,"fr:Ixelles","c:9/9d/MAISON-40.jpg"],["Q3160833",32,"ville","Jambes","C","Jambes est une section au sud de la ville belge de Namur située en Wallonie dans la province de Namur.",null,"fr:Jambes","c:8/8e/Jambes_Pt1b.jpg"],["Q843315",33,"ville","Jumet","C","Jumet est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut. Avant la fusion des communes belges de 1977, Jumet était une commune à part entière.","Jumet est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.","fr:Jumet","c:f/fe/Jumet_-_H%C3%B4tel_de_Ville.jpg"],["Q12988",34,"ville","Knokke-Heist","C","Knokke-Heist est une commune néerlandophone de Belgique située en Région flamande dans la province de Flandre-Occidentale. C'est une station balnéaire huppée d’environ 35 000 habitants sur la côte, à la frontière avec les Pays-Bas.",101,"fr:Knokke-Heist","c:6/6e/Knocke-Heist.jpg"],["Q211572",35,"ville","La Louvière","PC","La Louvière est une ville francophone de Belgique. Elle se situe en Wallonie dans la province de Hainaut. Elle est surnommée la « cité des Loups ».","La Louvière est une ville francophone de Belgique.","fr:La_Louvière","c:4/4d/La_Louvi%C3%A8re_-_Vue_a%C3%A9rienne_%28cropped%29.jpg"],["Q730506",36,"ville","Laeken","C","Laeken est une section de la ville de Bruxelles située au nord de celle-ci, au sein de la Région de Bruxelles-Capitale, en Belgique.",119,"fr:Laeken","c:2/29/Former_Townhall_Laeken_Brussels_2103-08.JPG"],["Q2541119",37,"ville","Landenne","C","Landenne, autrefois Landenne-sur-Meuse, est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.",117,"fr:Landenne","c:f/ff/Landenne_JPG01.jpg"],["Q3992",38,"ville","Liège","E","Liège est une ville wallonne de l'Est de la Belgique.",null,"fr:Liège","c:4/4b/Prince-Bishops%27_Palace_in_Liege_%28cropped_1%29.jpg",{"cats":["belgique","geo"]}],["Q607274",39,"ville","Lodelinsart","C","Lodelinsart est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.",null,"fr:Lodelinsart","c:3/3a/Lodelinsart_-_Maison_communale_et_annexes.jpg"],["Q118958",40,"ville","Louvain","R","Louvain est une ville néerlandophone de Belgique située en Région flamande, chef-lieu de la province du Brabant flamand et chef-lieu de l'arrondissement qui porte son nom. Elle est arrosée par la Dyle, affluent du Rupel.",119,"fr:Louvain","c:9/92/Tafelrond_Leuven_-_385956_-_onroerenderfgoed.jpg"],["Q665868",41,"ville","Louvain-la-Neuve","PC","Louvain-la-Neuve est une section de la commune belge d'Ottignies-Louvain-la-Neuve, située en Région wallonne dans la province du Brabant wallon.",116,"fr:Louvain-la-Neuve","c:8/8e/Belgique_-_Louvain-la-Neuve_-_Grand-Place_-_01.jpg"],["Q2172363",42,"ville","Maizeret","C","Maizeret est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.",null,"fr:Maizeret","c:a/ab/Maizeret_050818_%281%29.JPG"],["Q162022",43,"ville","Malines","R","Malines (; en néerlandais: Mechelen, prononcé) est une commune et ville néerlandophone de Belgique située en Région flamande dans la province d'Anvers, chef-lieu de l'arrondissement. Malines compte 90 355 habitants. C'est la sixième ville de Flandre en nombre d'habitants et la deuxième ville de province, après Anvers. Elle est aussi la deuxième ville sur la Dyle, après Louvain.",115,"fr:Malines","c:6/65/Mechelen_City_Hall_01.JPG"],["Q159838",44,"ville","Malmedy","PC","Malmedy, parfois orthographié Malmédy, est une ville francophone de Belgique située en Région wallonne dans la province de Liège.",119,"fr:Malmedy","c:d/d5/Vue_de_Malmedy_en_mai_2012.jpg"],["Q2189182",45,"ville","Malonne","C","Malonne est une section de la ville belge de Namur située en Wallonie dans la province de Namur. C'était une commune à part entière avant la fusion des communes de 1977. La structure du village était initialement très éparpillée, avec pas moins de 52 hameaux qui étaient autant de clairières habitées dans la foret de Marlagne. Un coeur de village s'est développé le long du Landoir, un ruisseau affluent de la Sambre en rive droite, connectant les hameaux de Bauce, du 'Fond de Malonne', du Malpas et d'Incevaux.","Malonne est une section de la ville belge de Namur située en Wallonie dans la province de Namur.","fr:Malonne","c:0/0a/SaintBerthuin_malonne.jpg"],["Q269908",46,"ville","Marche-en-Famenne","C","Marche-en-Famenne est une ville francophone de Belgique située en Wallonie dans la province de Luxembourg, chef-lieu de l'arrondissement administratif du même nom.",119,"fr:Marche-en-Famenne","c:b/b4/Marche-en-Famenne_HV1aJPG.jpg"],["Q941041",47,"ville","Marchienne-au-Pont","C","Marchienne-au-Pont est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.",null,"fr:Marchienne-au-Pont","c:1/14/Marchienne-au-Pont_-_salon_communal_-_2021-07-21_-_02.jpg"],["Q785440",48,"ville","Marcinelle","C","Marcinelle est une section de la ville belge de Charleroi, située en Wallonie dans la province de Hainaut.",null,"fr:Marcinelle","c:8/87/Marcinelle_-_Ancienne_maison_communale_-_2023-04-05_-_01.jpg",{"cats":["belgique","geo"]}],["Q118769",49,"ville","Mettet","C","Mettet est une commune francophone de Belgique située en Région wallonne dans la province de Namur. Le village a donné son nom à l'entité de Mettet qui réunit différentes localités.","Mettet est une commune francophone de Belgique située en Région wallonne dans la province de Namur.","fr:Mettet","c:f/f2/Mettet_JPG01.jpg"],["Q180775",50,"ville","Molenbeek-Saint-Jean","PC","Molenbeek-Saint-Jean, couramment appelée Molenbeek, est l'une des 19 communes bilingues de la région de Bruxelles-Capitale en Belgique. Située dans l'ouest de la région, la commune est bordée par la ville de Bruxelles, dont elle est séparée par le canal Charleroi-Bruxelles, les communes bruxelloises d'Anderlecht, Berchem-Sainte-Agathe, Jette et Koekelberg, ainsi que par la commune flamande de Dilbeek. Le ruisseau Molenbeek, d'où elle tire son nom, traverse la commune. Ses habitants sont appelés les Molenbeekois.",103,"fr:Molenbeek-Saint-Jean","c:7/7b/Pin_Wheels_%288307190869%29.jpg"],["Q83407",51,"ville","Mons","R","Monsest une ville francophone de Belgique située en Wallonie. Ancienne capitale des comtes de Hainaut, chef-lieu de la province de Hainaut, ville principale de l’arrondissement de Mons, elle est le siège d’une des cinq cours d’appel du pays. La population montoise est de 97 745 habitants en 2026 et son agglomération contient 261 255 habitants.","Monsest une ville francophone de Belgique située en Wallonie.","fr:Mons","c:8/8f/070204_%2890%29_Mons.JPG"],["Q843323",52,"ville","Mont-sur-Marchienne","C","Mont-sur-Marchienne est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.",null,"fr:Mont-sur-Marchienne","c:f/f2/Mont-sur-Marchienne_-_H%C3%B4tel_communal_-_2020_-_03.jpg"],["Q837453",53,"ville","Montignies-sur-Sambre","C","Montignies-sur-Sambre est une section de la ville belge de Charleroi, située en Wallonie, dans la province de Hainaut.",null,"fr:Montignies-sur-Sambre","c:8/87/Montignies-sur-Sambre_-_H%C3%B4tel-de-Ville.jpg",{"cats":["belgique","geo"]}],["Q134121",54,"ville","Namur","R","Namur est une ville francophone de Belgique, capitale de la Wallonie depuis 1986, et chef-lieu de la province de Namur. La ville occupe une position centrale à 62,5 km au sud-est de Bruxelles, à 40 km à l'est de Charleroi et à 66 km à l'ouest de Liège. Sa position au confluent de la Meuse et de la Sambre en fait un nœud de communication important.","Namur est une ville francophone de Belgique, capitale de la Wallonie depuis 1986, et chef-lieu de la province de Namur.","fr:Namur","c:8/89/NEW-Parlement-12juin-3.jpg",{"cats":["belgique","geo"]}],["Q2298793",55,"ville","Namêche","C","Namèche est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.",null,"fr:Namêche","c:c/ca/NamecheFromAcrossRiver.jpg"],["Q319463",56,"ville","Nivelles","C","Nivelles est une ville francophone de Belgique située en Région wallonne dans la province du Brabant wallon, chef-lieu de l'arrondissement administratif et judiciaire de Nivelles.",118,"fr:Nivelles","c:2/23/Nivelles1307_%28cropped%29.JPG"],["Q721090",57,"ville","Ohey","C","Ohey est une commune francophone de Belgique située en Région wallonne dans la province de Namur, ainsi qu’une localité où siège son administration.",119,"fr:Ohey","c:d/db/0_Ohey_-_Maison_communale_et_%C3%A9glise_St-Pierre.JPG"],["Q12996",58,"ville","Ostende","R","Ostende est une ville belge située en Région flamande, dans la province de Flandre-Occidentale.",null,"fr:Ostende","c:6/65/Oostende_Europacentrum_01.jpg"],["Q329642",59,"ville","Ottignies-Louvain-la-Neuve","C","Ottignies-Louvain-la-Neuve est une commune et ville francophone de Belgique, située dans la province du Brabant wallon en Région wallonne, qui accueille sur son territoire l'université catholique de Louvain.",118,"fr:Ottignies-Louvain-la-Neuve","c:1/13/Belgique_-_Ottignies_-_maison_communale_-_01.jpg"],["Q650239",60,"ville","Philippeville","C","Philippeville est une ville francophone de Belgique située en Wallonie, dans la province de Namur.",null,"fr:Philippeville","c:e/ec/Belgium%2C_Namur%2C_Philippeville_%2808%29%2C_Hotel_de_Ville.jpg"],["Q696940",61,"ville","Profondeville","C","Profondeville est une commune francophone de Belgique située en Wallonie dans la province de Namur, ainsi qu’une localité où siège son administration.",112,"fr:Profondeville","c:6/62/Profondeville_JPG01.jpg"],["Q497764",62,"ville","Rochefort","PC","Rochefort est une ville francophone et commune de Belgique située en Région wallonne dans la province de Namur, aux confins de la Famenne, de la Calestienne et de l'Ardenne. Ville touristique largement contenue dans une boucle de la Lomme, elle est considérée comme ville principale des deux vallées qui forment la région de la Haute-Lesse. Elle se trouve à 105 km au sud de Bruxelles.",115,"fr:Rochefort_(Belgique)","c:f/fb/Rochefort_JPG00.jpg"],["Q237674",63,"ville","Saint-Gilles","C","Saint-Gilles, parfois appelé Saint-Gilles-lez-Bruxelles, est l'une des 581 communes de Belgique et une des dix-neuf communes bilingues de la Région de Bruxelles-Capitale.",115,"fr:Saint-Gilles_(Bruxelles)","c:9/9b/StGillesTownHall.jpg"],["Q650185",64,"ville","Sambreville","C","Sambreville est une commune et depuis le 12 mars 2024 aussi une ville de Belgique située en Région wallonne dans la province de Namur.",115,"fr:Sambreville","c:8/8b/Auvelais_Sambreville_Hotel_de_Ville_Belgium_20070101_Didier_Misson.JPG"],["Q12887",65,"ville","Schaerbeek","PC","Schaerbeek est l'une des 19 communes bilingues de la région de Bruxelles-Capitale en Belgique.",null,"fr:Schaerbeek","c:c/c3/H%C3%B4tel_communal_de_Schaerbeek_%282%29_-_2264-0007-0.jpg"],["Q2184160",66,"ville","Sclayn","C","Sclayn est une localité en bord de Meuse, entre Namur et Andenne, dont elle fait administrativement partie en province de Namur. Elle était une commune à part entière avant la fusion des communes de 1977.",118,"fr:Sclayn","c:9/90/Sclayn-reserve.jpg"],["Q1958221",67,"ville","Seilles","C","Seilles est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur. C'était une commune à part entière avant la fusion des communes de 1977. Avant la fusion, Seilles faisait partie de la province de Liège. Son dernier bourgmestre, toujours avant la fusion, fut le socialiste Claude Eerdekens.","Seilles est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.","fr:Seilles","c:3/3a/Seilles_20250103_22.jpg",{"cats":["belgique","geo"]}],["Q194037",68,"ville","Seraing","C","Seraing est une ville francophone de Belgique située en Région wallonne dans la province de Liège. Il s'agit du lieu de l'ancienne résidence d'été des princes-évêques de Liège avant de devenir une ville industrielle au XIXe siècle.","Seraing est une ville francophone de Belgique située en Région wallonne dans la province de Liège.","fr:Seraing","c:1/15/Ch%C3%A2teau_Cockerill-Seraing.jpg"],["Q39865",69,"ville","Spa","PC","Spa est une ville francophone de Belgique située dans la province de Liège en Région wallonne. Elle est connue pour ses eaux thermales et a donné son nom au centre d'hydrothérapie éponyme.","Spa est une ville francophone de Belgique située dans la province de Liège en Région wallonne.","fr:Spa_(ville)","c:5/50/Spa_JPG05.jpg"],["Q173219",70,"ville","Tournai","R","Tournai est une ville francophone de Belgique située en Région wallonne et historiquement en Flandre romane, et française une dernière fois entre 1794 et 1814 Période française de l'histoire de Belgique, chef-lieu d’arrondissement de la province de Hainaut et siège de l'évêché de Tournai",111,"fr:Tournai","c:d/d3/Tournai_%28Belgique-Belgium%2C_Belgi%C3%AB%29%2C_Grand%27Place.jpg"],["Q203312",71,"ville","Uccle","PC","Uccle est une commune belge, l'une des 19 communes bilingues de la région de Bruxelles-Capitale.",null,"fr:Uccle","c:b/ba/3557uccleTownHall.jpg"],["Q202954",72,"ville","Verviers","PC","Verviers est une ville francophone de Belgique située en Région wallonne, chef-lieu d'arrondissement en province de Liège, à l'extrémité est du sillon industriel. C'est la capitale wallonne de l'eau.",115,"fr:Verviers","c:0/0a/Verviers_JPG02.jpg"],["Q179034",73,"ville","Waterloo","R","Waterloo /watɛʁlo/ est une commune belge francophone située à une vingtaine de kilomètres au sud de Bruxelles, dans la province du Brabant wallon.",118,"fr:Waterloo","c:4/4e/EgliseStJosephWaterloo.jpg"],["Q181314",74,"ville","Wavre","C","Wavre est une ville francophone du centre de la Belgique située au bord de la Dyle, chef-lieu de la province du Brabant wallon en région wallonne.",119,"fr:Wavre","c:2/24/Wavre_-_Saint-Jean-Baptiste_-_vue_d%27ensemble.JPG"],["Q612874",75,"ville","Wépion","C","Wépion est une section de la ville belge de Namur. Située dans la partie méridionale de Namur, Wépion se trouve en bord de Meuse tout en ayant une partie ancienne sur les hauteurs. C'était une commune à part entière avant la fusion des communes de 1977.","Wépion est une section de la ville belge de Namur.","fr:Wépion","c:9/9b/Balades_le_long_du_halage_%C3%A0_W%C3%A9pion.JPG"],["Q102728",76,"ville","Ypres","R","Ypres est une ville de Belgique située en Région flamande, chef-lieu d'arrondissement en province de Flandre-Occidentale.",100,"fr:Ypres","c:6/6a/Ypres_grand_place.JPG"],["Q151985",77,"region","Ardenne","R","L'Ardenne est une région géographique de basse montagne qui s'étend sur les territoires belge, français, luxembourgeois et allemand, située à l'est de la Meuse et de la Sambre et limitée au sud par les plaines de Lorraine et de Champagne. Le Massif ardennais est une ancienne chaîne de haute montagne qui culminait à 8 000 mètres d'altitude, qui a été affectée par les plissements calédoniens et varisques.",119,"fr:Ardenne","c:f/f6/Frahan_JPG01.jpg",{"cats":["belgique","geo"]}],["Q93782",78,"region","Arrondissement administratif de Namur","C","L'arrondissement administratif de Namur est l'un des trois arrondissements de la province de Namur en Région wallonne. Il existe également un arrondissement judiciaire de Namur, ressortissant de la cour d'appel de Liège. On l'appelle également \"le namurois\", pour ne pas prêter confusion en disant région namuroise sachant qu'il y a la province du même nom dans son entiereté.","L'arrondissement administratif de Namur est l'un des trois arrondissements de la province de Namur en Région wallonne.","fr:Arrondissement_administratif_de_Namur","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Arrondissement_Namur_Belgium_Map.svg/330px-Arrondissement_Namur_Belgium_Map.svg.png"],["Q31",79,"region","Belgique","M","La Belgique, en forme longue le royaume de Belgique, est un pays d'Europe de l'Ouest, bordé par la France, les Pays-Bas, l'Allemagne, le Luxembourg et la mer du Nord. La Belgique couvre une superficie de 30 688 km2 avec une population de 11 825 551 habitants au 1er janvier 2025, soit une densité de 385 habitants/km2. Politiquement, il s'agit d'une monarchie constitutionnelle fédérale à régime parlementaire.",110,"fr:Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/EU-Belgium.svg/330px-EU-Belgium.svg.png",{"cats":["belgique","geo"]}],["Q182920",80,"region","Borinage","C","Le Borinage est une région belge de la Région wallonne située dans la province de Hainaut, à l'ouest et au sud-ouest de la ville de Mons. Elle s’étend jusqu’à la frontière franco-belge, à l'extrémité ouest du sillon Sambre-et-Meuse.",119,"fr:Borinage","c:b/b9/Vue_de_P%C3%A2turages_%28Colfontaine%29.jpg"],["Q90027",81,"region","Communauté germanophone de Belgique","PC","La Communauté germanophone de Belgique, ou Belgique de l'Est, est l'une des trois communautés de Belgique, où la langue officielle est l'allemand. Elle se situe dans l'est de la province de Liège, en Région wallonne, plus particulièrement le long de la frontière allemande.",119,"fr:Communauté_germanophone_de_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Flag_of_the_German_Community_in_Belgium.svg/330px-Flag_of_the_German_Community_in_Belgium.svg.png"],["Q1124673",82,"region","Condroz","C","Le Condroz fait référence à une partie du territoire de Wallonie caractérisé par une géomorphologie en « tôle ondulée » du Moyen Plateau belge.",119,"fr:Condroz","c:c/c6/M%C3%A9an_JPG02.jpg"],["Q2145016",83,"region","Côte belge","C","La côte belge, en néerlandais Belgische Kust, en allemand Belgische Küste, est le nom généralement utilisé pour désigner la partie belge du littoral de la mer du Nord. Elle s'étend sur 65 kilomètres, de La Panne à Knokke-Heist. Particulièrement urbanisée, on y recense de nombreux immeubles à appartements. La côte belge compte 19 stations balnéaires plus la réserve naturelle du Zwin, à Knokke, et la réserve naturelle du Westhoek, à La Panne.",111,"fr:Côte_belge","c:5/52/K%C3%BCste%2C_Belgien_07.jpg"],["Q15900643",84,"region","Entre-Sambre-et-Meuse","C","L'Entre-Sambre-et-Meuse est une région naturelle de Wallonie, dans la partie méridionale de la Belgique. Elle comprend les villages et communes situés au sud de la Sambre et à l'ouest de la Meuse. Elle est arbitrairement limitée par la frontière française. N'étant pas administrative, la région n'a pas une superficie clairement déterminée. Certaines communes en faisant partie comprennent des entités se trouvant des deux côtés de la Sambre ou de la Meuse. On estime cependant sa superficie à 2 200 km2.","L'Entre-Sambre-et-Meuse est une région naturelle de Wallonie, dans la partie méridionale de la Belgique.","fr:Entre-Sambre-et-Meuse","c:8/8f/Daussois_JPG01a.jpg"],["Q37620",85,"region","Escaut","PC","L'Escaut est un fleuve européen de 355 km de long, qui traverse trois pays, avant de se jeter en mer du Nord.",null,"fr:Escaut","c:f/f1/Tournai_JPG05c.jpg",{"cats":["belgique","geo"]}],["Q1395106",86,"region","Famenne","C","La Famenne est une région naturelle de Belgique qui fait partie de l'ensemble plus vaste que l'on appelle Fagne-Famenne.",null,"fr:Famenne","c:b/bd/Nettinne_060124.JPG"],["Q599193",87,"region","Hautes Fagnes","PC","Les Hautes Fagnes sont un plateau du massif ardennais qui s'étend en Belgique dans la Région wallonne et, en Allemagne, dans les Länder de Rhénanie-Palatinat et Rhénanie-du-Nord-Westphalie.",119,"fr:Hautes_Fagnes","c:d/d7/0_Xhoffraix_-_Grande-Fagne_%28Tr%C3%B4s_Br%C3%B4li%29_et_caillebotis_de_La_Vecqu%C3%A9e_%285%29.jpg"],["Q932205",88,"region","Hesbaye","C","La Hesbaye est une région naturelle de Belgique s'étendant sur les provinces du Brabant flamand, du Brabant wallon, de Liège, de Limbourg, de Namur et, très brièvement, de Hainaut.",118,"fr:Hesbaye","c:d/df/Lens-Saint-Servais_-_Wet_meadows.jpg"],["Q617270",89,"region","Lacs de l'Eau d'Heure","C","Les lacs de l'Eau d'Heure sont situés en Wallonie sur le cours de la rivière Eau d'Heure, à cheval sur les provinces de Hainaut et de Namur.",119,"fr:Lacs_de_l'Eau_d'Heure","c:b/bf/Barrage_de_la_plate_taille_1.jpg"],["Q41986",90,"region","Meuse","R","La Meuse est un fleuve européen qui prend sa source en France et se jette dans la mer du Nord après un cours long d'approximativement 950 kilomètres traversant la France, la Belgique et les Pays-Bas. Son bassin est relativement étroit et est orienté sud-nord bien que, entre Namur et Liège, son cours soit orienté ouest-est et est-ouest depuis un de ses affluents, la Niers, jusqu'à la mer du Nord. Elle prend sa source à 409 mètres d’altitude dans la commune du Châtelet-sur-Meuse.",113,"fr:Meuse_(fleuve)","c:3/32/Meuse_Montherme.jpg",{"cats":["belgique","geo"]}],["Q160698",91,"region","Ourthe","C","L'Ourthe est une rivière de Belgique, affluent en rive droite de la Meuse. C'est une rivière issue de la confluence de l'Ourthe orientale et de l'Ourthe occidentale, toutes deux dans la province de Luxembourg en Belgique.","L'Ourthe est une rivière de Belgique, affluent en rive droite de la Meuse.","fr:Ourthe_(rivière)","c:b/be/Durbuy_-_L%27Ourthe_et_le_ch%C3%A2teau.jpg"],["Q3373444",92,"region","Pays de Charleroi","C","Le Pays de Charleroi est une région de la province de Hainaut. Il comprend les communes suivantes: Aiseau-Presles, Charleroi, Châtelet, Courcelles, Farciennes, Fleurus, Fontaine-l'Évêque, Gerpinnes, Les Bons Villers et Pont-à-Celles. Il était aussi anciennement nommé Pays Noir en référence à ses mines de charbon.","Le Pays de Charleroi est une région de la province de Hainaut.","fr:Pays_de_Charleroi","c:5/5b/Charleroi_vu-depuis-Couillet.JPG",{"cats":["belgique","geo"]}],["Q1129",93,"region","Province de Hainaut","PC","La province de Hainaut, couramment appelée le Hainaut, est une province de l'ouest de la Belgique située en Région wallonne.",114,"fr:Province_de_Hainaut","https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Generieke_vlag_van_Henegouwen.svg/330px-Generieke_vlag_van_Henegouwen.svg.png",{"cats":["belgique","geo"]}],["Q1127",94,"region","Province de Liège","PC","La province de Liège est une province belge située dans l'Est de la Région wallonne; elle est placée sous la tutelle de cette dernière. Sa frange Est, frontalière avec l'Allemagne, constitue la Communauté germanophone tandis que le reste de son territoire fait partie de la Communauté française.",119,"fr:Province_de_Liège","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Flag_of_the_Province_of_Li%C3%A8ge.svg/330px-Flag_of_the_Province_of_Li%C3%A8ge.svg.png",{"cats":["belgique","geo"]}],["Q1126",95,"region","Province de Luxembourg","PC","La province de Luxembourg est une province belge de la Région wallonne située à l'extrême sud du pays et limitrophe du Luxembourg.",118,"fr:Province_de_Luxembourg","https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Flag_of_the_Province_of_Luxembourg_%28Belgium%29.svg/330px-Flag_of_the_Province_of_Luxembourg_%28Belgium%29.svg.png",{"cats":["belgique","geo"]}],["Q1125",96,"region","Province de Namur","C","La province de Namur est une province de Belgique située en Région wallonne.",null,"fr:Province_de_Namur","https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Flag_of_Namur_Province.svg/330px-Flag_of_Namur_Province.svg.png",{"cats":["belgique","geo"]}],["Q1122",97,"region","Province du Brabant wallon","PC","Le Brabant wallon, souvent appelé par son sigle BW, est une province de Belgique située en Région wallonne. La province possède des armoiries qui lui ont été octroyées le 2 janvier 1995. Le lion est inspiré des armoiries historique du duché de Brabant. Les deux coqs sont le symbole de la Communauté française de Belgique.","Le Brabant wallon, souvent appelé par son sigle BW, est une province de Belgique située en Région wallonne.","fr:Province_du_Brabant_wallon","https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Drapeau_Province_BE_Brabant_Wallon.svg/330px-Drapeau_Province_BE_Brabant_Wallon.svg.png",{"cats":["belgique","geo"]}],["Q240",98,"region","Région de Bruxelles-Capitale","L","La Région de Bruxelles-Capitale (/ʁeʒjɔ̃ də bʁysɛlkapital/; en néerlandais: Brussels Hoofdstedelijk Gewest, /ˈbrʏsəls ˌɦoːfˈsteːdələk ɣəˈʋɛst/ ), ou Région bruxelloise, est l'une des trois régions qui composent la Belgique. Elle ne doit pas être confondue avec la ville de Bruxelles, qui n'est qu'une des dix-neuf communes de la région de Bruxelles-Capitale, ni avec la région bilingue de Bruxelles-Capitale.",117,"fr:Région_de_Bruxelles-Capitale","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Flag_of_the_Brussels-Capital_Region.svg/330px-Flag_of_the_Brussels-Capital_Region.svg.png",{"cats":["belgique","geo"]}],["Q9337",99,"region","Région flamande","R","La Région flamande, communément appelée Flandre, est l'une des trois régions de Belgique créées par la loi spéciale du 8 août 1980 à la suite de la première réforme de l'État belge datant, elle, du 24 décembre 1970.",118,"fr:Région_flamande","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Flag_of_Flanders.svg/330px-Flag_of_Flanders.svg.png",{"cats":["belgique","geo"]}],["Q208267",100,"region","Sambre","C","La Sambre est une rivière franco-belge, affluent de la Meuse, de 190 km de long. Elle fait partie du District hydrographique international de la Meuse.","La Sambre est une rivière franco-belge, affluent de la Meuse, de 190 km de long.","fr:Sambre","c:f/fa/Charleroi_-_2019-08-24_-_05_-_quai_Arthur_Rimbaud_et_quai_de_Sambre.jpg",{"cats":["belgique","geo"]}],["Q303621",101,"region","Semois","C","La Semois ou Semoy est une rivière de Belgique et de France, affluent en rive droite de la Meuse. Elle prend ses sources à Arlon en Belgique, traverse la Lorraine et l’Ardenne suivant une direction ouest-nord-ouest, franchit la frontière française et se jette dans la Meuse à Monthermé.","La Semois ou Semoy est une rivière de Belgique et de France, affluent en rive droite de la Meuse.","fr:Semois","c:9/9b/Bouillon_JPG01B.JPG"],["Q322824",102,"region","Signal de Botrange","PC","Le signal de Botrange est, depuis 1919, le point culminant de la Belgique à une altitude de 694 mètres. Il se trouve sur le plateau des Hautes Fagnes, dans le Massif ardennais, dans la province de Liège en Wallonie, dans la commune de Waimes. Sa situation lui vaut un rude climat, enregistré par une station météorologique.","Le signal de Botrange est, depuis 1919, le point culminant de la Belgique à une altitude de 694 mètres.","fr:Signal_de_Botrange","c:e/e4/Signal_de_Botrange%2C_communicatiemast_boven_op_de_berg_foto5_2017-03-28_11.58.jpg",{"cats":["belgique","geo"]}],["Q83078",103,"region","Wallonie","C","La Wallonie est une région du sud de la Belgique. Elle appartient presque intégralement au domaine linguistique roman et est, de ce fait, fréquemment qualifiée de « terre romane » par opposition au domaine linguistique germanique de la Flandre.","La Wallonie est une région du sud de la Belgique.","fr:Wallonie","https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Flag_of_Wallonia.svg/330px-Flag_of_Wallonia.svg.png"],["Q333912",104,"monument","Abbaye de Floreffe","C","L'abbaye de Floreffe est un établissement monastique fondé en 1121 et supprimé en 1796. L'édifice est situé sur un promontoire dominant la Sambre, sur la commune de Floreffe, en Belgique.","L'abbaye de Floreffe est un établissement monastique fondé en 1121 et supprimé en 1796.","fr:Abbaye_de_Floreffe","c:f/f1/Floreffe_-_Abbaye_et_village_%281%29.JPG"],["Q2719216",105,"monument","Abbaye de Maredsous","C","L'abbaye de Maredsous est un monastère bénédictin situé à Maredsous, dans la commune de Anhée, en province de Namur. Elle a été fondée sous la forme d'un prieuré le 15 novembre 1872 par l'abbaye de Beuron, avec l'appui financier de la famille Desclée, qui fit don des terres, paya les plans et la construction des bâtiments dessinés par l'architecte Jean-Baptiste Bethune. Son église abbatiale est érigée en basilique Saint-Benoît en 1926.","L'abbaye de Maredsous est un monastère bénédictin situé à Maredsous, dans la commune de Anhée, en province de Namur.","fr:Abbaye_de_Maredsous","c:2/28/Church_Maredsous_Abbey_03.JPG"],["Q1493708",106,"monument","Abbaye de Villers","C","L'abbaye de Villers, dont le nom canonique est « abbaye de Villers-en-Brabant », parfois improprement appelée « abbaye de Villers-la-Ville », est une abbaye de l'ordre de Cîteaux ayant existé entre 1146 et la Révolution française.",118,"fr:Abbaye_de_Villers","c:d/d1/%C3%89glise_abbatiale.jpg",{"cats":["belgique","urbex"]}],["Q334099",107,"monument","Abbaye Notre-Dame d'Orval","C","L'abbaye Notre-Dame d'Orval est un monastère cistercien situé en Belgique, à Villers-devant-Orval, dans la province de Luxembourg.",118,"fr:Abbaye_Notre-Dame_d'Orval","c:3/3a/Abbaye_d%27Orval_-_Cour_d%27honneur_1.jpg"],["Q99495",108,"monument","Ascenseur de Strépy-Thieu","E","L’ascenseur de Strépy-Thieu est un ascenseur à bateaux double situé en Belgique, sur le canal du Centre en Région wallonne dans la province de Hainaut.",113,"fr:Ascenseur_de_Strépy-Thieu","c:d/da/Aerial_view_of_Str%C3%A9py-Thieu_boat_lift_6.jpg"],["Q99372",109,"monument","Ascenseurs à bateaux du canal du Centre","C","Les ascenseurs à bateaux du canal du Centre sont quatre ascenseurs à bateaux hydrauliques construits en Belgique entre 1888 et 1917. Ils permettent de compenser ensemble une dénivellation de 66 mètres. De ces quatre ascenseurs, le premier permet de rattraper une dénivellation de 15,40 mètres, les trois autres de 16,93 mètres chacun. Le site des quatre ascenseurs du canal du Centre, dans les communes de La Louvière et du Rœulx, a été inscrit sur la liste du patrimoine mondial de l'Unesco en 1998.",118,"fr:Ascenseurs_à_bateaux_du_canal_du_Centre","c:c/c4/Canal_du_Centre_historique_-_Ascenseur_n%C2%B0_1_-_2022-06-07_-_02.jpg",{"cats":["belgique","urbex"]}],["Q846006",111,"monument","Basilique du Sacré-Cœur de Bruxelles","C","La basilique nationale du Sacré-Cœur, familièrement appelée basilique de Koekelberg car sise sur le plateau de Koekelberg, est un édifice religieux catholique situé à cheval sur les communes de Koekelberg et de Ganshoren, dans la Région de Bruxelles-Capitale, en Belgique. Conçue au début du XXe siècle comme monument national, et après la Première Guerre mondiale, comme centre de pèlerinage au Sacré-Cœur, la basilique de style « Art déco » ne fut formellement consacrée que les 13 et 14 octobre 1951.",110,"fr:Basilique_du_Sacré-Cœur_de_Bruxelles","c:0/05/Bruxelles_-_Basilique_Nationale_du_Sacr%C3%A9-C%C5%93ur_%C3%A0_Koekelberg_%285%29.jpg",{"cats":["belgique","religions","architecture"]}],["Q2441211",112,"monument","Beffroi de Bruges","C","Le beffroi de Bruges est une haute tour médiévale surmontant la Halle aux draps sur la Grand-Place de la ville de Bruges, dans la province de Flandre-Occidentale en Belgique. C'est un monument civil, construit en plusieurs étapes du XIIIe au XVe siècle, qui fut le symbole de l'indépendance communale de Bruges, importante cité commerçante au Moyen Âge. Il est classé au patrimoine mondial de l'UNESCO avec d'autres beffrois de Belgique et de France.",113,"fr:Beffroi_de_Bruges","c:3/37/Brugge_Belfort_HDR.jpg"],["Q1850707",113,"monument","Beffroi de Mons","C","Le beffroi de Mons est un bâtiment historique de la ville de Mons, en Belgique. Ce beffroi, classé depuis le 15 janvier 1936, relève du Patrimoine majeur de Wallonie et fait partie des beffrois de Belgique et de France reconnus en tant que patrimoine mondial de l'Humanité par l'Unesco depuis le 1er décembre 1999. Il est le seul de style baroque reconnu par l'UNESCO. Mesurant 87 mètres, il constitue le point culminant de la ville, construite sur une colline comme son nom l'indique.","Le beffroi de Mons est un bâtiment historique de la ville de Mons, en Belgique.","fr:Beffroi_de_Mons","c:6/64/0_Mons_-_Beffroi_%281%29.JPG",{"cats":["belgique","geo"]}],["Q1884030",114,"monument","Beffroi de Namur","C","Le beffroi de Namur, également appelé tour Saint-Jacques, est un bâtiment historique de la ville de Namur, capitale de la Wallonie, en Belgique. La tour, construite vers 1388 comme partie de l’enceinte de la ville devint beffroi en 1746. Il est un des 56 Beffrois de Belgique et de France classés au patrimoine mondial de l’UNESCO.",118,"fr:Beffroi_de_Namur","c:c/c9/Namur_Belfry_02.JPG"],["Q1832013",115,"monument","Bellewaerde","C","Bellewaerde est un parc d'attractions et un parc zoologique belge flamand, situé dans la province de Flandre-Occidentale, à Ypres. Fondé par Albert Florizoone sous le nom de Centre touristique de Bellewaerde en 1954 sur l'un des sites de la bataille d'Ypres de la Première Guerre mondiale, et nommé d'après le château qui se dresse encore près de l'entrée principale, il est aujourd'hui la propriété du groupe français la Compagnie des Alpes, filiale de la Caisse des dépôts et consignations.",100,"fr:Bellewaerde","c:2/29/Bellewaerde_%28ingang_1%29.jpg",{"cats":["belgique","parcs"]}],["Q891068",116,"monument","Bois du Cazier","C","Le Bois du Cazier est un lieu-dit de Marcinelle, près de Charleroi, en Belgique.",null,"fr:Bois_du_Cazier","c:1/13/Marcinelle_-_Bois_du_Cazier_-_2018-04-22_-_01.jpg",{"cats":["belgique","histoire","urbex"]}],["Q31985",117,"monument","Butte du Lion","PC","La Butte du Lion, érigée sous le nom de Monument de Waterloo, constituée d'un imposant tertre de terre surmonté d'un colossal Lion belgique, est un monument érigé en 1826 pour éterniser la gloire nationale, sur le site de la bataille de Waterloo, à Braine-l'Alleud, à la demande du roi Guillaume Ier des Pays-Bas qui voulut marquer l'endroit présumé où son fils ainé, le prince Guillaume II, fut blessé à l'épaule à la fin de la bataille.",116,"fr:Butte_du_Lion","c:3/3f/Domaine_du_champ_de_bataille_de_Waterloo_13_02.jpg"],["Q821009",118,"monument","Bâtiment Berlaymont","C","Le bâtiment Berlaymont est le siège de la Commission européenne, à Bruxelles, au carrefour de la rue de la Loi et du boulevard Charlemagne. Il abrite les bureaux du président de la Commission européenne et des vingt-sept commissaires européens.",116,"fr:Bâtiment_Berlaymont","c:d/d2/Belgique_-_Bruxelles_-_Schuman_-_Berlaymont_-_01.jpg",{"cats":["belgique","architecture"]}],["Q265453",119,"monument","Béguinages flamands","C","Les béguinages flamands sont des ensembles de maisons où vivaient les béguines, des femmes laïques religieuses. Treize d'entre eux sont classés au patrimoine mondial de l'UNESCO depuis 1998.",111,"fr:Béguinages_flamands","c:8/8a/Street_in_the_groot_begijnhof.jpg"],["Q5901",120,"monument","Cathédrale Notre-Dame d'Anvers","PC","La cathédrale Notre-Dame à Anvers en Belgique, dédiée à la Vierge Marie, est la cathédrale du diocèse du même nom. Construite de 1352 à 1521 elle est un des cinq monuments religieux majeurs de la ville d'Anvers avec l’église Saint-Charles-Borromée, l’église Saint-André, l’église Saint-Jacques et l’église Saint-Paul.","La cathédrale Notre-Dame à Anvers en Belgique, dédiée à la Vierge Marie, est la cathédrale du diocèse du même nom.","fr:Cathédrale_Notre-Dame_d'Anvers","c:6/6e/Antwerp_-_Cathedral_of_Our_Lady.jpg"],["Q391229",121,"monument","Cathédrale Notre-Dame de Tournai","C","La cathédrale Notre-Dame de Tournai est un édifice religieux catholique sis au cœur du centre historique de la ville de Tournai, en Belgique. Elle est le siège du diocèse de Tournai et le seul bâtiment de culte belge construit dès l’origine comme cathédrale. Chef-d'œuvre de l'art roman scaldien et de l'art gothique scaldien, ce monument est, par l'alliance harmonieuse des styles roman et gothique, par sa taille et son architecture caractéristique, un des témoins les plus impressionnants de l'art d'Occident.",119,"fr:Cathédrale_Notre-Dame_de_Tournai","c:1/1c/Tournai_JPG000c.jpg"],["Q1726584",122,"monument","Cathédrale Saint-Aubain de Namur","C","La cathédrale Saint-Aubain située à Namur est un édifice religieux catholique de style néo-classique qui est l'église épiscopale et siège du diocèse de Namur. Remplaçant une collégiale du XIe siècle devenue cathédrale en 1559 et sise sur la place Saint-Aubain, la cathédrale fut construite à partir de 1751, son édification se terminant en 1767. La consécration eut lieu le 20 septembre 1772. Son saint patron est Alban de Mayence. Elle est inscrite au patrimoine majeur de Wallonie.",117,"fr:Cathédrale_Saint-Aubain_de_Namur","c:2/25/Namur_Belgium_Cath%C3%A9drale-Saint-Aubain-02.jpg"],["Q269654",123,"monument","Cathédrale Saints-Michel-et-Gudule de Bruxelles","PC","La cathédrale Saints-Michel-et-Gudule située à Bruxelles, en Belgique, est la cocathédrale de l'archidiocèse catholique de Malines-Bruxelles. Elle est dédiée à saint Michel et à sainte Gudule, saints patrons de la ville de Bruxelles, et est un exemple reconnaissable du gothique brabançon.",119,"fr:Cathédrale_Saints-Michel-et-Gudule_de_Bruxelles","c:2/2a/Saints-Michel-et-Gudule_Luc_Viatour.jpg"],["Q815542",124,"monument","Centre belge de la bande dessinée","C","Le Centre belge de la bande dessinée, ou Musée de la BD, est un musée consacré à la bande dessinée. Il est installé à Bruxelles, rue des Sables, dans le bâtiment art nouveau conçu par Victor Horta en 1906 pour abriter les grands magasins de tissus Waucquez.","Le Centre belge de la bande dessinée, ou Musée de la BD, est un musée consacré à la bande dessinée.","fr:Centre_belge_de_la_bande_dessinée","c:f/fb/Brussel_-_Zandstraat_20_-_Belgisch_Stripcentrum_in_het_voormalig_Waucquez-warenhuis_%281903_door_Victor_Horta%29_20230826.jpg"],["Q567525",125,"monument","Château de Bouillon","C","Le château de Bouillon est un château fort construit au Moyen Âge situé en Wallonie dans la ville belge de Bouillon en province de Luxembourg.",118,"fr:Château_de_Bouillon","c:a/af/Bouillon_Castle_34.jpg"],["Q930363",126,"monument","Château de Freÿr","C","Le château de Freÿr, ou encore château de Freÿr-sur-Meuse, est un édifice situé à Freÿr, hameau de la commune belge d'Hastière, le long de la Meuse, entre Waulsort et Dinant. Le château, ses jardins et les rochers de Freÿr sur l'autre rive forment un des plus beaux sites de Belgique.",115,"fr:Château_de_Freÿr","c:a/aa/Fre%C3%BFr_Castle_R01.jpg"],["Q287806",127,"monument","Château de Gaesbeek","C","Le château de Gaesbeek ou Gaasbeek se trouve au cœur du Pajottenland, à proximité de Bruxelles.",null,"fr:Château_de_Gaesbeek","c:1/1b/Binnenhof_kasteel_van_gaasbeek.jpg"],["Q2971064",128,"monument","Château de Walzin","PC","Le château de Walzin est un château belge situé en Wallonie dans le hameau condruzien de Walzin, dans l'ancienne commune de Dréhance en province de Namur.",112,"fr:Château_de_Walzin","c:c/cf/Ch%C3%A2teau_de_Walzin_%28DSCF7410%29.jpg",{"cats":["belgique","urbex"]}],["Q1543972",129,"monument","Château des comtes de Flandre","PC","Le château des comtes de Flandre est un château du Moyen Âge situé dans la ville belge de Gand, dans la province de Flandre-Orientale. Le château est un des hauts lieux touristiques de la ville. Il renferme une collection d'objets de l'époque, une salle de tortures, une crypte, un donjon, des oubliettes, une étable et les pièces de résidence des comtes.",115,"fr:Château_des_comtes_de_Flandre","c:f/fa/Chateau_des_comtes_de_Flandre_-_Gand.jpg"],["Q172851",130,"monument","Circuit de Spa-Francorchamps","R","Le circuit de Spa-Francorchamps est un circuit automobile situé à Francorchamps dans la province de Liège, en Belgique. Il accueille chaque année le Grand Prix de Belgique de Formule 1 et la course d'endurance des 24 Heures de Spa, ainsi que d'autres courses nationales et internationales.","Le circuit de Spa-Francorchamps est un circuit automobile situé à Francorchamps dans la province de Liège, en Belgique.","fr:Circuit_de_Spa-Francorchamps","https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/2022_F1_CourseLayout_Belgium.svg/330px-2022_F1_CourseLayout_Belgium.svg.png",{"cats":["belgique","f1","moto"]}],["Q2974385",131,"monument","Citadelle de Dinant","C","La citadelle de Dinant est une fortification militaire belge édifiée en 1818, à l'époque néerlandaise, dans le cadre de la construction de la barrière Wellington contre la France.",119,"fr:Citadelle_de_Dinant","c:f/fe/Citadelle_de_Dinant_pic3.JPG"],["Q2600730",132,"monument","Citadelle de Namur","C","La citadelle de Namur, à l'origine le château des comtes de Namur, est un ancien château fort puis citadelle situé dans la ville de Namur, dans la province du même nom en Belgique. Dominant la ville à la confluence de la Sambre et la Meuse, il s'agit d'une des plus grandes citadelles d'Europe et son vaste réseau de souterrains lui aurait valu d'être surnommée « La termitière de l'Europe » par Napoléon Ier.",119,"fr:Citadelle_de_Namur","c:2/2e/Namur_JPG07.jpg",{"cats":["belgique","geo"]}],["Q2228532",133,"monument","Collégiale Notre-Dame de Dinant","C","La Collégiale Notre-Dame de Dinant est un édifice religieux catholique sis en bord de Meuse à Dinant. Un premier édifice roman s'étant écroulé, il est remplacé au XIIIe siècle par un autre en style gothique. L'église est l'un des monuments les plus représentatifs de l'architecture gothique de style mosan qui s'est répandu dans l'ancienne principauté de Liège au XIIIe siècle.","La Collégiale Notre-Dame de Dinant est un édifice religieux catholique sis en bord de Meuse à Dinant.","fr:Collégiale_Notre-Dame_de_Dinant","c:a/a9/0_Dinant_-_Coll%C3%A9giale_N.-D._de_l%27Assomption_et_la_citadelle_%281%29.JPG"],["Q2984038",134,"monument","Collégiale Sainte-Begge d'Andenne","C","La collégiale Sainte-Begge est un édifice religieux catholique sis au cœur de la ville d'Andenne dans la province de Namur. De style néoclassique l'église est dédiée à Sainte-Begge, fondatrice du monastère auquel appartenaient les sept églises détruites pour permettre la construction de la collégiale.",116,"fr:Collégiale_Sainte-Begge_d'Andenne","c:7/75/Andenne_050802_%284%29.JPG"],["Q1491935",135,"monument","Galeries royales Saint-Hubert","C","Les galeries royales Saint-Hubert sont un complexe de trois passages commerciaux couverts à Bruxelles, capitale de la Belgique. Elles ont été conçues par l'architecte Jean-Pierre Cluysenaar et inaugurées en 1847. L'ensemble se compose de trois passages distincts: la galerie du Roi, la galerie de la Reine et la galerie des Princes. Couvertes sur toute leur longueur par un large vitrage en arcades, elles forment le plus ancien piétonnier de la ville.",117,"fr:Galeries_royales_Saint-Hubert","c:d/d8/Galeries_royales_Saint-Hubert_Bruxelles.JPG",{"cats":["belgique","architecture"]}],["Q800398",136,"monument","Gare d'Anvers-Central","PC","La gare d'Anvers-Central est une gare ferroviaire belge des lignes 12 d'Anvers-Central à Essen, 25 de Bruxelles-Nord à Anvers, 27 de Bruxelles-Nord à Anvers-Central et 59/1 d'Anvers-Central à Y Ouest-Berchem, située sur la place Reine Astrid à proximité du centre de la ville d'Anvers, chef-lieu de la province d'Anvers en Région flamande. Elle est considérée comme l'un des monuments les plus fastueux de Belgique et l'une des plus belles gares du monde.",118,"fr:Gare_d'Anvers-Central","c:7/76/Antwerpen-Centraal_aerial_4.jpg",{"cats":["belgique","transports"]}],["Q801116",137,"monument","Gare de Liège-Guillemins","C","La gare de Liège-Guillemins — appelée également la gare des Guillemins — est la principale des sept gares ferroviaires de la ville de Liège en Belgique. Elle est située au pied de la colline de Cointe.",118,"fr:Gare_de_Liège-Guillemins","c:4/4b/Li%C3%A8ge_Luik_L%C3%BCttich_%284411635751%29.jpg",{"cats":["belgique","transports","architecture"]}],["Q1025354",138,"monument","Grand-Hornu","C","Le Grand-Hornu est un ancien complexe industriel de charbonnages faisant partie de l'ancienne commune de Hornu, située dans la région du Borinage, à une dizaine de kilomètres à l'Ouest du centre de Mons, dans le Hainaut en Belgique. Ce site fait partie du patrimoine majeur de Wallonie. De style néoclassique, il compte aujourd'hui parmi les beaux témoignages architecturaux de l'ère industrielle et comprend une des plus anciennes cités ouvrières au monde.",118,"fr:Grand-Hornu","c:d/dc/0_Hornu_050322_%287%29.JPG",{"cats":["belgique","urbex"]}],["Q947295",139,"monument","Grand-Place d'Anvers","C","La Grand-Place est la place centrale de la ville d'Anvers, située dans le centre historique, à quelques centaines de mètres de l'Escaut.",116,"fr:Grand-Place_d'Anvers","c:c/cc/Grote_Markt_%28Antwerpen%29.jpg"],["Q215429",140,"monument","Grand-Place de Bruxelles","PC","La Grand-Place, Grand Place ou Grand'Place est la place centrale de la ville belge de Bruxelles. Elle est également appelée Grote Markt en néerlandais et Gruute Met en bruxellois.","La Grand-Place, Grand Place ou Grand'Place est la place centrale de la ville belge de Bruxelles.","fr:Grand-Place_de_Bruxelles","c:a/ae/Grand_Place_Bruselas_2.jpg",{"cats":["belgique","geo"]}],["Q571145",141,"monument","Grottes de Han","C","Les grottes de Han consistent en un ensemble de grottes situées en Wallonie à Han-sur-Lesse, section de la commune belge de Rochefort, en relation avec la rivière Lesse en Famenne, dans la région géologique appelée Calestienne.",114,"fr:Grottes_de_Han","c:4/4d/Grotten_van_Han_-_grot_1.jpg"],["Q1255327",142,"monument","Hôtel de ville de Bruxelles","C","L'hôtel de ville de Bruxelles est un édifice de style gothique et classique situé sur la Grand-Place de Bruxelles en Belgique, au sud de la place, face à la Maison du Roi.",116,"fr:Hôtel_de_ville_de_Bruxelles","c:1/13/Brussels%2C_townhall_oeg2043-00090_foto3_2015-06-07_08.38.jpg",{"cats":["belgique","architecture"]}],["Q2477151",143,"monument","Hôtel de ville de Charleroi","C","L'hôtel de ville de Charleroi est un vaste bâtiment éclectique mêlant classicisme et Art déco inauguré en 1936.",null,"fr:Hôtel_de_ville_de_Charleroi","c:0/0a/Charleroi_-_H%C3%B4tel_de_ville_vu_de_la_place_Charles_II_-_2019-06-01.jpg"],["Q2667833",144,"monument","Jardins d'Annevoie","C","Les jardins d'Annevoie constituent le parc du château d'Annevoie à Annevoie-Rouillon, commune d'Anhée dans la province de Namur en Belgique.",118,"fr:Jardins_d'Annevoie","c:b/b6/Annevoie_JA1bJPG.jpg"],["Q1067006",146,"monument","Mini-Europe","C","Mini-Europe est un parc de miniatures situé à Bruparck au pied de l’Atomium à Bruxelles.",null,"fr:Mini-Europe","https://upload.wikimedia.org/wikipedia/fr/thumb/0/00/Mini-Europe_logo.jpg/330px-Mini-Europe_logo.jpg"],["Q1865794",147,"monument","Mont des Arts","C","Le Mont des Arts est un ensemble urbain à Bruxelles. Il regroupe la Bibliothèque royale de Belgique, les Archives générales du Royaume, le Square - Brussels Meeting Centre et un jardin créé par l'architecte paysagiste René Pechère. Le Mont des Arts est situé entre le quartier royal dans sa partie haute et le quartier du centre en contrebas.","Le Mont des Arts est un ensemble urbain à Bruxelles.","fr:Mont_des_Arts","c:b/b4/Brussels_view_from_Mont_des_Arts%2C_Brussels%2C_Belgium_%28cropped%29.jpg"],["Q3247381",148,"monument","Montagne de Bueren","C","La montagne de Bueren est un escalier de 374 marches reliant le quartier Féronstrée et Hors-Château au Péri et à la citadelle en traversant les Coteaux dans la ville de Liège en Belgique.",115,"fr:Montagne_de_Bueren","c:a/a2/Montagne_de_Bueren_R01.jpg"],["Q1955717",149,"monument","Musée de la Photographie à Charleroi","C","Le musée de la Photographie à Charleroi, centre d'art contemporain de la Fédération Wallonie-Bruxelles, est un musée installé dans l'ancien carmel néo-gothique de Mont-sur-Marchienne.",116,"fr:Musée_de_la_Photographie_à_Charleroi","c:3/30/Charleroi_-_Mus%C3%A9e_de_la_photographie_-_nouvelle_aile_-_2.jpg"],["Q1131318",150,"monument","Musée des Instruments de musique de Bruxelles","C","Le musée des Instruments de musique de Bruxelles, fondé en 1877, est l'un des musées d'instruments de musique les plus importants au monde. Ses collections comptent près de 10 000 instruments, dont plus de 1 200 sont exposés dans les salles du musée.",118,"fr:Musée_des_Instruments_de_musique_de_Bruxelles","c:5/57/Old_England_facade%2C_Brussels_%28DSCF7544%29.jpg"],["Q19697920",151,"monument","Musée Félicien Rops","C","Le Musée provincial Félicien Rops est un musée monographique situé au cœur du quartier historique de Namur, ville natale de l'artiste Félicien Rops. Il retrace la carrière artistique du graveur et illustrateur, depuis les caricatures publiées dans le journal satirique Uylenspiegel jusqu'à la série des œuvres érotiques Les Sataniques, en passant par Un enterrement au pays wallon, Pornocrates et les Dames au pantin.",113,"fr:Musée_Félicien_Rops","c:a/a4/Mus%C3%A9e_F%C3%A9licien_Rops_%C3%A0_Namur.JPG"],["Q1547331",152,"monument","Musée Hergé","C","Le musée Hergé est un musée consacré à l'auteur belge de bandes dessinées Hergé, créateur des Aventures de Tintin, de Quick et Flupke et de Jo, Zette et Jocko, Popol et Virginie et de Totor, CP des Hanetons.",117,"fr:Musée_Hergé","https://upload.wikimedia.org/wikipedia/fr/thumb/8/83/Musee_herge.svg/330px-Musee_herge.svg.png"],["Q943581",153,"monument","Musée Magritte","C","Le musée Magritte est une section des musées royaux des Beaux-Arts de Belgique logée dans l'hôtel du Lotto, un édifice qui fait partie du vaste ensemble architectural de style néo-classique de la place Royale de Bruxelles.",118,"fr:Musée_Magritte","c:d/dc/Belgique_-_Bruxelles_-_H%C3%B4tel_du_Lotto_-_02.JPG"],["Q779703",154,"monument","Musée royal de l'Afrique centrale","C","Le musée royal de l’Afrique centrale (néerlandais: Koninklijk Museum voor Midden-Afrika, allemand: Königliches Museum für Zentralafrika), communicant sous le nom AfricaMuseum depuis 2018, est un établissement scientifique fédéral belge situé en Brabant flamand dans le parc de Tervueren, dans la périphérie de Bruxelles.",117,"fr:Musée_royal_de_l'Afrique_centrale","c:b/bd/Tervuren_AfricaMuseum_17_Oktober_2026.jpg"],["Q377500",155,"monument","Musées royaux des Beaux-Arts de Belgique","C","Les musées royaux des Beaux-Arts de Belgique, situés à Bruxelles, conservent quelque vingt mille œuvres, peintures, sculptures et dessins. Ils intègrent quatre musées: le musée Old Masters, antérieurement appelé « musée royal d'Art ancien »; le musée Magritte; le musée Wiertz et le musée Meunier.",115,"fr:Musées_royaux_des_Beaux-Arts_de_Belgique","c:e/eb/Mus%C3%A9es_Royaux_des_Beaux-Arts_Belgique_1101.jpg"],["Q2154395",156,"monument","Pairi Daiza","R","Pairi Daiza est un parc zoologique belge wallon situé dans la province de Hainaut, à Brugelette. Fondé en 1994, il s'est d'abord appelé Paradisio de son ouverture jusqu'en 2010. Il est la propriété d’Éric Domb, fondateur du parc, et de Marc Coucke.","Pairi Daiza est un parc zoologique belge wallon situé dans la province de Hainaut, à Brugelette.","fr:Pairi_Daiza","https://upload.wikimedia.org/wikipedia/fr/thumb/d/dc/Logo_pairiDaiza.jpg/330px-Logo_pairiDaiza.jpg",{"cats":["belgique","parcs"]}],["Q850537",157,"monument","Palais de justice de Bruxelles","PC","Le palais de justice de Bruxelles est un imposant bâtiment de style éclectique et d'inspiration gréco-romaine situé sur la place Poelaert à Bruxelles. Il est le siège de l'arrondissement judiciaire de Bruxelles, ainsi que de plusieurs cours et tribunaux, dont la Cour de cassation, la Cour d'assises, la Cour d'appel de Bruxelles, le Tribunal de première instance de Bruxelles et enfin l'Ordre des avocats de Bruxelles.",119,"fr:Palais_de_justice_de_Bruxelles","c:5/57/Palais_de_Justice_from_Hilton.jpg",{"cats":["belgique","architecture","urbex"]}],["Q2285837",158,"monument","Palais des Beaux-Arts de Bruxelles","C","Le palais des Beaux-Arts de Bruxelles, aussi connu sous la marque Bozar, est l'une des trois institutions culturelles fédérales de Belgique. Cet espace pluridisciplinaire bruxellois est conçu pour rassembler un large éventail d’événements artistiques, qu’il s’agisse de musique, d’arts plastiques, de théâtre, de danse, de littérature, de cinéma ou d’architecture.",117,"fr:Palais_des_Beaux-Arts_de_Bruxelles","c:2/2b/BOZAR_%28DSCF7462%29.jpg"],["Q704698",159,"monument","Palais des princes-évêques de Liège","C","Le palais des princes-évêques de Liège ou palais épiscopal de Liège, se situe sur la place Saint-Lambert dans le centre de Liège. Le palais actuel, devenu le palais de justice de Liège, a été reconstruit au XVIe siècle à l'initiative du cardinal Érard de La Marck, à l'emplacement d'un ancien édifice détruit lors du sac de Charles le Téméraire. Une nouvelle aile néo-gothique, le palais provincial, est construit entre 1849 et 1853.",119,"fr:Palais_des_princes-évêques_de_Liège","c:8/8a/Prinsbisschoppelijk_paleisLuik2010-02-04.jpg"],["Q635307",160,"monument","Palais royal de Bruxelles","PC","Le palais royal de Bruxelles est le lieu de travail et de réception du roi des Belges, située au cœur de la capitale belge. Il abrite notamment les services de la maison du roi, rassemblant les équipes de collaborateurs du souverain nécessaires à l'exercice de ses fonctions, mais sert aussi de lieu de réception pour les réceptions d'ambassadeurs et d'invités de marque, ainsi que pour les autres festivités ou activités de la monarchie.",116,"fr:Palais_royal_de_Bruxelles","c:e/e3/Palacio_Real%2C_Bruselas%2C_B%C3%A9lgica%2C_2021-12-15%2C_DD_55.jpg",{"cats":["belgique","geo"]}],["Q1101790",161,"monument","Parc du Cinquantenaire","C","Le parc du Cinquantenaire est un parc dans l'extension est de la ville de Bruxelles, en Belgique. Il est aménagé autour d'un arc monumental à trois arches appelées les arcades du Cinquantenaire.","Le parc du Cinquantenaire est un parc dans l'extension est de la ville de Bruxelles, en Belgique.","fr:Parc_du_Cinquantenaire","c:4/42/Parc_du_Cinquantenaire_30-05-06.JPG",{"cats":["belgique","architecture"]}],["Q99464",162,"monument","Plan incliné de Ronquières","C","Le plan incliné de Ronquières est un ascenseur à bateaux près de Ronquières, dans la province de Hainaut. Situé sur le parcours du canal Charleroi-Bruxelles, il permet de faire glisser un bac contenant une ou plusieurs péniches en vue de leur faire franchir un dénivelé important. Le plan incliné a été mis en service en 1968.","Le plan incliné de Ronquières est un ascenseur à bateaux près de Ronquières, dans la province de Hainaut.","fr:Plan_incliné_de_Ronquières","c:f/f8/Infographie_plan_inclin%C3%A9_%28haute_d%C3%A9finition%29.png"],["Q1414854",163,"monument","Plopsaland Belgium","C","Plopsaland Belgium, anciennement Plopsaland De Panne ou Plopsaland La Panne, est un parc d'attractions belge situé à Adinkerque dans la commune de La Panne, dans la Province de Flandre-Occidentale. Le parc est ouvert sous ce nom depuis le 29 avril 2000. Avant cette date, il se nommait Meli Park.",116,"fr:Plopsaland_Belgium","",{"cats":["belgique","parcs"]}],["Q326377",164,"monument","Pont de Jambes","C","Le pont de Jambes, de son vrai nom « pont de Meuse », est un très ancien pont en maçonnerie enjambant la Meuse entre Jambes et le pied de la citadelle de Namur, en Belgique. Datant probablement de l’époque romaine, il a été plusieurs fois reconstruit et modifié. Long de 145 mètres, il compte aujourd’hui sept arches, dont celle du centre est plus large afin de permettre le passage de convois fluviaux. Devenu emblématique de l’ancienne ville de Jambes, il en orne le blason.",116,"fr:Pont_de_Jambes","c:b/bf/Namur_Pont_de_Jambes_R01.jpg"],["Q2769371",165,"monument","Rocher Bayard","C","Le rocher Bayard est une spectaculaire aiguille rocheuse d’une quarantaine de mètres de haut se trouvant en bord de Meuse, entre Dinant et Anseremme, dans la province de Namur. Associée à l’ancienne légende ardennaise des quatre fils Aymon, elle est une curiosité touristique importante de la région.",115,"fr:Rocher_Bayard","c:0/01/RocherBayardDinant.JPG"],["Q1644661",166,"monument","Serres royales de Laeken","C","Les serres royales de Laeken sont une construction architecturale composée de métal et de verre, réalisée par l'architecte Alphonse Balat dans le parc attenant au château royal de Laeken à l'initiative du roi Léopold II. Les serres sont officiellement inaugurées le 20 mai 1880.",109,"fr:Serres_royales_de_Laeken","c:9/98/Serres_Royales_de_Laeken_avec%2C_en_premier_plan%2C_le_jardin_d%27hiver.jpg"],["Q622671",167,"monument","Stade Roi Baudouin","PC","Le stade Roi Baudouin, d'abord appelé stade du Centenaire et parfois stade du Jubilé avant 1945 puis stade du Heysel jusqu'en 1993, est un stade multisports belge, souvent désigné comme le « stade national ».",116,"fr:Stade_Roi_Baudouin","c:a/a4/Stade_Roi_Baudouin.JPG",{"cats":["belgique","foot"]}],["Q819511",168,"monument","Terril","E","Un terril /tɛʁi/, un terri ou une halde est une colline artificielle formée par accumulation de résidus miniers produits par l'exploitation minière. Les débris rocheux provenant des charbonnages sont composés surtout de schistes houillers et, en plus petite quantité, de grès carbonifères et de résidus de charbon.",111,"fr:Terril","c:2/21/Mines_de_Plancher-les-Mines_%2811%29.JPG"],["Q24929435",169,"monument","Théâtre de Namur","C","Le théâtre royal de Namur est un théâtre à l'italienne situé à Namur, en Belgique. Construit en 1863, il est classé au Patrimoine civil public de Wallonie.","Le théâtre royal de Namur est un théâtre à l'italienne situé à Namur, en Belgique.","fr:Théâtre_de_Namur","c:c/c7/TheatredeNamur.jpg"],["Q15971959",170,"monument","Téléphérique de la Citadelle de Namur","C","Le Téléphérique de la Citadelle de Namur est un moyen de transport touristique inauguré le 8 mai 2021 reliant la place Maurice Servais à l'esplanade de la citadelle, le trajet se fait entre six minutes et neuf minutes selon affluence. Il succède plus de vingt ans après sa fermeture au précédent téléphérique dont le tracé était différent.",118,"fr:Téléphérique_de_la_Citadelle_de_Namur","c:5/55/Namur_-_T%C3%A9l%C3%A9ph%C3%A9rique_de_la_citadelle_de_Namur_%28A082%29.JPG"],["Q489313",171,"monument","Walibi Belgium","PC","Walibi Belgium est un parc d'attractions conçu par l'homme d'affaires belge Eddy Meeùs et qui a été inauguré le 26 juillet 1975. Il est localisé en Belgique sur des terrains situés dans les communes de Wavre, Limal et Bierges. Sa mascotte est un kangourou de couleur orange dénommé également Walibi, en référence au wallaby.",114,"fr:Walibi_Belgium","c:6/67/Walibi_Belgium_Entr%C3%A9e_pour_les_50_ans.jpg",{"cats":["belgique","parcs"]}],["Q1823577",172,"monument","Élysette","C","L’Élysette est le siège de la présidence du Gouvernement de Wallonie à Namur. Ce surnom lui a été donné à l’époque où son président entre 1992 et 1994, Guy Spitaels entretenait de bonnes relations avec l’Élysée.","L’Élysette est le siège de la présidence du Gouvernement de Wallonie à Namur.","fr:Élysette","c:7/7e/L%E2%80%99%C3%89lysette%2C_c%C3%B4t%C3%A9_Meuse.jpg"],["Q1884243",173,"plat","Anguille au vert","C","L'anguille au vert est un plat traditionnel belge, une spécialité principalement de la Région flamande autour de l'Escaut, entre Termonde et Anvers.",112,"fr:Anguille_au_vert","c:f/fa/Anguille_au_vert_P1320209.JPG",{"cats":["belgique","friterie"]}],["Q113291374",174,"plat","Babelutte","C","Une Babelutte est une sorte de caramel long aromatisé au miel ou à la cassonade originaire de Furnes dans le Westhoek.",null,"fr:Babelutte","c:3/3c/Jielbeaumadier_babeluttes_de_lille_2010.jpg",{"cats":["belgique","friterie"]}],["Q140635754",175,"plat","Bière belge","C","Les bières belges comptent parmi les plus variées et les plus nombreuses collections de bières dans le monde.",null,"fr:Bière_belge","c:e/ef/A_wall_of_Belgian_beer_bottles_at_the_Bruges_beer_experience.jpg"],["Q2921756",176,"plat","Boulet à la liégeoise","PC","Le boulet à la liégeoise est une spécialité culinaire traditionnelle belge de la région de Liège. C'est une préparation de viande hachée façonnée en grosses boulettes, qui sont dorées sur toutes leurs faces puis mijotées dans une sauce au sirop de Liège.","Le boulet à la liégeoise est une spécialité culinaire traditionnelle belge de la région de Liège.","fr:Boulet_à_la_liégeoise","c:0/05/Boulets_%C3%A0_la_li%C3%A9geoise_1.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q1027218",177,"plat","Callebaut","C","Callebaut est une entreprise et fabricant belge de chocolats, fondée en 1911 à Wieze, elle fusionne en 1996 avec le chocolatier français Barry pour former le groupe Barry Callebaut.",115,"fr:Callebaut","https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Postcard_Callebaut_Factory.tif/330px-Postcard_Callebaut_Factory.tif.png"],["Q138553",178,"plat","Carbonade flamande","R","La carbonade flamande, ou carbonnade à la flamande, est une recette de cuisine traditionnelle de la cuisine belge et franco-flamande, variante de carbonade à base de morceaux de viande braisés à l'étouffée avec de la bière belge ou du Nord-Pas-de-Calais.",116,"fr:Carbonade_flamande","c:8/82/Jielbeaumadier_carbonade_flamande_2010.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q33105701",179,"plat","Chimay","C","La Chimay est une bière trappiste belge, produite à l'abbaye Notre-Dame de Scourmont.",null,"fr:Chimay_(bière)","c:2/22/Chimay_3_beers.JPG",{"cats":["belgique","friterie"]}],["Q2964269",180,"plat","Chocolat belge","PC","Le chocolat belge est une spécialité gastronomique belge. Avec 500 chocolatiers et 2000 boutiques de chocolats en Belgique en 2015, le Belge consomme en moyenne 8 kilos de chocolat par personne et par an, l’un des taux les plus élevés dans le monde. La Belgique produit 650 000 tonnes de chocolat par an, la majorité destinée à l'exportation. C'est l'un des symboles de la qualité belge dans le monde.","Le chocolat belge est une spécialité gastronomique belge.","fr:Chocolat_belge","c:3/36/Belgian_chocolates.jpg",{"cats":["belgique","nourriture"]}],["Q2744746",181,"plat","Chouffe","C","La Chouffe est une bière blonde belge. Elle est produite en Wallonie par la Brasserie d'Achouffe, dans le village du même nom, en province de Luxembourg. Elle fait partie des blondes des Ardennes.","La Chouffe est une bière blonde belge.","fr:Chouffe","c:3/38/La_chouffe_et_son_verre.jpg",{"cats":["belgique","friterie"]}],["Q2740922",182,"plat","Cougnou","C","Le cougnou, appelé aussi cougnole dans certaines régions, mais également folard, quignole, queugnole, coquille ou pain de Jésus, est une viennoiserie typique de la Belgique et du nord de la France, consommée durant les périodes de la Saint-Nicolas et de Noël ainsi qu'à la Saint-Martin.",118,"fr:Cougnou","c:9/9b/Cougnou.jpg"],["Q2579351",183,"plat","Couque de Dinant","C","Spécialité de la ville belge dont elle porte le nom, la couque de Dinant est une sorte de biscuit extrêmement dur fait de miel et de farine, imprimé dans des moules en bois de poirier, de noyer et de hêtre selon des formes très variées: animaux, objets divers, personnages, motifs floraux, etc.",118,"fr:Couque_de_Dinant","c:5/5b/Couque_de_Dinant.jpg",{"cats":["belgique","friterie"]}],["Q3002088",184,"plat","Cramique","C","Le ou la cramique est un pain brioché belge fourré de raisins secs. C’est une recette qu’on retrouve, à l’origine, dans les trois régions de Belgique: la Flandre, la Wallonie et Bruxelles Capitale, ainsi que dans le Nord de la France et au Luxembourg.","Le ou la cramique est un pain brioché belge fourré de raisins secs.","fr:Cramique","c:c/c6/Kramiek.jpg"],["Q1142939",185,"plat","Cuberdon","PC","Le cuberdon est une friandise ou un bonbon de forme conique, traditionnel en Belgique.",null,"fr:Cuberdon","c:1/1c/Topneus.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q1150967",186,"plat","Côte d'Or","PC","Côte d'Or est une marque de chocolat belge faisant partie du groupe américain Mondelez International.",null,"fr:Côte_d'Or_(chocolat)","https://upload.wikimedia.org/wikipedia/fr/thumb/8/84/EXE_240118_CDO_LOGO_2018.jpg/330px-EXE_240118_CDO_LOGO_2018.jpg",{"cats":["belgique","marques","friterie"]}],["Q903559",187,"plat","Delirium Tremens","C","Delirium Tremens est une bière blonde belge, brassée par la brasserie Huyghe à Melle.",null,"fr:Delirium_Tremens_(bière)","c:7/7f/Delirium_Tremens_%28bi%C3%A8re%29.JPG"],["Q1773786",188,"plat","Duvel","C","La Duvel est une bière blonde de fermentation haute brassée par la brasserie Duvel en Belgique. Elle représente 85 % de la production de la brasserie, qui produit également les Maredsous et la Vedett. C'est une bière de type triple, dont le titre alcoolique est de 8,5 % en volume. L'étiquette recommande de la servir à une température comprise entre 6 et 10 °C, même si les amateurs de bières de fermentation haute boivent plutôt celles-ci à température de cave, entre 12 et 14 °C.","La Duvel est une bière blonde de fermentation haute brassée par la brasserie Duvel en Belgique.","fr:Duvel","c:d/de/Biere_Duvel.jpg",{"cats":["belgique","friterie"]}],["Q2963406",189,"plat","Endive au jambon","C","L’endive au jambon est un plat typique de Belgique, des Hauts-de-France et des Pays-Bas. Il se présente sous la forme d'un gratin d'endives enroulées dans des tranches de jambon.","L’endive au jambon est un plat typique de Belgique, des Hauts-de-France et des Pays-Bas.","fr:Endive_au_jambon","c:e/e8/Jielbeaumadier_chicon_au_jambon_maroilles_2010.jpg",{"cats":["belgique","friterie"]}],["Q1960572",190,"plat","Escavèche","C","Le terme escavèche désigne en Wallonie un mets de poisson conservé dans une sauce au vinaigre. Ce plat est une variante de ce que l'on appelle escabèche en dehors de la Belgique. La recette d'origine est à base d'anguille mais peut aussi se concevoir avec d'autres poissons tels que la truite ou le brochet. Dans la région de Momignies existe une variante à base de roussette de mer.","Le terme escavèche désigne en Wallonie un mets de poisson conservé dans une sauce au vinaigre.","fr:Escavèche","c:8/88/Escavetche_pot.jpg"],["Q749593",191,"plat","Filet américain","R","Le steak tartare ou tartare est une recette à base de viande de bœuf ou de viande de cheval crue, généralement hachée gros, ou coupée en petits cubes au couteau. La recette actuelle figure dans Le Guide culinaire d'Auguste Escoffier de 1903 sous le nom de « beefsteak à l'américaine ».",117,"fr:Steak_tartare","c:2/2a/Tartare_de_boeuf_charolais_01.jpg",{"cats":["belgique","nourriture"]}],["Q3073285",192,"plat","Flamiche","C","La flamiche est un type de tarte dans la cuisine traditionnelle de Belgique, du Nord de la France et de la Picardie. On en compte plusieurs parmi lesquelles:","La flamiche est un type de tarte dans la cuisine traditionnelle de Belgique, du Nord de la France et de la Picardie.","fr:Flamiche","c:a/a9/Tarte_Flamiche.jpg",{"cats":["belgique","friterie"]}],["Q1464898",193,"plat","Fricadelle","R","La fricadelle est une préparation à base de viande cuisinée, spécialité des Pays-Bas historiques. Au XXIe siècle, la fricadelle se présente généralement sous la forme de saucisses d'une quinzaine de centimètres de long. Elles sont souvent servies dans les friteries.","La fricadelle est une préparation à base de viande cuisinée, spécialité des Pays-Bas historiques.","fr:Fricadelle","c:d/da/Patat_met.jpg",{"cats":["belgique","friterie"]}],["Q152088",194,"plat","Frite","E","La frite est un bâtonnet de pomme de terre cuit par friture dans une graisse animale ou une huile végétale. Les appellations « pomme frite » et « patate frite » sont utilisées indifféremment pour ce bâtonnet, pour une tranche ou pour une rondelle du même végétal cuit de cette façon. La graisse de bœuf est utilisée pour la cuisson des frites en Belgique et dans le nord de la France.","La frite est un bâtonnet de pomme de terre cuit par friture dans une graisse animale ou une huile végétale.","fr:Frite","c:6/67/Fries_2.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q1814211",195,"plat","Friterie","C","Une friterie, aussi appelée fritkot, friture ou baraque à frites, est, en Belgique, dans le nord de la France et au Québec, un endroit où l'on sert des frites et des « snacks »: boulettes, fricadelles, cervelas, additionnés ou non de sauce d'accompagnement. Les friteries sont originaires de Belgique, ces lieux de restauration sont résidentiels ou mobiles. Les premières friteries étaient souvent mobiles. Ce n'est qu'après la Seconde Guerre mondiale que les friteries fixes sont devenues plus visibles dans la rue.",115,"fr:Friterie","c:3/36/Oud-Heverlee_frituur_B.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q614672",196,"plat","Fromage de Herve","C","Le fromage de Herve est un fromage belge, du territoire de l'Entre-Vesdre-et-Meuse, nommé pays de Herve, et portant le nom de la ville principale de cette région.",118,"fr:Fromage_de_Herve","c:4/49/Fromage-de-herve.jpg"],["Q3094784",197,"plat","Galler","C","Galler est une entreprise belge de chocolaterie et confiserie fondée en 1976 et dont le siège social est à Vaux-sous-Chèvremont, dans la commune de Chaudfontaine, près de Liège.",106,"fr:Galler","https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Galler_logo_2020.svg/330px-Galler_logo_2020.svg.png",{"cats":["belgique","friterie"]}],["Q1855212",198,"plat","Gaufre de Bruxelles","C","La gaufre de Bruxelles est une grande gaufre rectangulaire, très aérienne dont la recette fut créée au XVIIIe siècle. Celle-ci se mange chaude et peut être servie avec de la crème chantilly ou du sucre impalpable.","La gaufre de Bruxelles est une grande gaufre rectangulaire, très aérienne dont la recette fut créée au XVIIIe siècle.","fr:Gaufre_de_Bruxelles","c:8/8c/Waffle_DSC00575.jpg",{"cats":["belgique","friterie"]}],["Q2204257",199,"plat","Gaufre de Liège","PC","La gaufre de Liège ou gaufre de chasse, localement appelée « gaufre au sucre » ou wåfe en wallon, est une spécialité liégeoise de gaufre.",116,"fr:Gaufre_de_Liège","c:4/47/Gaufre_liege.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q931084",200,"plat","Godiva","PC","Godiva est une marque commerciale de confiseries et chocolats. Fondée en Belgique en 1926 par Pierre Draps, elle est aujourd'hui une marque internationale, avec une production en partie délocalisée en Turquie, et en Pennsylvanie pour le marché nord-américain. Les magasins de cette enseigne sont présents dans plusieurs grandes villes du monde comme Londres, Bruxelles, ou Tokyo.","Godiva est une marque commerciale de confiseries et chocolats.","fr:Godiva_(chocolatier)","c:d/d0/HK_Kln_Bay_Telford_Plaza_GODIVA_Chocolatier_a.jpg",{"cats":["belgique","marques","friterie"]}],["Q499532",201,"plat","Grammont","C","Grammont est une ville néerlandophone de Belgique située en Région flamande dans la province de Flandre-Orientale et le pays de la Dendre. Elle compte 35 236 habitants en 2025.",119,"fr:Grammont_(Belgique)","c:2/2e/Geraardsbergen-Grammont%28Belg%29.jpg"],["Q1546845",202,"plat","Grimbergen","C","La Grimbergen est une bière d'abbaye d'origine belge dont la production a été lancée à l'abbaye de Grimbergen au début du XVIIe siècle par les chanoines Prémontrés. Elle est produite et commercialisée par Alken-Maes et par Brasseries Kronenbourg.",118,"fr:Grimbergen_(bière)","c:c/c0/Grimbergen_beers.1.JPG"],["Q1520229",203,"plat","Gueuze","C","La gueuze est un type de bière obtenue à partir de l'assemblage de bières lambic. Des lambics jeunes et vieux sont mélangés et la bière subit une seconde fermentation.","La gueuze est un type de bière obtenue à partir de l'assemblage de bières lambic.","fr:Gueuze","c:c/c4/Mort_Subite._Gueuze.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q25388400",204,"plat","Hoegaarden","C","La Hoegaarden est une bière blanche originaire de Hoegaarden en Belgique. Elle est disponible dans plus de 70 pays. C'est une marque du groupe AB InBev, le plus gros brasseur du monde. Elle est produite à la Brasserie Hoegaarden.","La Hoegaarden est une bière blanche originaire de Hoegaarden en Belgique.","fr:Hoegaarden_(bière)","https://upload.wikimedia.org/wikipedia/fr/thumb/6/68/Hoegaarden_%28logo%29.png/330px-Hoegaarden_%28logo%29.png",{"cats":["belgique","friterie"]}],["Q153960",205,"plat","Jupiler","C","La Jupiler est une bière belge blonde de fermentation basse de type lager européen.",null,"fr:Jupiler","https://upload.wikimedia.org/wikipedia/fr/thumb/b/bf/Logo_bi%C3%A8re_Jupiler.jpg/330px-Logo_bi%C3%A8re_Jupiler.jpg",{"cats":["belgique","marques","friterie"]}],["Q1756073",206,"plat","Kriek","C","La kriek est une bière belge aromatisée avec des cerises acides. Traditionnellement il s'agit d'une lambic, bière de fermentation spontanée, mais la dénomination n'étant pas protégée toute bière aromatisée à la cerise peut être appelée kriek.","La kriek est une bière belge aromatisée avec des cerises acides.","fr:Kriek","c:a/a5/Kriek_Beer.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q2386515",207,"plat","Lacquemant","PC","Le lacquemant est une spécialité culinaire de la région liégeoise.",null,"fr:Lacquemant","c:f/fd/Lacquemant.jpg",{"cats":["belgique","friterie"]}],["Q526314",208,"plat","Lambic","PC","Le lambic est une bière de fermentation spontanée, en principe exclusivement produite dans la vallée de la Senne et dans le Pajottenland. C'est une bière plus ou moins acide selon son âge, sans pétillant ni mousse, et titrant environ 5 degrés d'alcool. Elle est consommée telle quelle et sert aussi de base pour la production du faro, de la gueuze et de la kriek.",115,"fr:Lambic","c:3/30/Bieren_uit_de_streek_rond_brussel.jpg",{"cats":["belgique","nourriture"]}],["Q1341618",209,"plat","Leffe","PC","La Leffe ou Abbaye de Leffe est une bière belge d'Abbaye reconnue, produite par la brasserie Artois à Louvain et faisant référence à l'abbaye Notre-Dame de Leffe où elle n'est plus brassée depuis la dissolution de la communauté prémontré à la fin du XVIIIe siècle.",112,"fr:Leffe_(bière)","c:5/56/Leffe_-_vieille_cuv%C3%A9e.jpg",{"cats":["belgique","marques"]}],["Q80335",210,"plat","Leonidas","C","Leonidas est une marque commerciale déposée de pralines belges, créée en 1913 par Léonidas Kestekides, qui appartient à la société d'industrie agroalimentaire Confiserie Leonidas. Un million de pralines sont confectionnées quotidiennement à Bruxelles, dans deux usines distinctes.",119,"fr:Leonidas_(chocolat)","c:9/93/Leonidas_Logo.JPG",{"cats":["belgique","marques"]}],["Q590113",211,"plat","Lotus Bakeries","R","Lotus Bakeries est une entreprise belge, dirigée par Karel Boone et spécialisée initialement dans le spéculoos. Aujourd'hui, elle décline aussi des produits à base de spéculoos et de frangipane, des pains d'épices, etc.","Lotus Bakeries est une entreprise belge, dirigée par Karel Boone et spécialisée initialement dans le spéculoos.","fr:Lotus_Bakeries","https://upload.wikimedia.org/wikipedia/fr/thumb/0/0c/Lotus_logo.svg/330px-Lotus_logo.svg.png",{"cats":["belgique","marques","friterie"]}],["Q1975036",212,"plat","Maredsous","C","La bière Maredsous est une bière belge de fermentation haute brassée pour les moines de l'abbaye de Maredsous par la brasserie Duvel.",116,"fr:Maredsous_(bière)","c:d/d3/Maredsous_blonde.jpg"],["Q2485491",213,"plat","Mitraillette","PC","La mitraillette est un mets constituée d'une demi-baguette contenant une viande cuite, servie chaude, des frites et de la sauce. C'est une préparation culinaire populaire très répandue dans les friteries et les snacks de Belgique.",118,"fr:Mitraillette_(cuisine)","c:0/03/Mitraillette.JPG"],["Q1200514",214,"plat","Moules-frites","PC","Les moules-frites sont une spécialité culinaire traditionnelle emblématique de la cuisine belge, nordiste, et néerlandaise, à base de moules marinières et de frites.",109,"fr:Moules-frites","c:5/5c/Moules_marini%C3%A8res_01.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q1813801",215,"plat","Neuhaus","C","Neuhaus est une société belge fondée en 1857 par Jean Neuhaus, un pharmacien venu de Suisse. Cette société vendait à l'origine des confiseries pharmaceutiques dans les galeries royales Saint-Hubert à Bruxelles. Pour améliorer le goût des médicaments vendus dans sa pharmacie, Frédéric Neuhaus décide de les enrober d'une couche de chocolat, dont les ventes vont progressivement augmenter. En 1912, son petit-fils développa cette idée en créant la première praline belge.","Neuhaus est une société belge fondée en 1857 par Jean Neuhaus, un pharmacien venu de Suisse.","fr:Neuhaus_(entreprise)","c:0/0b/Neuhaus_logo.jpg",{"cats":["belgique","marques"]}],["Q2199588",216,"plat","Nic-nac","C","Le nic-nac ou nic nac est un petit biscuit sec soit en forme de lettre soit rond au bord dentelé surmonté d'une rosace de sucre. Ces biscuits se vendent dans le commerce en Belgique, aux Pays-Bas et dans les Hauts-de-France.",118,"fr:Nic-nac","c:4/41/Nic-Nacs2.JPG"],["Q848355",217,"plat","Orval","C","L’Orval est une bière trappiste belge de fermentation haute, brassée à l'abbaye d'Orval située à Villers-devant-Orval dans la province de Luxembourg.",117,"fr:Orval_(bière)","c:4/40/Orval_bi.jpg"],["Q2626283",218,"plat","Pain à la grecque","C","Le pain à la grecque est une pâtisserie bruxelloise typique constituée par un simple rectangle de pain au lait, à la cassonade et à la cannelle, saupoudré de sucre cristallisé.",116,"fr:Pain_à_la_grecque","c:7/79/Pain_grecque.jpg",{"cats":["belgique","friterie"]}],["Q2782605",219,"plat","Pistolet","C","Le pistolet est un petit pain bruxellois, rond, fendu d’un léger sillon au sommet; il est destiné à une seule personne; on appelle aussi « pistolet » des petits pains ronds, ou allongés, dans d'autres régions de la Belgique.",119,"fr:Pistolet_(pain)","c:e/ed/Pistolets_bruxellois.jpg",{"cats":["belgique","friterie"]}],["Q2290274",220,"plat","Praline","C","Une praline, ou plus simplement petit chocolat ou chocolat, est un montage à base de chocolat. Il existe des pralines fourrées à la crème, à la crème au beurre, à la ganache, à la pâte pralinée, à la liqueur, au café, avec morceaux de fruits ou de fruits secs, au caramel, mais certaines ne sont faites que de chocolat ou, par exemple, de massepain. Elles sont souvent vendues dans des ballotins.","Une praline, ou plus simplement petit chocolat ou chocolat, est un montage à base de chocolat.","fr:Praline_(chocolat)","c:2/20/Pralines_cut.jpg"],["Q3142679",221,"plat","Péket","C","Le péket ou péquet est le nom wallon donné au genièvre de la même région en Belgique. Il s'agit donc d'un alcool de grain aromatisé de baies de genévrier. Il est distillé dans la région mosane, de Maastricht à Namur.","Le péket ou péquet est le nom wallon donné au genièvre de la même région en Belgique.","fr:Péket","c:1/1b/Tchantches3.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q3469465",222,"plat","Salade liégeoise","C","La salade liégeoise ou potée liégeoise, est une spécialité culinaire belge, originaire de la région de Liège.",null,"fr:Salade_liégeoise","c:0/0f/Salade_li%C3%A9geoise.jpg",{"cats":["belgique","friterie"]}],["Q2829733",223,"plat","Sauce andalouse","C","La sauce andalouse est:",null,"fr:Sauce_andalouse","c:4/47/Belgian_frites_with_andalouse_sauce.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q2258053",224,"plat","Sauce samouraï","C","La sauce samouraï est une sauce belge, assez relevée, servie traditionnellement avec des frites. Elle n'est pas, comme son nom pourrait le faire croire, originaire du Japon.","La sauce samouraï est une sauce belge, assez relevée, servie traditionnellement avec des frites.","fr:Sauce_samouraï","c:a/a8/Samurai_sauce.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q3032267",225,"plat","Sirop de Liège","C","Le sirop de Liège est une sorte de mélasse issue de la cuisson et de la réduction de jus de pommes et/ou de poires. Certains fabricants y ajoutent parfois des dattes. On obtient ainsi, après plusieurs heures, une pâte brune très foncée, légèrement translucide. Cette dernière est, comme son nom l'indique, d'origine liégeoise, région dans laquelle on trouvait de nombreuses siroperies.","Le sirop de Liège est une sorte de mélasse issue de la cuisson et de la réduction de jus de pommes et/ou de poires.","fr:Sirop_de_Liège","c:4/4e/Sirop_de_Li%C3%A8ge.jpg"],["Q107064986",226,"plat","Spéculoos","E","Le spéculoos ou speculoos, plus rarement spéculos ou spéculaus, est un biscuit traditionnel à la cassonade, originaire du comté de Flandre, territoire historique aujourd'hui partagé entre la Belgique, la France et les Pays-Bas.",118,"fr:Spéculoos","c:f/fc/Spekulatius_four_pieces_of.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q929276",227,"plat","Stella Artois","R","Stella Artois est une bière brassée depuis 1366. Originaire de Belgique, cette lager blonde est célèbre pour sa qualité, son goût raffiné et son histoire riche qui remonte à plusieurs siècles.","Stella Artois est une bière brassée depuis 1366.","fr:Stella_Artois","c:1/10/Stella_Artois_new_logo.png",{"cats":["belgique","marques","friterie"]}],["Q305329",228,"plat","Stoemp","C","Le stoemp est un plat traditionnel flamand typique en Belgique, dans le nord de la France et en Hollande. Il s'agit d'un plat cuisiné à Bruxelles depuis le XIXe siècle, une sorte de purée.","Le stoemp est un plat traditionnel flamand typique en Belgique, dans le nord de la France et en Hollande.","fr:Stoemp","c:2/23/Cod_and_stoemp.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q2550270",229,"plat","Tarte al d'jote","C","La tarte al d'jote est une spécialité culinaire de la ville de Nivelles.",null,"fr:Tarte_al_d'jote","c:f/f5/Tarte_al%27djote_02.jpg",{"cats":["belgique","friterie"]}],["Q154043",230,"plat","Tarte au riz","C","La tarte au riz ou blanke dorêye est une pâtisserie provenant de l'ancienne principauté de Liège.",null,"fr:Tarte_au_riz","c:9/9c/Tarte_au_riz.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q505815",231,"plat","Trappiste","PC","Une bière trappiste, ou trappiste, est une bière brassée par ou sous contrôle des moines trappistes. Elles sont généralement de fermentation haute et refermentées en bouteille.","Une bière trappiste, ou trappiste, est une bière brassée par ou sous contrôle des moines trappistes.","fr:Trappiste_(bière)","c:0/01/Trappist_Beer_2015-08-15.jpg",{"cats":["belgique","nourriture"]}],["Q855563",232,"plat","Trappiste Rochefort","C","La Rochefort est une bière trappiste belge.",null,"fr:Rochefort_(bière)","c:6/66/Rochefort-beers.jpg"],["Q2388771",233,"plat","Tripel Karmeliet","PC","La Tripel Karmeliet, est une bière belge du groupe AB-Inbev, lancée en 1996 par la brasserie Bosteels, selon une recette originale de 1679. C'est une bière de fermentation haute, possédant un haut degré d'alcool. Elle est fabriquée à partir de trois céréales: l'orge, le froment et l'avoine.",112,"fr:Tripel_Karmeliet","c:4/4b/Tripel_Karmeliet_%28glass%29.jpg",{"cats":["belgique","friterie"]}],["Q304868",234,"plat","Vol-au-vent","R","Le vol-au-vent est, de nos jours, une charcuterie pâtissière composée d'une croûte cylindrique faite de pâte feuilletée, et d'une garniture liée d'une sauce. À l'origine, le vol-au-vent désigne formellement la croustade de pâte feuilletée, mais le sens a glissé pour inclure la garniture. Destiné à plusieurs personnes, il a un diamètre généralement de 15 à 20 cm, mais aujourd'hui, il se confond avec la bouchée individuelle de taille inférieure et la mini-bouchée de 4/5 cm appelée autrefois « bouchée mignonne ».",108,"fr:Vol-au-vent","c:d/de/Vol-au-vent_20_cm.jpg",{"cats":["belgique","nourriture"]}],["Q635675",235,"plat","Waterzooï","PC","Le waterzooï est une soupe-repas mijotée originaire de Gand en Belgique à base de poulet ou de poisson.",null,"fr:Waterzooï","c:5/53/Waterzooi_at_De_Vlaamsche_Pot_%282175547879%29.jpg",{"cats":["belgique","nourriture","friterie"]}],["Q1144830",236,"plat","Westmalle","C","La Westmalle est une bière trappiste brassée depuis le XIXe siècle dans le village de Westmalle de la province d'Anvers, à l'Abbaye cistercienne de Westmalle.",110,"fr:Westmalle_(bière)","c:4/4d/Westmalle_bi%C3%A8res_et_verre.JPG"],["Q1368052",237,"plat","Westvleteren","C","La Westvleteren est une bière trappiste belge.",null,"fr:Westvleteren_(bière)","c:7/7e/WestvleterenBlonde.jpg",{"cats":["belgique","marques","friterie"]}],["Q80238",238,"plat","Élixir d'Anvers","C","L’élixir d’Anvers est une boisson alcoolisée fabriquée en Belgique par F.X. de Beukelaer. Créée en 1863, elle répondait à la demande émergente d’alcools supposément moins nocifs pour la santé que ceux habituellement consommés alors, voire parés de diverses vertus préventives et curatives. L’élixir d’Anvers est aujourd’hui servi en apéritif ou en digestif.","L’élixir d’Anvers est une boisson alcoolisée fabriquée en Belgique par F.X.","fr:Élixir_d'Anvers","c:6/62/%C3%89lixir_d%27Anvers.jpg",{"cats":["belgique","friterie"]}],["Q2882210",240,"bd","Bande dessinée belge","C","La bande dessinée belge constitue un art à part entière en Belgique. La bande dessinée apparaît réellement dans ce pays dans les années 1920 sous l'impulsion d'Hergé avec son héros Tintin et plus tard le journal du même nom, précédé par le journal Spirou. Cette concurrence crée une émulation et un développement accru de la bande dessinée après-guerre. Chaque journal avait sa ligne éditoriale et donna lieu à deux styles.","La bande dessinée belge constitue un art à part entière en Belgique.","fr:Bande_dessinée_belge","c:a/ac/Le_d%C3%A9luge_%C3%A0_Bruxelles.jpg"],["Q134390874",244,"bd","Bob Morane","PC","Bob Morane est le nom d'une série de romans et de son héros éponyme créés en décembre 1953 par le romancier belge Henri Vernes pour la collection de poche « Marabout Junior » des éditions André Gérard. Ces romans furent par la suite adaptés en bandes dessinées.",119,"fr:Bob_Morane","c:f/f0/Bob_Morane_poche%2C_ann%C3%A9es_1960_et_70.jpg"],["Q667573",258,"bd","Jerry Spring","C","Jerry Spring est une série de bande dessinée franco-belge créée en 1954 par Jijé dans le no 829 du journal Spirou. Elle met en scène Jerry Spring, un cow-boy de l'Ouest américain, qui est fréquemment nommé US-marshall par le gouvernement. Jijé a parfois fait appel à un scénariste: Maurice Rosy, René Goscinny, Jean Acquaviva, Jacques Lob, Daniel Dubois, et Philip. Après le décès de Jijé, le dessin est repris par Franz, le temps d'une histoire, sur un scénario de Festin, alias José-Louis Bocquet.","Jerry Spring est une série de bande dessinée franco-belge créée en 1954 par Jijé dans le no 829 du journal Spirou.","fr:Jerry_Spring","https://upload.wikimedia.org/wikipedia/en/thumb/3/39/Jije-jerry_spring1.jpg/330px-Jije-jerry_spring1.jpg"],["Q741204",259,"bd","Jijé","C","Joseph Gillain, dit Jijé, né le 13 janvier 1914 à Gedinne et mort le 19 juin 1980 à Versailles, est un scénariste et dessinateur de bande dessinée belge. Il est l'initiateur de ce que le monde de la bande dessinée désigne comme l'école de Marcinelle, liée aux Éditions Dupuis et au Journal de Spirou.",116,"fr:Jijé","c:a/a8/Joseph_Gillain.jpg"],["Q21716752",263,"bd","Largo Winch","C","Largo Winch est un personnage de fiction, héros éponyme de romans et d’une série de bande dessinée, créé par l'écrivain belge Jean Van Hamme, ainsi que de plusieurs produits dérivés dont une série télévisée et trois films, Largo Winch, Largo Winch 2 et Largo Winch: Le Prix de l'argent.",119,"fr:Largo_Winch","c:4/4d/Belgique_-_Louvain-la-Neuve_-_Place_des_Sciences_-_Largo_Winch_-_02.jpg"],["Q76210",265,"bd","Le Lotus bleu","PC","Le Lotus bleu est le cinquième album de la série de bande dessinée Les Aventures de Tintin, créée par le dessinateur belge Hergé. L'histoire est d'abord pré-publiée en noir et blanc du 9 août 1934 au 17 octobre 1935 dans les pages du Petit Vingtième — le supplément pour la jeunesse du journal Le Vingtième Siècle —, sous le titre Les Aventures de Tintin reporter en Extrême-Orient, avant d'être éditée en album de 124 planches sous son titre définitif, aux éditions Casterman.",116,"fr:Le_Lotus_bleu","c:3/38/Le_Lotus_Bleu_transparent.png"],["Q921522",267,"bd","Le Secret de La Licorne","C","Le Secret de La Licorne est le onzième album de la série de bande dessinée Les Aventures de Tintin, créée par le dessinateur belge Hergé. Il constitue la première partie d'un diptyque qui s'achève avec Le Trésor de Rackham le Rouge.",112,"fr:Le_Secret_de_La_Licorne","https://upload.wikimedia.org/wikipedia/fr/thumb/a/a8/Logo_Le_Secret_de_la_Licorne.png/330px-Logo_Le_Secret_de_la_Licorne.png"],["Q55692704",268,"bd","Les Aventures de Chick Bill","C","Les Aventures de Chick Bill est une série de bande dessinée créée par Tibet. Reprenant les codes et l'univers du western, elle raconte les aventures humoristiques d'un jeune cow-boy, Chick Bill. Tibet est l'auteur à part entière d'une partie des épisodes, mais la série a également été scénarisée par Maurice Rosy, Michel Greg et André-Paul Duchâteau, ainsi que, le temps d'un épisode, par René Goscinny. Les dessins des deux derniers albums sont co-signés par Tibet et Frank Brichau.","Les Aventures de Chick Bill est une série de bande dessinée créée par Tibet.","fr:Les_Aventures_de_Chick_Bill","c:6/6b/Chick_Bill_logo_BD.jpg"],["Q1213734",271,"bd","Les Bijoux de la Castafiore","C","Les Bijoux de la Castafiore est le vingt et unième album de la série de bande dessinée Les Aventures de Tintin, créée par le dessinateur belge Hergé. L'histoire est d'abord pré-publiée du 4 juillet 1961 au 13 septembre 1962 dans les pages du journal Tintin, avant d'être éditée en album de soixante-deux planches aux éditions Casterman en 1963.",117,"fr:Les_Bijoux_de_la_Castafiore","c:1/10/Les_bijoux_de_la_castafiore.png"],["Q1307909",275,"bd","Ligne claire","PC","La ligne claire est un langage graphique issu de l'école belge de bandes dessinées réunie autour d'Hergé, c'est-à-dire le « style Tintin » associé aux dessinateurs du journal du même nom. Le terme ligne claire a été forgé en 1977 par le dessinateur néerlandais Joost Swarte, à l'occasion de l'exposition Tintin de Rotterdam.",118,"fr:Ligne_claire","c:f/f2/Comic_mural_Le_jeune_Albert%2C_Yves_Chaland%2C_Bruxelles.jpg"],["Q3312612",278,"bd","Midam","C","Midam, de son vrai nom Michel Ledent, né le 16 mai 1963 à Etterbeek, est un auteur, dessinateur et scénariste de bande dessinée belge.",118,"fr:Midam","c:d/d5/MIDAM_n%26b.jpg"],["Q1309201",282,"bd","On a marché sur la Lune","C","On a marché sur la Lune est le dix-septième album de la série de bande dessinée Les Aventures de Tintin, créée par le dessinateur belge Hergé. Sa prépublication dans les pages du journal Tintin se confond avec celle de l'album précédent, Objectif Lune, mais l'aventure est présentée uniquement sous le titre On a marché sur la Lune. 24 planches sont prépubliées du 30 mars 1950 au 7 septembre 1950 puis 93 autres du 9 avril 1952 au 30 décembre 1953. L'album paraît en 1954.",117,"fr:On_a_marché_sur_la_Lune","https://upload.wikimedia.org/wikipedia/fr/thumb/4/44/Logo_On_a_march%C3%A9_sur_la_Lune.png/330px-Logo_On_a_march%C3%A9_sur_la_Lune.png"],["Q431392",287,"bd","Raymond Leblanc","C","Raymond Leblanc, né le 22 mai 1915 à Longlier et mort le 21 mars 2008 à Bruxelles, est un éditeur de presse et de bande dessinée belge, fondateur du journal Tintin, des éditions du Lombard et des studios de dessins animés Belvision.",119,"fr:Raymond_Leblanc","c:2/2e/BelVision_logo.png"],["Q1506760",293,"bd","Tibet","C","Gilbert Gascard, connu sous le pseudonyme de Tibet, né le 29 octobre 1931 à Marseille et mort le 2 janvier 2010 à Roquebrune-sur-Argens, est un auteur de bande dessinée français surtout connu pour ses séries franco-belges au long cours: Chick Bill et Ric Hochet.",113,"fr:Tibet_(dessinateur)","c:4/40/Tibet.89.jpg"],["Q636870",295,"bd","Tintin au Congo","PC","Tintin au Congo est le deuxième album de la série de bande dessinée Les Aventures de Tintin, créée par le dessinateur belge Hergé.",117,"fr:Tintin_au_Congo","c:d/de/Tintin_au_Congo.png"],["Q273470",299,"bd","École de Marcinelle","C","L'école de Marcinelle, ou école de Charleroi, est un style de bande dessinée associé au journal Spirou.",null,"fr:École_de_Marcinelle","c:d/d0/Spirou_at_Place_Sainctelette%2C_Brussels.JPG"],["Q181995",300,"personnalite","Adolphe Sax","R","Antoine-Joseph Sax, mieux connu sous le nom d'Adolphe Sax, né le 6 novembre 1814 à Dinant, en province de Namur, peu après rattachée au royaume uni des Pays-Bas, et mort le 7 février 1894 à Paris 9e à l'âge de 79 ans, est un facteur d'instruments de musique belge, surtout connu pour avoir inventé le saxophone et le saxhorn.",116,"fr:Adolphe_Sax","c:4/4f/Adolphe_Sax.jpg"],["Q55008046",301,"personnalite","Albert Ier","E","Albert Ier, né le 8 avril 1875 à Bruxelles et mort le 17 février 1934 à Marche-les-Dames, est le troisième roi des Belges. Duc de Saxe, prince de Saxe-Cobourg et Gotha et héritier de la couronne belge à partir de 1905, il succède à son oncle Léopold II en 1909 et règne jusqu'à sa mort.",114,"fr:Albert_Ier_(roi_des_Belges)","c:1/16/Albert_I_Koning_der_Belgen.jpg",{"cats":["belgique","politique"]}],["Q3911",302,"personnalite","Albert II","E","Albert II, né le 6 juin 1934 au château du Stuyvenberg, à Laeken, est le sixième roi des Belges, du 9 août 1993, à la suite de la mort de son frère Baudouin, jusqu'à son abdication le 21 juillet 2013.",117,"fr:Albert_II_(roi_des_Belges)","c:1/19/Albert_II%2C_King_of_Belgium.jpg",{"cats":["belgique","politique"]}],["Q476596",303,"personnalite","Alexander De Croo","PC","Alexander De Croo, né le 3 novembre 1975 à Vilvorde, est un homme d'État belge néerlandophone. Membre du parti libéral Open VLD, il est Premier ministre du 1er octobre 2020 au 3 février 2025.","Alexander De Croo, né le 3 novembre 1975 à Vilvorde, est un homme d'État belge néerlandophone.","fr:Alexander_De_Croo","c:2/25/Alexander_De_Croo_on_5_January_2024_%28cropped%29.jpg",{"cats":["belgique","politique"]}],["Q12847",304,"personnalite","Ambiorix","C","Ambiorix est un roi des Éburons du Ier siècle av. J.-C., peuple belge du nord de la Gaule.","Ambiorix est un roi des Éburons du Ier siècle av.","fr:Ambiorix","c:4/4a/Ambiorix_%288676574663%29.jpg"],["Q168040",305,"personnalite","Amélie Nothomb","E","Fabienne Claire, baronne Nothomb, dite Amélie Nothomb, née le 9 juillet 1966 à Etterbeek, est une romancière belge de langue française.",117,"fr:Amélie_Nothomb","c:9/91/Am%C3%A9lie_Nothomb_02828_G.Garitan.jpg",{"cats":["belgique","personnalites"]}],["Q170267",306,"personnalite","André Vésale","R","André Vésale, de son nom latin Andreas Vesalius, de son nom de naissance Andreas Wytinck van Wesel est un anatomiste et médecin brabançon, originaire des Pays-Bas méridionaux. Grand humaniste de son époque, il est considéré comme le père de l'anatomie moderne.",119,"fr:André_Vésale","c:4/4e/Vesalius_Fabrica_portrait.jpg",{"cats":["belgique","personnalites"]}],["Q45192617",307,"personnalite","Angèle","M","Angèle, mononyme d'Angèle Van Laeken, née le 3 décembre 1995 à Uccle, est une auteure-compositrice-interprète, musicienne, productrice, actrice et mannequin belge d'expression française.",110,"fr:Angèle_(chanteuse)","c:7/78/P2NAngele_2.jpg",{"cats":["belgique","chanteurs_fr"]}],["Q150679",309,"personnalite","Antoine van Dyck","PC","Antoine van Dyck, né Antoon van Dyck le 22 mars 1599 à Anvers et mort le 9 décembre 1641 à Londres, est un peintre et graveur baroque brabançon, surtout portraitiste, qui a été le principal peintre de cour en Angleterre, après avoir connu un grand succès en Italie et en Flandre.",117,"fr:Antoine_van_Dyck","c:e/ee/Anthony_van_Dyck_-_Self-portrait_with_a_Sunflower.jpg"],["Q230238",310,"personnalite","Astrid de Suède","R","Astrid de Suède, princesse de Suède, née le 17 novembre 1905 à Stockholm et morte dans un accident de voiture le 29 août 1935 à Küssnacht, est la quatrième reine des Belges, du 23 février 1934 jusqu’à sa mort, en tant qu'épouse du roi Léopold III.",115,"fr:Astrid_de_Suède","c:7/7c/Astrid_av_Sverige.jpg"],["Q151838",311,"personnalite","Axel Witsel","R","Axel Witsel, né le 12 janvier 1989 à Liège en Belgique, est un footballeur international belge qui joue au poste de défenseur ou de milieu de terrain à l'OGC Nice.",115,"fr:Axel_Witsel","c:6/61/Axel_Witsel_USMNT_v_Belgium_Mar_28_2026-34_%28cropped%29.jpg",{"cats":["belgique","foot"]}],["Q336599",312,"personnalite","Bart De Wever","R","Bart De Wever, également désigné par ses initiales BDW, né le 21 décembre 1970 à Mortsel, est un homme d'État belge néerlandophone membre de la Nieuw-Vlaamse Alliantie, dont il était le président de 2004 à 2025. Il est Premier ministre de Belgique depuis le 3 février 2025.",115,"fr:Bart_De_Wever","c:4/43/2025_Bart_De_Wever_%28cropped%29.jpg",{"cats":["belgique","politique"]}],["Q12976",313,"personnalite","Baudouin","E","Baudouin, né le 7 septembre 1930 au château du Stuyvenberg et mort le 31 juillet 1993 à Motril, est le cinquième roi des Belges.",116,"fr:Baudouin_(roi_des_Belges)","c:c/c2/King_Baudouin_of_Belgium_%282%29.jpg",{"cats":["belgique","politique"]}],["Q950958",317,"personnalite","Charles Michel","PC","Charles Michel, né le 21 décembre 1975 à Namur, est un homme d'État belge, membre du Mouvement réformateur. Il est Premier ministre du 11 octobre 2014 au 27 octobre 2019, puis président du Conseil européen de 2019 à 2024.","Charles Michel, né le 21 décembre 1975 à Namur, est un homme d'État belge, membre du Mouvement réformateur.","fr:Charles_Michel","c:b/ba/Charles_Michel_%2849467991288%29.jpg",{"cats":["belgique","politique"]}],["Q32500",318,"personnalite","Charles Quint","L","Charles de Habsbourg, couramment appelé en français Charles Quint, né le 24 février 1500 à Gand et mort le 21 septembre 1558 au monastère de Yuste, élu le 28 juin 1519 empereur sous le nom de Charles V, est le monarque européen le plus puissant de la première moitié du XVIe siècle.",119,"fr:Charles_Quint","c:6/61/Emperor_charles_v.png",{"cats":["belgique","politique"]}],["Q19406",320,"personnalite","David Goffin","E","David Goffin, né le 7 décembre 1990 à Rocourt, est un joueur de tennis belge, professionnel de 2009 à 2026.",null,"fr:David_Goffin","c:b/b4/Goffin_MCM22_%286%29_%2852036658809%29.jpg",{"cats":["belgique","sports","tennis"]}],["Q272438",321,"personnalite","Diane von Fürstenberg","E","Diane von Fürstenberg, née Diane Simone Michelle Halfin le 31 décembre 1946 à Bruxelles, est une créatrice de mode féminine, femme d'affaires et philanthrope Belge et américaine. Selon le magazine Forbes, elle est la soixante-quinzième femme la plus puissante du monde en 2015. Elle est la fondatrice et coprésidente de la société Diane von Fürstenberg, une marque de luxe qui distribue prêt-à-porter féminin, chaussures, sacs à main et accessoires. Le siège de l'entreprise est situé à New York.",114,"fr:Diane_von_Fürstenberg","c:1/1d/Diane_von_Furstenberg_and_Barry_Diller_Shankbone_NYC_2009.jpg"],["Q44122",322,"personnalite","Django Reinhardt","E","Jean Reinhardt, plus connu sous le nom de Django Reinhardt, prononcé ou, est un guitariste français de jazz né le 23 janvier 1910 à Liberchies — aujourd'hui une section de la commune de Pont-à-Celles — dans la province de Hainaut, près de la ville de Charleroi, en Belgique, et mort le 16 mai 1953 à Fontainebleau. Son style de jeu et de composition a été suivi d'adeptes, donnant naissance à un style de jazz à part entière, le jazz manouche.",116,"fr:Django_Reinhardt","c:b/b7/DjangoReinhardt-1939-Harcourt.png"],["Q11954",323,"personnalite","Dries Mertens","R","Dries Mertens, né le 6 mai 1987 à Louvain en Belgique, est un footballeur international belge ayant évolué au poste d'attaquant.",115,"fr:Dries_Mertens","c:f/f6/Dries_Mertens_%282024%29.png",{"cats":["belgique","foot"]}],["Q103756",324,"personnalite","Eddy Merckx","L","Édouard, baron Merckx, dit Eddy Merckx, est un cycliste belge né le 17 juin 1945 dans la commune de Meensel-Kiezegem, en Province de Brabant à l'est de Louvain.",117,"fr:Eddy_Merckx","c:e/e8/Eddy_Merckx_Molteni_1973.jpg",{"cats":["belgique","cyclisme","sports"]}],["Q214204",325,"personnalite","Eden Hazard","L","Eden Hazard, né le 7 janvier 1991 à La Louvière en Belgique, est un footballeur international belge qui joue au poste d'ailier gauche entre 2007 et 2023.",117,"fr:Eden_Hazard","c:6/68/Eden_Hazard_WC2022.jpg",{"cats":["belgique","foot"]}],["Q15048",326,"personnalite","Elio Di Rupo","PC","Elio Di Rupo, né le 18 juillet 1951 à Morlanwelz-Mariemont, est un homme d'État belge francophone, président du Parti socialiste de 1999 à 2019, Premier ministre de Belgique de 2011 à 2014 et trois fois ministre-président de Wallonie de 1999 à 2000, de 2005 à 2007 et de 2019 à 2024.",117,"fr:Elio_Di_Rupo","c:e/e2/1718636580832_20240612_DI_RUPO_Elio_BE_10B.jpg",{"cats":["belgique","politique","lgbt"]}],["Q193680",327,"personnalite","Emile Verhaeren","C","Emile Verhaeren, né à Saint-Amand dans la province d'Anvers le 21 mai 1855 et mort à Rouen le 27 novembre 1916, est un poète belge flamand, d'expression française.",118,"fr:Emile_Verhaeren","c:f/ff/Emile_Verhaeren01.jpg",{"cats":["belgique","personnalites"]}],["Q221432",328,"personnalite","Enzo Scifo","PC","Vincenzo Scifo dit Enzo Scifo, né le 19 février 1966 à Haine-Saint-Paul en Belgique, est un footballeur international belge reconverti entraîneur. Fils d'immigrés italiens, il est naturalisé belge en 1984.",117,"fr:Enzo_Scifo","c:b/b1/Enzo_scifo_belgium.jpg",{"cats":["belgique","foot"]}],["Q311665",329,"personnalite","Ernest Solvay","C","Ernest Solvay, né le 16 avril 1838 à Rebecq-Rognon et mort le 26 mai 1922 à Ixelles, est un chimiste et un industriel belge, fondateur de la Société Solvay & Cie et grand mécène de la recherche scientifique de son époque.",117,"fr:Ernest_Solvay","c:8/81/Ernest_Solvay.jpg"],["Q597609",331,"personnalite","Frères Dardenne","PC","Jean-Pierre et Luc Dardenne, souvent appelés collectivement frères Dardenne, sont deux réalisateurs, scénaristes et producteurs belges, respectivement nés le 21 avril 1951 à Engis et le 10 mars 1954 aux Awirs. Ils réalisent leurs films en commun.",115,"fr:Frères_Dardenne","c:7/72/Fr%C3%A8res_Dardenne_Cannes_2015.jpg"],["Q378129",332,"personnalite","Félicien Rops","PC","Félicien Rops, né le 7 juillet 1833 à Namur et mort le 23 août 1898 à Essonnes, est un peintre, dessinateur, illustrateur et graveur belge.",108,"fr:Félicien_Rops","c:3/3d/F%C3%A9licien_Rops_%28photo%29.jpeg"],["Q12998",333,"personnalite","Georges Lemaître","R","Georges Lemaître, né le 17 juillet 1894 à Charleroi et mort le 20 juin 1966 à Louvain, est un chanoine catholique, astronome et physicien belge, professeur à l'université catholique de Louvain.",114,"fr:Georges_Lemaître","c:5/52/Lemaitre.jpg",{"cats":["belgique","personnalites"]}],["Q128790",334,"personnalite","Georges Simenon","R","Georges Simenon, né le 13 février 1903 à Liège et mort le 4 septembre 1989 à Lausanne, est un romancier belge francophone.",109,"fr:Georges_Simenon","c:4/45/GeorgesSimenon-StudioHarcourt-1952.png",{"cats":["belgique","personnalites"]}],["Q18433444",335,"personnalite","Georges-Louis Bouchez","R","Georges-Louis Bouchez, également désigné par ses initiales GLB, né le 23 mars 1986 à Frameries, est un avocat et homme politique belge libéral. Il est le président du parti politique belge le Mouvement réformateur.",118,"fr:Georges-Louis_Bouchez","c:4/46/Georges-Louis_Bouchez_cropped.jpg"],["Q76721",336,"personnalite","Godefroy de Bouillon","R","Godefroy de Bouillon, né vers 1058 et mort le 18 juillet 1100 à Jérusalem, est un chevalier franc et duc de Basse-Lotharingie. Premier souverain du royaume de Jérusalem au terme de la première croisade, il a, selon la majorité des chroniqueurs occidentaux, refusé le titre de roi pour celui, plus humble, d'avoué du Saint-Sépulcre.",107,"fr:Godefroy_de_Bouillon","c:4/4a/Godefroi1099.jpg"],["Q12978",337,"personnalite","Guy Verhofstadt","PC","Guy Verhofstadt, né le 11 avril 1953 à Termonde, est un homme d'État belge, 36e Premier ministre du royaume de Belgique de 1999 à 2008. Ministre d'État belge, il est membre de l'Open Vld, de tendance libérale.",119,"fr:Guy_Verhofstadt","c:f/f5/Guy_Verhofstadt_-_MEP_Portrait_2019.jpg",{"cats":["belgique","politique"]}],["Q6353",338,"personnalite","Gérard Mercator","PC","Geert ou Gerard de Kremer, connu dans la République des Lettres sous son nom latinisé de Gerardus Mercator et dans les livres français sous celui de Gérard Mercator, né le 5 mars 1512 à Rupelmonde et mort le 2 décembre 1594 à Duisbourg, est un mathématicien, géographe et cartographe flamand, inventeur de la projection cartographique qui porte son nom.",118,"fr:Gérard_Mercator","c:9/94/G%C3%A9rard_Mercator.jpg",{"cats":["belgique","personnalites"]}],["Q12983",339,"personnalite","Herman Van Rompuy","PC","Herman, comte Van Rompuy, né le 31 octobre 1947 à Etterbeek, est un homme d'État belge.",null,"fr:Herman_Van_Rompuy","c:8/8d/Herman_Van_Rompuy_675.jpg"],["Q173123",340,"personnalite","Jacky Ickx","R","Jacques Bernard Ickx, dit Jacky Ickx, né le 1er janvier 1945 à Bruxelles, est un pilote automobile belge, ayant notamment couru avec succès en Formule 1, en endurance et en rallye-raid. Il est le père de la pilote Vanina Ickx.",111,"fr:Jacky_Ickx","c:1/19/Jacky_Ickx_Portr%C3%A4t_Mille_Miglia_2018.jpg",{"cats":["belgique","f1","moto"]}],["Q1666",341,"personnalite","Jacques Brel","L","Jacques Brel, né le 8 avril 1929 à Schaerbeek et mort le 9 octobre 1978 à Bobigny, est un auteur-compositeur-interprète, poète, acteur et réalisateur belge.",89,"fr:Jacques_Brel","c:c/c1/Jacques_Brel_%281962%29.jpg",{"cats":["belgique","chanteurs_fr"]}],["Q158840",342,"personnalite","James Ensor","PC","James Sidney Edouard Ensor, né le 13 avril 1860 à Ostende et mort le 19 novembre 1949 dans cette ville, est un artiste peintre, graveur et un anarchiste belge. Il développe son propre langage esthétique au gré de ses expérimentations avec la lumière, la ligne et la couleur. Ses toiles se peuplent de motifs macabres, masques de carnaval et squelettes pour atteindre l’apogée dans de fameuses mascarades comme L’intrigue.",118,"fr:James_Ensor","c:5/56/Henry_De_Groux.James_Ensor.JPG",{"cats":["belgique","personnalites"]}],["Q312618",343,"personnalite","Jan Ceulemans","C","Jan Anna Gumaar Ceulemans, né le 28 février 1957 à Lierre en Belgique, est un footballeur international belge, devenu ensuite entraîneur.",117,"fr:Jan_Ceulemans","c:c/c5/Jan_Ceulemans.jpg",{"cats":["belgique","foot"]}],["Q446501",346,"personnalite","Jean-Michel Saive","C","Jean-Michel Saive est un pongiste et un dirigeant sportif belge. Considéré comme l'un des meilleurs pongistes de l'histoire, il a remporté de nombreuses médailles internationales et est également reconnu pour sa longévité dans le sport de haut niveau.","Jean-Michel Saive est un pongiste et un dirigeant sportif belge.","fr:Jean-Michel_Saive","c:b/b7/Mondial_Ping_-_Gatien-Saive_-_39.jpg"],["Q11682",347,"personnalite","Justine Henin","R","Justine Henin, née le 1er juin 1982 à Rocourt en Belgique, est une joueuse professionnelle de tennis belge.",null,"fr:Justine_Henin","c:d/db/Justine_Henin_RG2010.jpg",{"cats":["belgique","sports","tennis"]}],["Q59209505",349,"personnalite","Jérémy Doku","L","Jérémy Doku, né le 27 mai 2002 à Borgerhout en Belgique, est un footballeur international belge qui joue au poste d'attaquant à Manchester City.",113,"fr:Jérémy_Doku","c:0/06/J%C3%A9r%C3%A9my_Doku_USMNT_v_Belgium_Mar_28_2026-27_%28cropped%29.jpg",{"cats":["belgique","foot"]}],["Q357984",350,"personnalite","Kevin De Bruyne","L","Kevin De Bruyne, surnommé KDB, né le 28 juin 1991 à Tronchiennes en Belgique, est un footballeur international belge qui joue au poste de milieu de terrain au SSC Naples.",116,"fr:Kevin_De_Bruyne","c:4/40/Kevin_De_Bruyne_USMNT_v_Belgium_Mar_28_2026-64_%28cropped%29.jpg",{"cats":["belgique","foot"]}],["Q11685",351,"personnalite","Kim Clijsters","R","Kim Antonie Lode Clijsters, née le 8 juin 1983 à Bilzen, est une joueuse de tennis professionnelle belge. Elle est la fille du footballeur Lei Clijsters. Elle a connu une première carrière de 1997 à 2007. Le 26 mars 2009, elle annonce son retour sur le circuit WTA au tournoi de Cincinnati en août 2009. Elle met fin à sa deuxième carrière lors de l'US Open 2012. En 2019, elle annonce un retour sur le circuit pour 2020, après sept ans d'absence.","Kim Antonie Lode Clijsters, née le 8 juin 1983 à Bilzen, est une joueuse de tennis professionnelle belge.","fr:Kim_Clijsters","c:7/71/Kim_Clijsters.jpg",{"cats":["belgique","sports","tennis"]}],["Q466625",352,"personnalite","Kim Gevaert","C","Kim Gevaert est une athlète belge, spécialiste du sprint. Elle est championne olympique du relais 4 × 100 m en 2008 à Pékin et double championne d'Europe en 100 et 200 mètres en 2006 à Göteborg. Elle commence l'athlétisme à l'âge de 15 ans et établit plusieurs records chez les juniors. Passée professionnelle en 1998, parallèlement à ses études de logopédie, elle bat le record national du 100 m et remporte ensuite sa première médaille d'or lors de l'Universiade d'été de 1999.","Kim Gevaert est une athlète belge, spécialiste du sprint.","fr:Kim_Gevaert","c:4/48/Kim_Gevaert.jpg"],["Q243442",353,"personnalite","Leo Baekeland","C","Leo Baekeland, né le 14 novembre 1863 à Gand et mort le 23 février 1944 à Beacon, est un chimiste belge naturalisé américain, connu pour ses recherches en photographie et sur les matières plastiques. Il a donné son nom à la « bakélite ».",114,"fr:Leo_Baekeland","c:8/80/Leo_Hendrik_Baekeland%2C_1916.jpg",{"cats":["belgique","personnalites"]}],["Q22955400",354,"personnalite","Lize Spit","C","Lize Spit, née en 1988 à Lierre, est une écrivaine belge, écrivant en néerlandais. Son premier roman, Débâcle, connaît un grand succès et est traduit dans de nombreuses langues.","Lize Spit, née en 1988 à Lierre, est une écrivaine belge, écrivant en néerlandais.","fr:Lize_Spit","c:3/3b/Lize_Spit_%282016%29.jpg"],["Q12971",355,"personnalite","Léopold Ier","E","Léopold Ier, connu auparavant sous le nom de Léopold Georges Chrétien Frédéric de Saxe-Cobourg-Saalfeld, né le 16 décembre 1790 à Cobourg et mort le 10 décembre 1865 au château de Laeken, est un prince allemand de la maison de Saxe-Cobourg et Gotha devenu le premier roi des Belges en 1831 et le fondateur de la dynastie régnant sur la Belgique. Il est également l'ancêtre du grand-duc de Luxembourg, du prétendant au trône d'Italie, ainsi que du prince Napoléon.",113,"fr:Léopold_Ier_(roi_des_Belges)","c:9/9e/NICAISE_Leopold_ANV.jpg",{"cats":["belgique","politique"]}],["Q12967",356,"personnalite","Léopold II","L","Léopold II, de son nom Léopold Louis-Philippe Marie Victor de Saxe-Cobourg-Gotha, né le 9 avril 1835 au palais royal de Bruxelles et mort le 17 décembre 1909 au château de Laeken, est le deuxième roi des Belges, prince de Belgique, duc de Saxe, prince de Saxe-Cobourg et Gotha, duc de Brabant. Il succède à son père, Léopold Ier, au trône de Belgique en 1865. Par sa mère Louise d'Orléans, il est le petit-fils de Louis-Philippe Ier, roi des Français. Il est le frère de Charlotte, impératrice consort du Mexique.",119,"fr:Léopold_II_(roi_des_Belges)","c:9/9e/REX_LEOPOLD_II.jpg",{"cats":["belgique","politique"]}],["Q12973",357,"personnalite","Léopold III","E","Léopold III, né le 3 novembre 1901 à Bruxelles et mort le 25 septembre 1983 à Woluwe-Saint-Lambert, est le quatrième roi des Belges du 23 février 1934 au 16 juillet 1951, et le fils d’Albert Ier et d’Élisabeth en Bavière. Déclaré dans l'impossibilité de régner de juin 1940 à juin 1950, il abdique l'année suivante au terme d'une longue polémique sur la question royale suscitée par son comportement controversé lors de la Seconde Guerre mondiale et l'occupation allemande du pays.",116,"fr:Léopold_III_(roi_des_Belges)","c:b/bc/Leopold_III_%281934%29.jpg",{"cats":["belgique","politique"]}],["Q346427",358,"personnalite","Marc Wilmots","PC","Marc Wilmots, né le 22 février 1969 à Dongelberg en Belgique, est un footballeur international et entraîneur belge actif dans les années 1980 et 1990. Il a également exercé les fonctions de sénateur et de consultant.",114,"fr:Marc_Wilmots","c:2/22/13980312001139636951013713150860_46238_PhotoT.jpg",{"cats":["belgique","foot"]}],["Q163118",359,"personnalite","Marguerite Yourcenar","R","Marguerite Yourcenar, pseudonyme de Marguerite Cleenewerck de Crayencour, née le 8 juin 1903 à Bruxelles et morte le 17 décembre 1987 à Bar Harbor dans l'État du Maine, est une femme de lettres et académicienne française. Romancière, nouvelliste et autobiographe, elle est aussi poète, traductrice, essayiste et critique littéraire.",119,"fr:Marguerite_Yourcenar","c:1/15/Marguerite_Yourcenar-Bailleul-1982.10.04.Bernhard_De_Grendel_%2811%29.jpg",{"cats":["belgique","personnalites"]}],["Q978265",361,"personnalite","Martin Margiela","PC","Martin Margiela, né le 9 avril 1957 à Louvain, Belgique, est un couturier et artiste belge. Il est le créateur de la marque Maison Martin Margiela, devenue par la suite Maison Margiela.","Martin Margiela, né le 9 avril 1957 à Louvain, Belgique, est un couturier et artiste belge.","fr:Martin_Margiela",""],["Q94334",362,"personnalite","Mathilde d'Udekem d'Acoz","R","Mathilde d'Udekem d'Acoz, née le 20 janvier 1973 à Uccle est la septième reine des Belges en tant qu'épouse du roi Philippe.",114,"fr:Mathilde_d'Udekem_d'Acoz","c:8/8a/EU2024BE_240417_Exhibition_%27Histoire_de_ne_pas_rire._Surrealism_in_Belgium%27_-_70_%28cropped%29.jpg",{"cats":["belgique","politique"]}],["Q49747",364,"personnalite","Maurice Maeterlinck","PC","Maurice Maeterlinck, né le 29 août 1862 à Gand et mort le 6 mai 1949 à Nice, est un écrivain flamand francophone belge, prix Nobel de littérature en 1911.",119,"fr:Maurice_Maeterlinck","c:b/b9/Maurice_de_Maeterlinck%2C_crop.jpg",{"cats":["belgique","personnalites"]}],["Q315992",365,"personnalite","Michel Preud'homme","PC","Michel Preud'homme, né le 24 janvier 1959 à Ougrée en Belgique, est un footballeur international belge, actif dans les années 1980 et 1990, et entraîneur qui joue au poste de gardien de but.",118,"fr:Michel_Preud'homme","c:e/ec/Michel_Preud.JPG",{"cats":["belgique","foot"]}],["Q4167514",366,"personnalite","Nafissatou Thiam","C","Nafissatou Thiam, née le 19 août 1994 à Bruxelles, est une athlète belge, spécialiste des épreuves combinées.",null,"fr:Nafissatou_Thiam","c:3/3b/Nafissatou_Thiam_Oregon_2022_%282%29.jpg",{"cats":["belgique","sports"]}],["Q446883",367,"personnalite","Natacha Régnier","C","Natacha Régnier, née Nathalie Régnier le 11 avril 1974 à Ixelles, est une actrice belge.",null,"fr:Natacha_Régnier","c:2/23/Natacha_R%C3%A9gnier_Cannes_2019.jpg"],["Q312511",368,"personnalite","Olivier Rochus","C","Olivier Rochus, né le 18 janvier 1981 à Namur, est un joueur de tennis belge, professionnel de 1999 à 2014.",null,"fr:Olivier_Rochus","c:d/d7/Olivier_Rochus.jpg",{"cats":["belgique","tennis"]}],["Q31129",369,"personnalite","Paola Ruffo di Calabria","R","Paola Margherita Maria Antonia Consiglia Ruffo di Calabria, née le 11 septembre 1937 à Forte dei Marmi en Toscane, issue de la maison Ruffo di Calabria, prestigieuse famille de la noblesse italienne, est un membre de la famille royale de Belgique, sixième reine des Belges de 1993 à 2013 en tant qu'épouse du roi Albert II, et la mère du roi Philippe.",114,"fr:Paola_Ruffo_di_Calabria","c:f/f5/Queen_Paola_of_Belgium%2C_at_Rashtrapati_Bhavan%2C_in_New_Delhi_on_November_04%2C_2008_%281%29_%28cropped%29.jpg"],["Q164712",370,"personnalite","Paul Delvaux","C","Paul Delvaux, né le 23 septembre 1897 à Antheit et mort le 20 juillet 1994 à Furnes, est un peintre, graveur et illustrateur post-impressionniste, expressionniste puis surréaliste belge.",111,"fr:Paul_Delvaux","c:9/92/Paul_Delvaux_28_Janvier_1972.jpg",{"cats":["belgique","personnalites"]}],["Q1341556",371,"personnalite","Paul Magnette","PC","Paul Magnette est un universitaire et un homme politique belge francophone membre du Parti socialiste, né le 28 juin 1971 à Louvain.",116,"fr:Paul_Magnette","c:2/25/Portrait_de_Paul_Magnette_par_Vanden_Driessche_%28cropped%29.jpg",{"cats":["belgique","politique"]}],["Q362322",372,"personnalite","Paul Van Himst","C","Paul Van Himst, né le 2 octobre 1943 à Leeuw-Saint-Pierre en Belgique, est un footballeur international et entraîneur belge qui joue au poste d'attaquant.",117,"fr:Paul_Van_Himst","c:6/67/Paul_van_himst-1464583760.JPG",{"cats":["belgique","foot"]}],["Q155691",373,"personnalite","Paul-Henri Spaak","PC","Paul-Henri Spaak, né à Schaerbeek le 25 janvier 1899 et mort à Braine-l'Alleud le 31 juillet 1972, est un homme d'État belge socialiste. Il est considéré comme l'un des Pères fondateurs de l'Union européenne.",118,"fr:Paul-Henri_Spaak","c:6/6a/Bundesarchiv_Bild_183-39998-0427%2C_Paul-Henri_Spaak.jpg",{"cats":["belgique","politique"]}],["Q155004",374,"personnalite","Philippe","E","Philippe, né le 15 avril 1960 au château du Belvédère à Bruxelles, est, depuis le 21 juillet 2013, le septième roi des Belges.",118,"fr:Philippe_(roi_des_Belges)","c:a/a5/King_Philippe_of_Belgium_%28January_2025%29.jpg",{"cats":["belgique","politique"]}],["Q259412",375,"personnalite","Philippe Gilbert","R","Philippe Gilbert, né le 5 juillet 1982 à Verviers, est un coureur cycliste belge professionnel pendant 20 ans de 2003 à 2022.",119,"fr:Philippe_Gilbert_(cyclisme)","c:a/a5/Philippe_Gilbert_%282020%29.jpg",{"cats":["belgique","cyclisme","sports"]}],["Q3386120",376,"personnalite","Pierre Marcolini","C","Pierre Marcolini est un chef pâtissier-chocolatier et entrepreneur belge né le 12 juillet 1964 à Charleroi.",null,"fr:Pierre_Marcolini","c:e/e2/Pierre_Marcolini_dans_sa_boutique_de_la_place_du_Grand_Sablon_%28d%C3%A9cembre_2019%29_-_1.jpg"],["Q558440",379,"personnalite","Plastic Bertrand","R","Plastic Bertrand, nom de scène de Roger Jouret, né le 24 février 1954 à Bruxelles, est un chanteur, musicien, auteur-compositeur, producteur, éditeur et présentateur de télévision belge, surtout connu pour le titre Ça plane pour moi, une chanson pop punk de 1977.",109,"fr:Plastic_Bertrand","c:4/4c/Plastic-bertrand.jpg",{"cats":["belgique","chanteurs_fr"]}],["Q232785",380,"personnalite","Père Damien","R","Jozef de Veuster, né le 3 janvier 1840 à Tremelo en Belgique et mort le 15 avril 1889 à Molokaï à Hawaï, est un prêtre missionnaire catholique membre de la congrégation des Sacrés-Cœurs de Jésus et de Marie connu sous le nom de père Damien. Il est célèbre pour son travail de missionnaire dans le Pacifique, spécialement auprès des lépreux relégués par les gouvernements locaux sur l'île de Molokai à Hawaï. Durant son ministère, il contracta lui-même la lèpre en 1884.",118,"fr:Père_Damien","c:6/63/Father_Damien_in_1878%2C_HSA.jpg",{"cats":["belgique","religions"]}],["Q16672153",381,"personnalite","Raoul Hedebouw","PC","Raoul Hedebouw, né le 2 juillet 1977 à Liège, est un homme politique belge.",null,"fr:Raoul_Hedebouw","c:1/13/Raoul_Hedebouw_Bxl_Climate.jpg"],["Q50821956",382,"personnalite","Remco Evenepoel","M","Remco Evenepoel, né le 25 janvier 2000 à Alost, est un coureur cycliste belge, membre de l'équipe Red Bull-Bora-Hansgrohe. Il remporte notamment la Classique de Saint-Sébastien en 2019, 2022, 2023 et 2026, le championnat d'Europe du contre-la-montre en 2019 et 2025 ou encore le championnat d'Europe sur route en 2026.",101,"fr:Remco_Evenepoel","c:6/6f/Remco_Evenepoel_WC_2022.jpg",{"cats":["belgique","cyclisme","sports"]}],["Q7836",383,"personnalite","René Magritte","L","René Magritte, né le 21 novembre 1898 à Lessines et mort le 15 août 1967 à Schaerbeek, est un peintre surréaliste belge.",null,"fr:René_Magritte","c:4/46/Ren%C3%A9_Magritte_in_1961.jpg"],["Q313316",384,"personnalite","Romelu Lukaku","M","Romelu Lukaku, surnommé Big Rom, né le 13 mai 1993 à Anvers en Belgique, est un footballeur international belge qui joue au poste d'avant-centre au Fenerbahçe SK.",115,"fr:Romelu_Lukaku","c:f/f3/Romelu_Lukaku_Fenerbah%C3%A7e_20261103_%281%29.JPG",{"cats":["belgique","foot"]}],["Q312610",385,"personnalite","Salvatore Adamo","R","Salvatore Adamo est un auteur-compositeur-interprète italo-belge né le 1er novembre 1943 à Comiso en Sicile.",null,"fr:Salvatore_Adamo","c:4/48/Adamo_einde_show.jpg",{"cats":["belgique","chanteurs_fr"]}],["Q18434995",386,"personnalite","Sophie Wilmès","PC","Sophie Wilmès, née le 15 janvier 1975 à Ixelles, est une femme d'État belge francophone. Membre du Mouvement réformateur, elle est Première ministre entre octobre 2019 et octobre 2020 et la première femme à occuper ce poste en Belgique. Elle est désignée ministre d'État en mai 2026.","Sophie Wilmès, née le 15 janvier 1975 à Ixelles, est une femme d'État belge francophone.","fr:Sophie_Wilmès","c:e/ee/1718636579270_20240612_WILMES_Sophie_BE_02B.jpg"],["Q1344577",387,"personnalite","Stoffel Vandoorne","PC","Stoffel Vandoorne, né le 26 mars 1992 à Courtrai en Belgique, est un pilote automobile belge. Vice-champion en Formula Renault 3.5 Series 2013 et champion de GP2 Series 2015, il débute, après une pige en 2016, en Formule 1 comme pilote-titulaire au sein de l'équipe McLaren-Honda comme coéquipier de Fernando Alonso en 2017 et poursuit en 2018.","Stoffel Vandoorne, né le 26 mars 1992 à Courtrai en Belgique, est un pilote automobile belge.","fr:Stoffel_Vandoorne","c:5/59/2023-04-22_Motorsport%2C_ABB_FIA_Formula_E_World_Championship%2C_Berlin_E-Prix_2023_1DX_1062_by_Stepro.jpg",{"cats":["belgique","f1"]}],["Q313453",388,"personnalite","Stromae","L","Stromae, nom de scène de Paul Van Haver, né le 12 mars 1985 à Etterbeek, est un rappeur, chanteur, auteur-compositeur-interprète, producteur et styliste belge d’origine belgo-rwandaise.",98,"fr:Stromae","c:9/9c/Stromae_2011_cropped.jpg",{"cats":["belgique","chanteurs_fr"]}],["Q73360",389,"personnalite","Thibaut Courtois","L","Thibaut Courtois, né le 11 mai 1992 à Brée en Belgique, est un footballeur international belge qui joue au poste de gardien de but au Real Madrid.",115,"fr:Thibaut_Courtois","c:f/f7/Thibaut_Courtois_at_the_2018_World_Cup_%28cropped%29.jpg",{"cats":["belgique","foot"]}],["Q975283",390,"personnalite","Thierry Neuville","PC","Thierry Neuville, né le 16 juin 1988 à Saint-Vith, est un pilote de rallye belge. Engagé en championnat du monde des rallyes depuis 2012, il est titulaire au sein de l'équipe Hyundai World Rally Team depuis 2014. Il est sacré champion du monde des rallyes WRC en 2024, après avoir été 8 fois sur le podium: vice-champion du monde à cinq reprises et troisième trois fois.","Thierry Neuville, né le 16 juin 1988 à Saint-Vith, est un pilote de rallye belge.","fr:Thierry_Neuville","c:e/e0/2014_Rallye_Deutschland_by_2eight_8SC0443.jpg",{"cats":["belgique","moto"]}],["Q365567",391,"personnalite","Toots Thielemans","PC","Toots Thielemans, né Jean-Baptiste Frédéric Isidore Thielemans le 29 avril 1922 à Bruxelles et mort le 22 août 2016 à Braine-l'Alleud, est un musicien belge de jazz, harmoniciste et guitariste, parfois même siffleur, à la carrière internationale. Il obtient la double nationalité américaine.",117,"fr:Toots_Thielemans","c:b/ba/Toots_thielemans.jpg"],["Q49744",392,"personnalite","Victor Horta","PC","Victor Horta, né le 6 janvier 1861 à Gand et mort le 8 septembre 1947 à Bruxelles, est un architecte belge. Il est un des principaux acteurs de l'Art nouveau en Belgique.","Victor Horta, né le 6 janvier 1861 à Gand et mort le 8 septembre 1947 à Bruxelles, est un architecte belge.","fr:Victor_Horta","c:4/45/Victor_Horta_%28cropped%29.jpg",{"cats":["belgique","personnalites","architecture"]}],["Q201381",393,"personnalite","Vincent Kompany","M","Vincent Kompany, né le 10 avril 1986 à Uccle en Belgique, est un footballeur international belge reconverti en entraîneur. Il est actuellement en poste au Bayern Munich, en Bundesliga.",110,"fr:Vincent_Kompany","c:0/00/FC_Red_Bull_Salzburg_gegen_Bayern_M%C3%BCnchen_%282025-01-06_Testspiel%29_73.jpg",{"cats":["belgique","foot"]}],["Q15713449",395,"personnalite","Wout van Aert","E","Wout van Aert, né le 15 septembre 1994 à Herentals, est un coureur cycliste belge, membre de l'équipe Visma-Lease a Bike depuis 2019.",115,"fr:Wout_van_Aert","c:e/ed/WVA_Paris-Roubaix_2022.jpg",{"cats":["belgique","cyclisme","sports"]}],["Q247603",397,"personnalite","Zénobe Gramme","C","Zénobe Gramme est l'inventeur belge de la \"dynamo Gramme\", un générateur électrique à courant continu, aussi appelé machine de Gramme.",115,"fr:Zénobe_Gramme","c:8/88/Z%C3%A9nobe_Gramme_1893.jpg",{"cats":["belgique","personnalites"]}],["Q830697",398,"personnalite","Élisabeth de Belgique","E","Élisabeth de Saxe-Cobourg, princesse de Belgique et duchesse de Brabant, née le 25 octobre 2001 à Anderlecht, est un membre de la famille royale belge et la princesse héritière du trône de Belgique depuis l'accession au trône de son père, le roi des Belges Philippe, le 21 juillet 2013.",116,"fr:Élisabeth_de_Belgique","c:b/b7/Princess_Elisabeth_2025_%28crop%29.jpg"],["Q199614",399,"tradition","Armoiries de la Belgique","C","Les armoiries de la Belgique se composent d'un lion d'or, armé et lampassé de gueules, sur champ de sable. Elles sont issues des armes des ducs de Brabant. Elles sont déclinées en plusieurs niveaux:","Les armoiries de la Belgique se composent d'un lion d'or, armé et lampassé de gueules, sur champ de sable.","fr:Armoiries_de_la_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Great_coat_of_arms_of_Belgium.svg/330px-Great_coat_of_arms_of_Belgium.svg.png"],["Q2864685",400,"tradition","Art nouveau en Belgique","C","L'Art nouveau naît en Belgique en 1893, lorsque Victor Horta construit l'Hôtel Tassel.",null,"fr:Art_nouveau_en_Belgique","c:b/be/Govaerts_Gresham_Hall_2.JPG"],["Q19312856",401,"tradition","Balle pelote","C","La balle pelote également appelée jeu de balle est un sport collectif d’extérieur, de la famille des jeux de paume, opposant deux équipes de cinq joueurs qui se renvoient une petite balle, appelée pelote, en la frappant à la main munie d’un gant en cuir.",115,"fr:Balle_pelote","c:0/0f/Hoves_J2JPG.jpg"],["Q2894374",402,"tradition","Belgitude","C","La belgitude est un terme utilisé pour exprimer l'âme et l'identité des Belges.",null,"fr:Belgitude","https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Flag_of_Belgium.svg/330px-Flag_of_Belgium.svg.png"],["Q2668371",403,"tradition","Brusseleir","C","Le bruxellois, brusseleir, brusselair ou brusseleer est un parler populaire de la ville de Bruxelles, issu du brabançon, mâtiné de nombreux mots français. Il est repris à l'inventaire du patrimoine culturel immatériel de la Région de Bruxelles-Capitale.",109,"fr:Brusseleir","c:6/6c/T%C3%A5vlea_brusselw%C3%A8s.jpg"],["Q153571",404,"tradition","Brussels Airlines","R","Brussels Airlines est la compagnie aérienne nationale belge et est basée à l'aéroport de Bruxelles Zaventem où elle dessert plus de 120 destinations en Europe, Amérique du Nord, Afrique et Asie. Elle travaille en partage de code avec de nombreuses compagnies aériennes internationales afin d'offrir des destinations supplémentaires à ses passagers. La compagnie est membre de l'Association internationale du transport aérien ainsi que de la Star Alliance.",115,"fr:Brussels_Airlines","c:4/49/OO-SFH_%40_JFK%2C_2024-12-08.png",{"cats":["belgique","marques","transports"]}],["Q2710193",405,"tradition","Carnaval d'Alost","C","Le carnaval d’Alost est un rituel festif vieux de 600 ans qui se déroule chaque année à Alost en Flandre-Orientale, au Nord de la Belgique. Il dure trois jours à compter du dimanche qui précède le carême chrétien. Inscrit en 2010 sur la liste représentative du patrimoine culturel immatériel de l'humanité de l'UNESCO, il en est retiré en décembre 2019, ne respectant plus les critères d'inscriptions à la suite de représentations antisémites.",118,"fr:Carnaval_d'Alost","c:8/88/Eirg_2013.jpg",{"cats":["belgique","fetes"]}],["Q35330",406,"tradition","Carnaval de Binche","C","Le carnaval de Binche est un des plus anciens folklores de Belgique. Il a été reconnu en 2003, par l'UNESCO comme chef-d'œuvre du patrimoine oral et immatériel de l'humanité. Il est repris parmi les chefs-d’œuvre du Patrimoine oral et immatériel de la Fédération Wallonie-Bruxelles depuis 2004 et a été élevé au rang d’officier du Mérite wallon, le 23 février 2017.","Le carnaval de Binche est un des plus anciens folklores de Belgique.","fr:Carnaval_de_Binche","c:d/d5/2005_-_%27Gilles_de_Binche_portant_leur_Masque_de_Cire%27_-_Marie-Claire_Lef%C3%A9bure.jpg",{"cats":["belgique","fetes"]}],["Q190916",407,"tradition","Club Bruges KV","E","Le Club Brugge Koninklijke Voetbalvereniging, littéralement Club Bruges Royal Football Association, abrégé en Club Brugge KV, couramment appelé Club Brugge en néerlandais et Club Bruges ou « le Club » en français, ou encore en rapport avec son appellation initiale le Club brugeois, voire le FC Bruges en France, est un club de football belge fondé en 1891 et basé à Bruges.",114,"fr:Club_Bruges_KV","https://upload.wikimedia.org/wikipedia/fr/thumb/3/38/Logo_Club_Brugge_KV_2026.svg/330px-Logo_Club_Brugge_KV_2026.svg.png",{"cats":["belgique","foot"]}],["Q6566971",408,"tradition","Colombophilie","C","La colombophilie est l'art d'élever et de faire concourir les pigeons voyageurs.",null,"fr:Colombophilie","c:6/60/Postduiven.jpg"],["Q12989",409,"tradition","Drapeau de Flandre","C","Le drapeau de Flandre, appelé aussi le lion flamand, lion de Flandre ou drapeau au lion, est l’emblème du Comté de Flandre. Il est depuis la disparition du comté utilisé de manière officielle ou informelle par divers entités, organismes ou populations en Région flamande en Belgique, en Flandre française dans le Nord et le Pas-de-Calais en France et en Flandre zélandaise aux Pays-Bas.",114,"fr:Drapeau_de_Flandre","https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Generieke_vlag_van_Vlaanderen.svg/330px-Generieke_vlag_van_Vlaanderen.svg.png"],["Q12990",410,"tradition","Drapeau de la Belgique","R","Le drapeau de la Belgique est composé de trois bandes verticales; noire, jaune et rouge.",null,"fr:Drapeau_de_la_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Flag_of_Belgium_%28civil%29.svg/330px-Flag_of_Belgium_%28civil%29.svg.png",{"cats":["belgique","geo"]}],["Q3040732",411,"tradition","Ducasse","C","La ducasse est une fête populaire annuelle des villages et villes, en Belgique et dans le nord de la France, organisée généralement le jour de la fête du saint patron de la localité. Les régions davantage influencées par la langue flamande parlent également de « kermesse ». Dans le nord de la France ducasse se traduit également aujourd'hui par fête foraine.",118,"fr:Ducasse","c:e/e4/Image050522_Mons_Car_d%27Or_JPG01.jpg"],["Q1945581",412,"tradition","Ducasse de Mons","C","La Ducasse de Mons ou Doudou est une fête locale basée sur des traditions ancestrales qui a lieu tous les ans, le week-end de la Trinité, à Mons en Belgique, ville située dans la province de Hainaut. On l'appelle souvent le Doudou, d'après le nom d'un air traditionnel que l'on joue durant les festivités",113,"fr:Ducasse_de_Mons","c:a/a5/DragonLumecon.jpg",{"cats":["belgique","fetes"]}],["Q2597696",413,"tradition","Festival de Dour","C","Le festival de Dour, ou Dour Festival, est un festival européen de genres musicaux alternatifs, indépendants, et multiculturels organisé par Dour Festival SA et Go Go Go! asbl, se déroulant chaque été en Belgique à Dour, près de Mons, durant 5 jours, sur le parc éolien de Dour, près de la frontière française en province de Hainaut.",112,"fr:Festival_de_Dour","c:8/82/Dour_Festival.jpg",{"cats":["belgique","electro","fetes"]}],["Q570091",414,"tradition","Festival international du film francophone de Namur","C","Le Festival International du film francophone de Namur a été créé en 1986, sous le nom de Festival cinématographique de Wallonie.",119,"fr:Festival_international_du_film_francophone_de_Namur","https://upload.wikimedia.org/wikipedia/en/thumb/d/d3/Logo_of_FIFF_Namur%2C_2020.png/330px-Logo_of_FIFF_Namur%2C_2020.png"],["Q499192",415,"tradition","Flèche wallonne","PC","La Flèche wallonne est une course cycliste d'un jour, une classique, se disputant en Belgique au printemps. Cette course est inscrite au programme du ProTour de 2005 à 2007, puis du Calendrier mondial UCI en 2009 et 2010, et enfin de l'UCI World Tour en 2011.","La Flèche wallonne est une course cycliste d'un jour, une classique, se disputant en Belgique au printemps.","fr:Flèche_wallonne","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2b/LFW.png/330px-LFW.png",{"cats":["belgique","cyclisme"]}],["Q232415",416,"tradition","Franc belge","C","Le franc belge est une unité monétaire de la Belgique, en vigueur de 1832 au 1er janvier 1999, date à laquelle il est devenu une subdivision de l'euro. Les billets de banque et les pièces libellés ont continué de circuler pendant une période de transition jusqu'au 1er mars 2002. Le franc était divisé en 100 centimes.",117,"fr:Franc_belge","https://upload.wikimedia.org/wikipedia/fr/thumb/0/05/Coin_BE_1F_Albert_II_rev_FR_96.png/330px-Coin_BE_1F_Albert_II_rev_FR_96.png"],["Q2440746",417,"tradition","Fête de Wallonie","C","La Fête de Wallonie est célébrée le troisième dimanche de septembre. Elle trouve son origine dans la fête de la communauté française de Belgique qui a lieu le 27 septembre, commémorant la victoire des volontaires lors des Quatre Jours de Bruxelles, l'un des épisodes de la révolution belge de 1830.","La Fête de Wallonie est célébrée le troisième dimanche de septembre.","fr:Fête_de_Wallonie","https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Flag_of_Wallonia.svg/330px-Flag_of_Wallonia.svg.png"],["Q2190144",418,"tradition","Fête nationale belge","C","La fête nationale belge désigne les festivités annuelles menées en l'honneur du royaume de Belgique.",null,"fr:Fête_nationale_belge","c:3/38/Nationale_feestdag_Belgi%C3%AB_1880.jpg",{"cats":["belgique","fetes"]}],["Q2458774",419,"tradition","Gille","C","Le Gille est un personnage de carnaval en Belgique. Les plus célèbres sont les Gilles de Binche dans la région du Centre.","Le Gille est un personnage de carnaval en Belgique.","fr:Gille","c:7/70/0_Binche_-_Les_Gilles_le_jour_du_mardi_gras_%281%29.JPG"],["Q7954",420,"tradition","Grand Prix automobile de Belgique","PC","Le Grand Prix de Belgique est une course automobile qui fait partie du championnat du monde de Formule 1. Cette course s'est disputée au cours de l'histoire sur cinq circuits différents: le circuit d'Anseremme-Dinant, le circuit de Nivelles, le circuit de Zolder, le circuit du bois de la Cambre, le plus célèbre et le plus utilisé de tous étant le circuit de Spa-Francorchamps. Ce dernier a eu deux versions, la première jusqu'en 1970 et la seconde sous une forme modifiée et raccourcie après 1983.","Le Grand Prix de Belgique est une course automobile qui fait partie du championnat du monde de Formule 1.","fr:Grand_Prix_automobile_de_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Spa-Francorchamps_of_Belgium.svg/330px-Spa-Francorchamps_of_Belgium.svg.png",{"cats":["belgique","f1"]}],["Q340069",421,"tradition","Géants de processions et de cortèges","C","Les géants sont des figures importantes du folklore européen, ils sont présents dans des processions et des cortèges de pays du monde entier. Il s'agit soit de personnages soit parfois de dragons ou d'animaux fabuleux, de symboles, d'objets... Les géants processionnels, mannequins d'osier, de bois, de métal ou parfois même de plastique sont promenés dans les cortèges et autres fêtes de villes et villages. Ils sont l'une des bases les plus vivaces du folklore de Catalogne, du Nord de la France et de la Belgique.",119,"fr:Géants_de_processions_et_de_cortèges","c:a/ae/Merc%C3%A8_2012_-_Gegants_del_Pi_i_Santa_Maria_del_Mar.JPG"],["Q1808937",422,"tradition","Kermesse","R","Une kermesse est, en Belgique, en France, au Luxembourg et en Suisse romande, une fête paroissiale, patronale, de bienfaisance ou une foire annuelle.",113,"fr:Kermesse","c:d/d6/Pieter_Bruegel_d._%C3%84._015.jpg"],["Q161539",423,"tradition","La Brabançonne","PC","La Brabançonne est une chanson tacitement reconnue comme étant l'hymne national de la Belgique, sans toutefois qu'aucune mention ne soit faite, ni de l'œuvre en question, ni même d'un hymne pour le royaume, tant au Moniteur belge que dans la Constitution du pays, contrairement aux « symboles nationaux » disposés par l'article 193.",110,"fr:La_Brabançonne","c:1/10/Partition9.jpg"],["Q2322300",424,"tradition","Langues en Belgique","R","La Belgique dispose de trois langues officielles comme langues nationales: l'allemand, le français, le néerlandais.",null,"fr:Langues_en_Belgique","c:6/6e/Languages_Belgium.png"],["Q1196401",425,"tradition","Le Chant des Wallons","C","Le Chant des Wallons est l'hymne officiel de la Région wallonne conformément au décret du 23 juillet 1998 créant un hymne wallon.",115,"fr:Le_Chant_des_Wallons","c:0/0d/Wallonia_National_Anthem.png"],["Q690672",426,"tradition","Le Soir","C","Le Soir est un quotidien généraliste belge de langue française fondé en 1887 par Émile Rossel. Il fait partie du Groupe Rossel. Se présentant comme progressiste et indépendant, ce journal est de tradition libérale et historiquement au centre de l'échiquier politique belge.","Le Soir est un quotidien généraliste belge de langue française fondé en 1887 par Émile Rossel.","fr:Le_Soir","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/Le_Soir.jpg/330px-Le_Soir.jpg"],["Q2192325",427,"tradition","Les Ardentes","C","Les Ardentes est le nom d'un festival de musique qui se déroule début juillet à Liège. Au départ sous-titré électro-rock, le festival s'ouvre rapidement à toutes les musiques pop, rock, musiques électroniques, chanson française mais aussi hip-hop et même jazz avant de devenir essentiellement un festival de hip-hop et de musiques urbaines à partir de 2018.","Les Ardentes est le nom d'un festival de musique qui se déroule début juillet à Liège.","fr:Les_Ardentes","c:9/9e/Les_Ardentes_2022.jpg"],["Q34009",428,"tradition","Liège-Bastogne-Liège","R","Liège-Bastogne-Liège, créée en 1892 par le Pesant Club Liégeois et le Liege Cyclist Union en Belgique, est une course cycliste sur route annuelle belge, réservée aux professionnels. Elle est l'une des plus anciennes des courses cyclistes encore disputées, ce qui lui vaut le surnom de « Doyenne ». Son parcours accidenté de 260 km en fait l'une des classiques les plus exigeantes et les plus prestigieuses.",117,"fr:Liège-Bastogne-Liège","https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Li%C3%A8ge%E2%80%93Bastogne%E2%80%93Li%C3%A8ge_logo.svg/330px-Li%C3%A8ge%E2%80%93Bastogne%E2%80%93Li%C3%A8ge_logo.svg.png",{"cats":["belgique","cyclisme","sports"]}],["Q1532699",429,"tradition","Marches de l'Entre-Sambre-et-Meuse","C","Les Marches de l'Entre-Sambre-et-Meuse sont un ensemble de marches folkloriques, se déroulant de mai à octobre, en Belgique dans l'Entre-Sambre-et-Meuse. D'anciennes processions religieuses dédiées à des saints locaux, protecteurs des paroisses ont pris au fil des temps un caractère folklorique, sans cependant que l'aspect religieux en soit totalement perdu. Elles sont accompagnées d'escortes armées, également traditionnelles.",114,"fr:Marches_de_l'Entre-Sambre-et-Meuse","c:2/20/Acoz_Fo8JPG.jpg"],["Q21052026",430,"tradition","Meyboom","C","La plantation du Meyboom est la plus ancienne tradition bruxelloise, attestée depuis 1308. Elle a lieu chaque année le 9 août, veille de la saint-Laurent, et consiste principalement à planter un hêtre au carrefour de la rue des Sables et de la rue du Marais dans le quartier Marais-Jacqmain de la ville de Bruxelles. L'exercice s'accompagne de cortèges et de diverses activités folkloriques au cours de la journée.","La plantation du Meyboom est la plus ancienne tradition bruxelloise, attestée depuis 1308.","fr:Meyboom","c:e/ed/Meyboom_%2814%29.jpg"],["Q1682845",431,"tradition","Métro léger de Charleroi","C","Le métro léger de Charleroi est un réseau de transport en commun de l’agglomération de Charleroi en Belgique, de type métro léger ou semi-métro.",117,"fr:Métro_léger_de_Charleroi","c:f/f3/Soleilmont_tram_%283%29.JPG"],["Q1404296",432,"tradition","Néerlandais de Belgique","C","En Belgique, le néerlandais est une des trois langues officielles et la langue maternelle d'environ 60 % de la population. Il est l'unique langue officielle de la Région flamande et une des langues officielles de la Région de Bruxelles-Capitale à côté du français. Les deux autres langues officielles de la Belgique sont le français et l'allemand.",110,"fr:Néerlandais_de_Belgique","c:a/a8/Faciliteitengemeenten_fr.png"],["Q2470659",433,"tradition","Ommegang de Bruxelles","C","L'Ommegang de Bruxelles est un cortège folklorique bruxellois qui a lieu actuellement deux fois, les premiers mercredi et vendredi du mois de juillet, sur la Grand-Place de Bruxelles.",118,"fr:Ommegang_de_Bruxelles","c:3/3d/Arbal%C3%A9trier_du_Sablon.jpg"],["Q3130130",434,"tradition","Procession du Saint-Sang","C","La procession du Saint-Sang est une grande procession religieuse, datant du Moyen Âge, qui a lieu chaque année le jour de l'Ascension à Bruges, en Belgique.",118,"fr:Procession_du_Saint-Sang","c:e/e8/Relic_of_the_Holy_Blood_-_Brugges.jpg"],["Q1190356",435,"tradition","Radio-télévision belge de la Communauté française","PC","La Radio-télévision belge de la Communauté française est une entreprise publique belge, chargée de la radio et de la télévision pour la Communauté française de Belgique. Elle succède, le 12 décembre 1977, à la Radiodiffusion-télévision belge. Elle a actuellement une offre radio, une offre télévisuelle et une offre Internet.",116,"fr:Radio-télévision_belge_de_la_Communauté_française","",{"cats":["belgique","tele"]}],["Q1547650",436,"tradition","Rock Werchter","C","Rock Werchter est un festival de musique annuel, qui se déroule début juillet à Werchter en Belgique. Il est un des plus importants festivals de musique au monde, de par les artistes qui le fréquentent chaque année.","Rock Werchter est un festival de musique annuel, qui se déroule début juillet à Werchter en Belgique.","fr:Rock_Werchter","c:6/6f/Plaine_Werchter_2010.jpg",{"cats":["belgique","fetes"]}],["Q19585",437,"tradition","Royal Charleroi Sporting Club","PC","Le Royal Charleroi Sporting Club, couramment appelé Sporting de Charleroi, est un club belge de football basé dans la ville de Charleroi. Le club évolue lors de la saison 2026-2027 en Jupiler Pro League, plus haut niveau du football belge. C'est sa 99e saison en séries nationales et sa 62e parmi l'élite.",117,"fr:Royal_Charleroi_Sporting_Club","https://upload.wikimedia.org/wikipedia/fr/thumb/9/93/Sporting_de_Charleroi_%28logo%29.svg/330px-Sporting_de_Charleroi_%28logo%29.svg.png",{"cats":["belgique","foot"]}],["Q187528",438,"tradition","Royal Sporting Club Anderlecht","R","Le Royal Sporting Club d'Anderlecht, abrégé en RSC Anderlecht, est un club de football belge fondé en 1908 et situé sur la commune d'Anderlecht, dans la banlieue ouest de Bruxelles. Le club évolue lors de la saison 2026-2027 en Jupiler Pro League, premier niveau du football belge. C'est sa 107e saison en séries nationales et sa 97e parmi l'élite.",119,"fr:Royal_Sporting_Club_Anderlecht","https://upload.wikimedia.org/wikipedia/fr/thumb/c/cc/Logo_RSC_Anderlecht_2023.svg/330px-Logo_RSC_Anderlecht_2023.svg.png",{"cats":["belgique","foot"]}],["Q196160",439,"tradition","Royale Union saint-gilloise","R","La Royale Union saint-gilloise, abrégée en Union saint-gilloise ou plus communément L’Union, est un club de football belge fondé en 1897 et basé sur la commune de Forest, bien qu'il fasse référence à la commune voisine de Saint-Gilles, également située dans le sud de la Région de Bruxelles-Capitale. Le club évolue lors de la saison 2026-2027 en Jupiler Pro League, plus haut niveau du football belge. C'est sa 118e saison en séries nationales et sa 64e parmi l'élite.",116,"fr:Royale_Union_saint-gilloise","https://upload.wikimedia.org/wikipedia/fr/thumb/8/87/Logo_Royale_Union_Saint-Gilloise_2025.svg/330px-Logo_Royale_Union_Saint-Gilloise_2025.svg.png",{"cats":["belgique","foot"]}],["Q760225",440,"tradition","Saint-Nicolas","R","La fête de la Saint-Nicolas est issue de la célébration religieuse du 6 décembre, telle que fixée par le calendrier liturgique de l'Église catholique. Prenant de l'ampleur et quittant le cadre strictement religieux au fil des temps, elle met en scène saint Nicolas, un personnage quasi légendaire inspiré de l'évêque lycien Nicolas de Myre et de son compatriote, mais ayant vécu deux siècles plus tard, le moine Nicolas de Sion, dont les traditions hagiographiques se confondent à tort depuis le Xe siècle.",115,"fr:Saint-Nicolas_(fête)","c:7/7d/Sinterklaas_2007.jpg",{"cats":["belgique","religions","fetes"]}],["Q524255",441,"tradition","Société nationale des chemins de fer belges","PC","La Société nationale des chemins de fer belges, en néerlandais: Nationale Maatschappij der Belgische Spoorwegen, est l'entreprise ferroviaire publique belge créée en 1926.",116,"fr:Société_nationale_des_chemins_de_fer_belges","https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/SNCB_logo.svg/330px-SNCB_logo.svg.png"],["Q190561",442,"tradition","Standard de Liège","R","Le Standard de Liège est un club de football belge de la ville de Liège. Le club évolue lors de la saison 2026-2027 en Jupiler Pro League, premier niveau du football belge. C'est sa 112e saison en séries nationales et sa 110e parmi l'élite, ce qui constitue le record national.","Le Standard de Liège est un club de football belge de la ville de Liège.","fr:Standard_de_Liège","https://upload.wikimedia.org/wikipedia/fr/thumb/3/33/Logo_Standard_de_Li%C3%A8ge_2019.svg/330px-Logo_Standard_de_Li%C3%A8ge_2019.svg.png",{"cats":["belgique","foot"]}],["Q2498881",443,"tradition","Tchantchès","C","Tchantchès, parfois écrit Tchantchèt, est un personnage issu du folklore liégeois représenté par une marionnette.",null,"fr:Tchantchès","c:4/4d/Marionnettistes.jpg"],["Q606649",444,"tradition","Tomorrowland","R","Tomorrowland est un festival de musique électronique organisé les deux derniers week-ends de juillet sur le site du domaine provincial De Schorre à Boom, Région flamande, en Belgique.",115,"fr:Tomorrowland_(festival)","c:9/97/Tomorrowland_2026_Mainstage_Night_Show_Boom_Belgium.jpg",{"cats":["belgique","electro","fetes"]}],["Q33970",445,"tradition","Tour des Flandres","R","Le Tour des Flandres, aussi connu comme « De Ronde », est une course cycliste sur route annuelle belge, réservée aux professionnels. Il a lieu en avril, souvent le premier dimanche du mois qui peut également être le dimanche de Pâques, en Flandre et est depuis des années une des Classiques flandriennes les plus importantes. Le Tour a eu une seule interruption, pendant la Première Guerre mondiale, et est organisé depuis 1919 de manière ininterrompue, la plus longue série de toutes les classiques cyclistes.",116,"fr:Tour_des_Flandres","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/RVV_LOGO_ENG.svg/330px-RVV_LOGO_ENG.svg.png",{"cats":["belgique","cyclisme"]}],["Q34219",446,"tradition","Wallon","PC","Le wallon est une langue d'oïl parlée en Belgique, en France, et très résiduellement dans la partie nord-est de l'État américain du Wisconsin. Elle est reconnue comme langue régionale endogène par la Communauté française de Belgique, au sein de laquelle elle est la plus importante des langues romanes endogènes en superficie et en effectifs.",118,"fr:Wallon","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Langues_d%27o%C3%AFl_2.svg/330px-Langues_d%27o%C3%AFl_2.svg.png",{"cats":["belgique","langues"]}],["Q3576332",447,"tradition","Zwanze","C","La zwanze est un type d'humour gouailleur proche de l’autodérision, associé à Bruxelles.",null,"fr:Zwanze",""],["Q3577413",448,"tradition","Échasseurs namurois","C","Les Échasseurs namurois sont des jouteurs sur échasses de la ville de Namur, en Belgique. Le terme échasseur provient du wallon namurois chacheu, qui désigne le jouteur sur échasses. Actifs depuis plus de 600 ans, les Échasseurs namurois sont un des plus vieux groupe d’ėchassiers du monde.","Les Échasseurs namurois sont des jouteurs sur échasses de la ville de Namur, en Belgique.","fr:Échasseurs_namurois","c:6/63/Echasseurs-Echasse-Or-Fetes-de-Wallonie-3-Skuds.jpg"],["Q166776",449,"tradition","Équipe de Belgique de football","L","L'équipe de Belgique de football est la sélection de joueurs belges représentant le pays lors des compétitions internationales de football masculin, sous l'égide de la Royal Belgian Football Association.",110,"fr:Équipe_de_Belgique_de_football","https://upload.wikimedia.org/wikipedia/fr/thumb/6/65/Logo_F%C3%A9d%C3%A9ration_Belge_Football_2019.svg/330px-Logo_F%C3%A9d%C3%A9ration_Belge_Football_2019.svg.png",{"cats":["belgique","foot"]}],["Q815514",451,"tradition","Équipe de Belgique masculine de hockey sur gazon","C","L'équipe de Belgique masculine de hockey sur gazon est l'équipe nationale qui représente la Belgique dans les compétitions internationales masculines de hockey sur gazon. Elle est placée sous l'égide de l'Association Royale Belge de Hockey. L'équipe est affiliée à la FIH depuis 1924. Elle est surnomée \"Red Lions\".",109,"fr:Équipe_de_Belgique_masculine_de_hockey_sur_gazon","https://upload.wikimedia.org/wikipedia/fr/thumb/7/74/Association_Royale_Belge_de_Hockey.png/330px-Association_Royale_Belge_de_Hockey.png"],["Q860150",454,"histoire","Bataille de Charleroi","C","La bataille de Charleroi ou bataille de la Sambre, est l'appellation donnée à l'ensemble des combats qui se sont déroulés sur la rivière Sambre entre la frontière franco-belge et la position fortifiée de Namur du 21 au 23 août 1914 lors de la Première Guerre mondiale. Ils ont opposé la 5e armée française du général Lanrezac à la IIe armée allemande du général von Bülow. Ils font partie de la bataille des Frontières.",112,"fr:Bataille_de_Charleroi","c:7/79/Battles_of_Charleroi_and_Mons_map.png"],["Q44732",455,"histoire","Bataille de Courtrai","PC","La bataille de Courtrai de 1302, également connue sous le nom de bataille des Éperons d'or, opposa, le 11 juillet 1302, près de Courtrai, l'armée du roi de France Philippe le Bel surnommée les leliaerts aux milices communales flamandes surnommées les klauwaerts.",119,"fr:Bataille_de_Courtrai_(1302)","c:7/73/Bataille_de_Courtrai_%281302%29_-_Fran%C3%A7ais_2813.png",{"cats":["belgique","histoire"]}],["Q678227",456,"histoire","Bataille de Fleurus","PC","La bataille de Fleurus a lieu le 26 juin 1794 pendant la guerre de la Première Coalition entre les coalisés et la France. L'armée révolutionnaire française remporte une bataille décisive à Fleurus, entre Charleroi et Namur, dans les Pays-Bas autrichiens.",113,"fr:Bataille_de_Fleurus_(1794)","c:e/e5/Bataille_de_Fleurus_1794.JPG"],["Q1653331",457,"histoire","Bataille de l'Yser","PC","La bataille de l’Yser est l'appellation donnée à l'ensemble des combats qui se sont déroulés du 17 au 31 octobre 1914 et qui ont opposé les unités allemandes qui voulaient franchir le fleuve Yser en direction de Dunkerque aux troupes belges et françaises qui essayaient de les y arrêter. Une vaste inondation, déclenchée fin octobre, a réussi à stopper définitivement la progression des assaillants.",117,"fr:Bataille_de_l'Yser","c:2/28/WW1_Western_Front_at_Nieuport.jpg",{"cats":["belgique","histoire"]}],["Q855429",458,"histoire","Bataille de Ligny","PC","La bataille de Ligny, également appelée bataille de Fleurus, opposa l'armée prussienne menée par le maréchal Blücher à une partie de l'armée française commandée par Napoléon Ier. Elle se déroula le 16 juin 1815, soit deux jours avant la bataille de Waterloo. Ligny fut la dernière victoire de Napoléon.",118,"fr:Bataille_de_Ligny","c:2/2b/Crofts_Ernest_The_Battle_Of_Ligny.jpg"],["Q426227",459,"histoire","Bataille de Passchendaele","R","La bataille de Passchendaele, aussi appelée troisième bataille d’Ypres, a eu lieu du 31 juillet au 10 novembre 1917 en Flandre occidentale, Belgique, pendant la Première Guerre mondiale. Avant l’offensive, le front occidental était marqué par une impasse après les batailles de la Somme et d’Arras, tandis que les sous-marins allemands menaçaient les liaisons maritimes alliées depuis les ports belges.",118,"fr:Bataille_de_Passchendaele","c:e/e6/Chateauwood.jpg",{"cats":["belgique","histoire"]}],["Q48314",460,"histoire","Bataille de Waterloo","L","La bataille de Waterloo s'est déroulée le 18 juin 1815, en Belgique, à vingt kilomètres au sud de Bruxelles, dans l'actuelle province du Brabant wallon. Cette bataille a opposé l'armée française dite Armée du Nord, dirigée par l'empereur Napoléon Ier, à l'armée des Alliés, dirigée par le duc de Wellington et composée de Britanniques, d'Allemands et de Néerlandais, rejointe par l'armée prussienne commandée par le maréchal Blücher. Elle s'est achevée par la défaite décisive de l'armée française.",113,"fr:Bataille_de_Waterloo","c:4/48/De_Slag_bij_Waterloo_Rijksmuseum_SK-A-1115.jpeg",{"cats":["belgique","histoire"]}],["Q151018",461,"histoire","Bataille des Ardennes","L","La bataille des Ardennes est l'ensemble des opérations militaires de la Seconde Guerre mondiale qui se sont déroulées en Ardenne pendant l'hiver 1944-1945. Le théâtre des opérations se déroule presque exclusivement en Belgique et dans le nord du Luxembourg, principalement dans l'Ardenne belge et l'Éislek luxembourgeois, avec pour objectif final de la part des Allemands la reconquête du port d'Anvers, mais leur offensive sera stoppée avant même d'atteindre la Meuse.",117,"fr:Bataille_des_Ardennes","c:b/bd/American_290th_Infantry_Regiment_infantrymen_fighting_in_snow_during_the_Battle_of_the_Bulge.jpg",{"cats":["belgique","histoire"]}],["Q1377716",462,"histoire","Belges","R","Les Belges sont les citoyens, définis par le droit belge et le droit international, du royaume de Belgique, État fédéral d'Europe de l'Ouest, qu'ils en soient natifs, ou non. Linguistiquement, ils peuvent être néerlandophones, francophones ou germanophones.",112,"fr:Belges_(nationalité)","c:d/de/Collage_van_25_beroemde_Belgen.png"],["Q13116",463,"histoire","Benelux","R","L'Union Benelux, plus communément appelée Benelux, est une union à l’origine économique entre la Belgique, les Pays-Bas et le Luxembourg dont le nom est un acronyme formé par les syllabes initiales des noms de ces trois pays dans leurs langues d'origine — Belgique ou België ou Belgien, Nederland et Luxembourg —.",119,"fr:Benelux","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Benelux.svg/330px-Benelux.svg.png"],["Q16874544",464,"histoire","Catastrophe du Bois du Cazier","C","La catastrophe du Bois du Cazier ou catastrophe de Marcinelle est la plus importante catastrophe minière survenue en Belgique au charbonnage du Bois du Cazier à Marcinelle, le 8 août 1956. Elle causa la mort de 262 mineurs. Couvert par la presse internationale pendant de nombreuses semaines, ce drame fut à l'origine d'une prise de conscience de la condition des mineurs dans cette industrie.",116,"fr:Catastrophe_du_Bois_du_Cazier","c:d/de/Catastrophe_Marcinelle.jpg"],["Q959309",465,"histoire","Charbonnage","C","Un charbonnage ou une houillère est une mine de houille, c'est-à-dire un lieu d'extraction du charbon.",null,"fr:Charbonnage","c:6/62/Le_Petit_Fran%C3%A7ais_ill_Mus%C3%A9e_scolaire_-_La_mine.jpg"],["Q89959",466,"histoire","Communauté française de Belgique","PC","La Communauté française de Belgique, ou Fédération Wallonie-Bruxelles dans ses communications usuelles mais non officielles depuis 2011, est l'une des trois communautés linguistiques de la Belgique. Elle exerce ses compétences sur le territoire de la région de langue française et de la région bilingue de Bruxelles-Capitale, laquelle fait également partie de la Communauté flamande, mais où le français est néanmoins majoritaire.",111,"fr:Communauté_française_de_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Flag_of_Wallonia.svg/330px-Flag_of_Wallonia.svg.png"],["Q157070",467,"histoire","Comté de Flandre","R","Le comté de Flandre, d'abord pagus de l'Empire carolingien, placé par le traité de Verdun à la frontière nord de la Francie occidentale, devient en 863 une principauté détenue héréditairement par la maison de Flandre, puis un fief vassal des rois de France pendant tout le Moyen Âge.",115,"fr:Comté_de_Flandre","https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Locator_County_of_Flanders_%281350%29.svg/330px-Locator_County_of_Flanders_%281350%29.svg.png"],["Q309460",468,"histoire","Comté de Hainaut","PC","Le comté de Hainaut ou Hainau est un ancien comté qui relevait du Saint-Empire romain germanique et se trouvait en bordure du royaume de France.",114,"fr:Comté_de_Hainaut","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Locator_County_of_Hainaut_%281350%29.svg/330px-Locator_County_of_Hainaut_%281350%29.svg.png"],["Q599613",469,"histoire","Comté de Namur","C","Le comté de Namur est un ancien comté qui relevait du Saint-Empire romain germanique, qui se trouvait entre la principauté de Liège, le duché de Brabant et le comté de Hainaut. Il comprenait les villes de Namur, Charleroi, Givet, Bouvignes, Mariembourg et Fleurus.",110,"fr:Comté_de_Namur","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Low_Countries_Locator_Namur.svg/330px-Low_Countries_Locator_Namur.svg.png"],["Q213510",470,"histoire","Congo belge","R","Congo belge est le nom porté par le territoire formant l’actuelle république démocratique du Congo lorsqu'il était une colonie de la Belgique entre le 15 novembre 1908, et le 30 juin 1960, date de l’indépendance du Congo belge, qui devient le Zaïre puis la RDC. Il faisait partie de l'empire colonial belge, dont il était, de loin, le plus grand territoire.",118,"fr:Congo_belge","c:d/d6/Belgian_Congo_locator_map.png"],["Q2246772",471,"histoire","Congrès national","C","Le Congrès national est la première assemblée législative et constituante de la Belgique, notamment chargée d'élaborer la Constitution belge. Élu en novembre 1830 au suffrage censitaire et capacitaire, il compte deux cents membres et est monocaméral. Il est dissous en août 1831 et remplacé par le Parlement.",118,"fr:Congrès_national_(Belgique)","https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Medal_of_the_Belgian_electoral_law_of_1831_%281%29.tif/330px-Medal_of_the_Belgian_electoral_law_of_1831_%281%29.tif.png"],["Q633629",472,"histoire","Constitution de la Belgique","C","La Constitution belge actuelle est la seule et unique norme juridique suprême qu'ait jamais eu la Belgique. Elle est dite « Constitution du 7 février 1831 » ou « Constitution du 17 février 1994 » car elle a été votée le 7 février 1831 par le Congrès national mais elle a été coordonnée le 17 février 1994.","La Constitution belge actuelle est la seule et unique norme juridique suprême qu'ait jamais eu la Belgique.","fr:Constitution_de_la_Belgique","c:5/55/Constitution_de_la_Belgique_de_1831_%28page_1_crop%29.jpg"],["Q2661931",473,"histoire","Crise politique belge de 2007-2011","C","La crise politique belge de 2007-2011 désigne une période de tensions communautaires et d'instabilité politique en Belgique, provoquée par des opinions divergentes sur les réformes de l'État belge et sur l'existence persistance de la circonscription électorale controversée de Bruxelles-Hal-Vilvorde.",114,"fr:Crise_politique_belge_de_2007-2011",""],["Q159856",474,"histoire","Duché de Brabant","PC","Le duché de Brabant est un État féodal issu du démembrement de la Basse-Lotharingie en 1106 et est intégré au Saint-Empire romain germanique. Sa frontière occidentale est l'Escaut, qui le sépare du comté de Flandre, fief du royaume de France jusqu'en 1526.",109,"fr:Duché_de_Brabant","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Locator_Duchy_of_Brabant_%281350%29.svg/330px-Locator_Duchy_of_Brabant_%281350%29.svg.png"],["Q74035",475,"histoire","Exposition universelle de Bruxelles de 1958","PC","L'Exposition universelle de 1958, officiellement Exposition universelle et internationale de Bruxelles, est une exposition internationale organisée à Bruxelles, en Belgique, du 17 avril au 19 octobre 1958 sur le plateau du Heysel et attire près de 42 millions de visiteurs.",111,"fr:Exposition_universelle_de_Bruxelles_de_1958","c:4/47/Ev._Pavillon_auf_der_EXPO_in_Br%C3%BCssel_%2827751784452%29.jpg",{"cats":["belgique","histoire"]}],["Q15042135",476,"histoire","Frontière linguistique en Belgique","C","La frontière linguistique en Belgique est une frontière administrative interne à la Belgique fixée le 8 novembre 1962 et qui partage géographiquement le pays en deux territoires: l'un de langue néerlandaise, au nord, et l'autre de langue française, au sud. Elle est la conséquence des tensions communautaires et linguistiques qui règnent dans le Royaume.",117,"fr:Frontière_linguistique_en_Belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/BelgieGemeenschappenkaart.svg/330px-BelgieGemeenschappenkaart.svg.png"],["Q206443",477,"histoire","Gaule belgique","PC","La Gaule belgique, aussi écrite « Gaule Belgique », est une des quatre provinces créées par Auguste au début de son principat à partir des conquêtes effectuées par Jules César en Gaule entre 58 et 51/50 av. J.-C.",115,"fr:Gaule_belgique","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Roman_Empire_-_Belgica_%28125_AD%29.svg/330px-Roman_Empire_-_Belgica_%28125_AD%29.svg.png"],["Q3118395",478,"histoire","Grève générale de l'hiver 1960-1961","C","La grève générale de l'hiver 1960-1961, déclenchée contre le programme d'austérité du gouvernement belge de Gaston Eyskens, dura six semaines et paralysa principalement la Wallonie, la reprise du travail étant massive en Flandre après quelques jours.",114,"fr:Grève_générale_de_l'hiver_1960-1961","c:b/b5/Demonstraties_in_Brussel_tegen_de_Eenheidswet%2C_demonstrerende_stakers%2C_Bestanddeelnr_911-9323.jpg"],["Q3137058",479,"histoire","Histoire de la Belgique de 1914 à 1945","C","L’histoire de la Belgique de 1914 à 1945 est principalement marquée par les deux guerres mondiales.",null,"fr:Histoire_de_la_Belgique_de_1914_à_1945","c:6/67/Cartload_of_Belgian_government_public_records%2C_books_and_documents_as_it_flees_German_Army_1914.jpg"],["Q107560397",480,"histoire","Inondations de juillet 2021 en Belgique","C","Les inondations de 2021 en Belgique font partie d'une série d'inondations qui affectent l'Europe de l'ouest depuis le 13 juillet. En Belgique, les provinces de Hainaut, de Namur, de Liège, de Luxembourg, du Brabant wallon, de Limbourg et la Région de Bruxelles-Capitale sont touchées. En plus d’importants dégâts matériels, 39 victimes ont perdu la vie au cours de ces inondations.",117,"fr:Inondations_de_juillet_2021_en_Belgique","c:1/1f/Floods_16_July_2021%2C_Belgium%2C_Tilff_9.jpg"],["Q160913",482,"histoire","Monarchie belge","PC","La monarchie belge est le système de gouvernement en vigueur en Belgique, dans lequel un monarque héréditaire est le souverain de la Belgique, nommé « roi des Belges ». Il est à l'origine des pouvoirs exécutif, judiciaire et législatif.",116,"fr:Monarchie_belge","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Coat_of_Arms_of_the_King_of_the_Belgians.svg/330px-Coat_of_Arms_of_the_King_of_the_Belgians.svg.png"],["Q157109",483,"histoire","Pays-Bas bourguignons","PC","Les Pays-Bas bourguignons sont les provinces des Pays-Bas historiques acquises par les ducs de Bourgogne de la maison de Valois-Bourgogne puis par les Habsbourg, entre les XIVe et XVIe siècles. Leur territoire couvrait la majeure partie des Pays-Bas, de la Belgique, du Luxembourg et des Hauts-de-France actuels.",117,"fr:Pays-Bas_bourguignons","https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Map_Burgundian_Netherlands_1477-fr.svg/330px-Map_Burgundian_Netherlands_1477-fr.svg.png"],["Q6581823",484,"histoire","Pays-Bas méridionaux","PC","Les Pays-Bas méridionaux, aussi qualifiés de Pays-Bas du Sud, de Pays-Bas catholiques, sont les territoires qui forment aujourd'hui la Belgique, le Luxembourg et le Nord-Pas-de-Calais, initialement réunis au XVe siècle par les ducs de Bourgogne, formant avec les Pays-Bas septentrionaux les Pays-Bas bourguignons avant de devenir les Pays-Bas des Habsbourg.",119,"fr:Pays-Bas_méridionaux","c:5/54/Map_of_the_Habsburg_Netherlands_by_Alexis-Marie_Gochet.png"],["Q3399664",485,"histoire","Position fortifiée de Namur","C","La position fortifiée de Namur était constituée de neuf forts de part et d’autre de la Meuse autour de Namur. Il y a quatre grands forts et cinq petits. Ils ont été construits entre 1888 et 1891, à l’initiative du général Henri Alexis Brialmont.","La position fortifiée de Namur était constituée de neuf forts de part et d’autre de la Meuse autour de Namur.","fr:Position_fortifiée_de_Namur","c:6/63/Position_Fortifi%C3%A9e_de_Namur_OSM.png"],["Q158835",486,"histoire","Principauté de Liège","PC","La principauté de Liège ou principauté épiscopale de Liège est un État du Saint-Empire romain germanique dans l'actuelle Belgique qui a existé de la fin du Xe siècle à la fin du XVIIIe siècle, ayant pour capitale la ville de Liège. Dans le cadre féodal du Moyen Âge, le prince-évêque de Liège est à la fois le chef religieux du diocèse de Liège et le chef temporel de la principauté, vassal de l'empereur.",109,"fr:Principauté_de_Liège","https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Locator_Prince-Bishopric_of_Li%C3%A8ge_%281560%29.svg/330px-Locator_Prince-Bishopric_of_Li%C3%A8ge_%281560%29.svg.png"],["Q2666386",487,"histoire","Question royale","C","La question royale désigne, en Belgique, les événements politiques qui eurent lieu entre le 7 mai 1945 et le 31 juillet 1951 à propos du retour au pays du roi Léopold III après la Seconde Guerre mondiale. Cette question fut à l'origine d'un soulèvement insurrectionnel principalement dans le sillon Sambre-et-Meuse de la Wallonie, qui fut le théâtre d'événements sanglants, d'une campagne d'attentats entre le 20 et le 26 juillet 1950, puis d'une grève générale violente.",119,"fr:Question_royale","c:a/a5/Koningskwestie_Kortrijk.jpg",{"cats":["belgique","histoire"]}],["Q15864",488,"histoire","Royaume uni des Pays-Bas","R","Le royaume uni des Pays-Bas, appelé officiellement en français royaume des Belgiques, en néerlandais Verenigd Koninkrijk der Nederlanden, et en latin Regnum Belgicum, est un État créé par le congrès de Vienne de 1815 dans le but d'en faire un État tampon entre les grandes puissances européennes.",109,"fr:Royaume_uni_des_Pays-Bas","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/United_Kingdom_of_the_Netherlands_1815.svg/330px-United_Kingdom_of_the_Netherlands_1815.svg.png"],["Q223933",489,"histoire","Révolution belge","R","La révolution belge désigne la révolte du peuple belge, habitant majoritairement les huit provinces méridionales du royaume uni des Pays-Bas, contre l'autorité néerlandaise de La Haye.",115,"fr:Révolution_belge","c:c/c6/Gustave_Wappers_-_%C3%89pisode_des_Journ%C3%A9es_de_septembre_1830_sur_la_place_de_l%27H%C3%B4tel_de_Ville_de_Bruxelles.jpg",{"cats":["belgique","geo","histoire"]}],["Q1527921",490,"histoire","Révolution liégeoise","C","La révolution liégeoise est la période qui va de 1789 à 1795, et qui entraîne la disparition de la principauté de Liège après huit siècles d'existence.",119,"fr:Révolution_liégeoise","c:7/77/Liege-ruine-stlambert-Chevron-1.jpg"],["Q1669385",491,"histoire","Sac de Dinant","C","Le sac de Dinant ou massacre de Dinant survient durant la Première Guerre mondiale, en août 1914, lorsque des exécutions en masse de civils, le pillage, la mise à sac et l'incendie de Dinant, de Neffe et de Bouvignes-sur-Meuse, en Belgique, sont perpétrés par les troupes allemandes.",109,"fr:Sac_de_Dinant_(1914)","c:b/bc/Destruction_of_Dinant_in_WW1.JPG",{"cats":["belgique","crimes"]}],["Q2617799",492,"histoire","Siège de Namur de 1692","C","Le siège de Namur est un épisode de la guerre de la Ligue d'Augsbourg au cours duquel les armées françaises commandées par Boufflers et Vauban, en présence du roi Louis XIV en personne, assiègent pendant un mois la ville de Namur, alors dans les Pays-Bas espagnols. La ville et le château, solidement fortifiés mais avec une garnison réduite, se rendent successivement les 5 et 30 juin 1692. Ce siège, bien que perturbé par des pluies diluviennes, est largement exploité par la propagande du Roi-Soleil.",118,"fr:Siège_de_Namur_(1692)","c:9/9a/Siege_of_Namur%2C_1692_%28by_Jean-Baptiste_Martin_the_elder%29.jpg"],["Q577353",493,"histoire","Siège de Namur de 1695","C","Le siège de Namur de 1695 est le second siège de la ville durant la guerre de la Ligue d'Augsbourg.",null,"fr:Siège_de_Namur_(1695)","c:4/4e/Die_Belagerung_von_Namur_1695.jpg"],["Q10751243",494,"histoire","Siège de Namur de 1914","C","Le siège de Namur est une bataille entre les forces armées belges et allemandes autour de la forteresse de Namur durant la Première Guerre mondiale. Namur était alors défendue par un anneau de forts modernes, connu sous le nom de Position Fortifiée de Namur et dont les intervalles étaient occupés par la 4e division d'armée belge et quatre régiments de forteresse.",119,"fr:Siège_de_Namur_(1914)","c:8/8f/Defences_of_Namur%2C_1914.jpg"],["Q1160895",495,"histoire","Traité des XXIV articles","C","Le traité des XXIV articles ou traité de Londres du 19 avril 1839 est un ensemble de deux traités signés à Londres le 19 avril 1839 entre d'une part l'Autriche, la France, la Grande-Bretagne, la Prusse et la Russie et, d'autre part, les Pays-Bas et la Belgique.",117,"fr:Traité_des_XXIV_articles","c:d/dc/Scheidingsverdrag_met_Belgi%C3%AB_Nl-HaNA_2.05.02_110G_04.jpg",{"cats":["belgique","histoire"]}],["Q2054700",497,"histoire","Viol de la Belgique","PC","« Viol de la Belgique » est le terme utilisé pour décrire le traitement des civils belges durant l’invasion et l’occupation allemande de la Belgique durant la Première Guerre mondiale. Tout d’abord utilisé dans un but de propagande, ce terme a pu correspondre à une réalité confirmée par l’historiographie. L'historien Larry Zuckerman l’utilise plus étroitement pour décrire la série de crimes de guerre allemands dans les premiers mois de la guerre allant du 4 août à septembre 1914.",110,"fr:Viol_de_la_Belgique","c:4/4c/%22Remember_Belgium._Buy_Bonds_Fourth_Liberty_Loan.%22%2C_ca._1918_-_ca._1918_-_NARA_-_512441.jpg",{"cats":["belgique","crimes"]}],["Q76048",498,"histoire","État indépendant du Congo","R","L'État indépendant du Congo, dont le territoire correspond à celui de l'actuelle république démocratique du Congo, est un État d'Afrique centrale sur lequel le roi des Belges Léopold II de Belgique exerça une souveraineté de fait de 1885 à 1908. Le Congo était donc officiellement reconnu comme la propriété privée du roi des Belges et non une colonie du royaume de Belgique. On peut cependant parler d’union personnelle avec la Belgique.",118,"fr:État_indépendant_du_Congo","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/LocationDemocraticRepublicoftheCongo.svg/330px-LocationDemocraticRepublicoftheCongo.svg.png",{"cats":["belgique","histoire"]}],["Q266765",499,"personnalite","Begge d'Andenne","C","Sainte Begge ou Begga, morte le 17 décembre 693, est l'épouse d'Ansegisel, la mère de Pépin le Jeune, duc et maire d'Austrasie, fondateur de la dynastie carolingienne, et la fondatrice de l'abbaye d'Andenne en région wallonne.",114,"fr:Begge_d%27Andenne","c:b/b8/Jacob_Jordaens_-_Saint_Begga.jpg"],["Q1547623",500,"monument","Grotte Scladina","C","La Grotte Scladina est une cavité karstique située à Sclayn, dans la commune d'Andenne en Belgique. D'importants restes humains préhistoriques y furent découverts, ainsi que des traces d'ours des cavernes.",112,"fr:Grotte_Scladina","https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Scladina01.jpg/3840px-Scladina01.jpg"],["Q3330010",501,"monument","Musée de la céramique d'Andenne","C","Le musée de la céramique, situé dans la ville belge d’Andenne, présente une vaste collection de céramiques datant de l’époque gallo-romaine à nos jours retraçant près de 2000 ans d’activité autour de la derle, argile blanche de grande qualité très présente dans le sous-sol de la région. Il fut créé en 1933.",116,"fr:Mus%C3%A9e_de_la_c%C3%A9ramique_d%27Andenne","c:2/27/Musee-de-la-ceramique-dandenne-facade.jpg"],["Q2820500",502,"monument","Abbaye d'Andenne","C","L'abbaye d'Andenne était un monastère fondé par sainte Begge, fille de Pépin de Landen, veuve d'Ansegisel et mère de Pépin de Herstal, vers 692.",116,"fr:Abbaye_d%27Andenne","c:7/75/Andenne_050802_%284%29.JPG"],["Q28499530",503,"monument","Château de Namêche","C","Le château de Namêche est un château érigé par François Moncheur au XIXe siècle, situé en Wallonie à Namêche (Andenne).",null,"fr:Ch%C3%A2teau_de_Nam%C3%AAche","c:7/7b/Ch%C3%A2teau_de_Nam%C3%AAche.png"],["Q5472461",504,"monument","Fort de Maizeret","C","Le fort de Maizeret est un des neuf forts semi-enterrés composant la position fortifiée de Namur établie à la fin du XIXe siècle en Belgique. Ce fort est construit de 1888 à 1892 selon les plans du général Brialmont. Contrairement aux forts français construits à la même époque par Séré de Rivières, ce fort enterré est en béton non-armé, nouveau matériau pour l'époque, au lieu de maçonnerie.",116,"fr:Fort_de_Maizeret",""],["Q3109195",505,"personnalite","Jean Tousseul","C","Jean Tousseul, né à Landenne (Belgique) le 7 décembre 1890 et décédé à Seilles le 9 février 1944, est un écrivain belge d'expression française.",113,"fr:Jean_Tousseul","c:d/dd/Jean_Tousseul_statue_in_Seilles_Andenne.jpg"],["Q1287514",506,"bd","Édouard Aidans","C","Édouard Aidans, né le 13 août 1930 à Andenne et mort le 6 septembre 2018 à Gesves, est un auteur de bande dessinée belge. Il est notamment le dessinateur des séries Tounga, Les Franval, Bob Binn et Les Panthères. Il a utilisé les pseudonymes de Jok, Delcroix, Joke et Hardan.",114,"fr:%C3%89douard_Aidans","c:a/a7/Olivier_Saive_%C3%89douard_Aidans_19950525.jpg"],["Q3439148",507,"personnalite","Roger Laboureur","C","Roger Laboureur est un journaliste sportif belge de la RTBF né le 13 juillet 1935 à Andenne et mort le 14 décembre 2025.",null,"fr:Roger_Laboureur",""],["Q2101769",508,"ville","Thon-Samson","C","Thon-Samson est une section de la ville belge d'Andenne située en Région wallonne dans la province de Namur.",null,"fr:Thon-Samson","c:0/09/Thon-Samson_JPG02.jpg"],["Q3475234",509,"ville","Vezin","C","Vezin est un village des hauteurs de Meuse entre Namur et la ville d'Andenne dont il fait administrativement partie, dans la province de Namur. C'était une commune à part entière avant la fusion des communes de 1977.",116,"fr:Vezin","https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Eglise_Saint-Martin_Vezin_Andenne.jpg/3840px-Eglise_Saint-Martin_Vezin_Andenne.jpg"],["Q97445432",510,"personnalite","Félix Radu","R","Félix Radu, né le 15 octobre 1995 à Namur, en Wallonie, est un comédien, interprète, auteur et dramaturge belge.",null,"fr:F%C3%A9lix_Radu","c:2/26/F%C3%A9lix_Radu.jpg"],["Q160780",511,"personnalite","Henri Michaux","R","Henri Michaux, né le 24 mai 1899 à Namur (Belgique) et mort le 19 octobre 1984 à Paris, est un écrivain, poète et peintre belge d'expression française naturalisé français en 1955.",113,"fr:Henri_Michaux",""],["Q24951514",512,"personnalite","GuiHome","R","Guillaume Wattecamps, dit GuiHome, est un vidéaste et humoriste belge, né le 20 janvier 1992 à Namur.",null,"fr:GuiHome",""],["Q1383055",513,"personnalite","Rémy Belvaux","PC","Rémy Belvaux est un réalisateur, producteur et scénariste belge, né le 10 novembre 1966 à Namur et mort par suicide le 5 septembre 2006 à Orry-la-Ville.",115,"fr:R%C3%A9my_Belvaux",""],["Q1873071",514,"personnalite","Lucas Belvaux","PC","Lucas Belvaux est un acteur, réalisateur et romancier belgo-français né le 14 novembre 1961 à Namur.",null,"fr:Lucas_Belvaux","c:b/b6/Lucas_Belvaux_Deauville_2010_%28cropped%29.jpg"],["Q2465172",515,"personnalite","Julie Taton","C","Julie Taton, née le 6 février 1984 à Namur (Belgique), est un mannequin, animatrice de radio et de télévision et femme politique belge.",112,"fr:Julie_Taton","c:6/6f/Julie_Taton_2005.jpg"],["Q66758410",516,"personnalite","Adélaïde Charlier","PC","Adélaïde Charlier, née le 9 décembre 2000 à Namur, est une activiste belge militant pour la justice climatique et sociale. Elle a cofondé en Belgique le mouvement Youth for Climate. Elle est principalement connue pour son engagement dans la lutte contre le changement climatique. Inspirée par les actions de Greta Thunberg, elle est l'une des figures, avec Kyra Gantois et Anuna De Wever, des premières grèves scolaires pour le climat en Belgique.",113,"fr:Ad%C3%A9la%C3%AFde_Charlier","c:2/28/Ad%C3%A9la%C3%AFde_Charlier%2C_2021_%28cropped%29.jpg"],["Q441059",517,"personnalite","Christophe Rochus","C","Christophe Rochus, né le 15 décembre 1978 à Namur, est un joueur de tennis belge professionnel de 1996 à 2010.",null,"fr:Christophe_Rochus","c:f/f6/ChristopheRochusStuttgart06.jpg"],["Q3190857",518,"personnalite","Jérôme Colin","R","Jérôme Colin, né le 9 novembre 1974 à Flawinne, est un journaliste et romancier belge.",null,"fr:J%C3%A9r%C3%B4me_Colin","c:1/15/J%C3%A9r%C3%B4me_Colin.jpg"],["Q2449493",519,"monument","Parlement wallon","C","Le Parlement wallon ou Parlement de Wallonie est l'assemblée législative de la Région wallonne, en Belgique.",null,"fr:Parlement_wallon","https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Parlement_Wallon_11_2026-04-22.svg/langfr-960px-Parlement_Wallon_11_2026-04-22.svg.png"],["Q1186375",520,"histoire","Gouvernement wallon","C","Le Gouvernement wallon ou Gouvernement de Wallonie est le pouvoir exécutif de la Région wallonne, une des trois régions de Belgique.",111,"fr:Gouvernement_wallon","c:7/7e/L%E2%80%99%C3%89lysette%2C_c%C3%B4t%C3%A9_Meuse.jpg"],["Q2491106",521,"tradition","L'Avenir","PC","Les éditions de l'Avenir, communément appelée « L'Avenir » et anciennement « Vers l'Avenir », est une entreprise de presse écrite belge de langue française dont le siège social est à Namur.",115,"fr:L%27Avenir_%28Belgique%29","c:c/c8/L%27Avenir_Logo.jpg"],["Q1391755",522,"monument","Université de Namur","C","L'Université de Namur (UNamur) est une institution d'enseignement supérieur universitaire catholique subventionnée par la Fédération Wallonie-Bruxelles sise à Namur. Fondée en 1831 par les jésuites comme collège secondaire, dans les bâtiments restaurés de l'ancienne abbaye bénédictine de la Paix-Notre-Dame à Namur elle se développe en Facultés universitaires Notre-Dame-de-la-Paix (FUNDP) avant de changer de nom en 2013.",114,"fr:Universit%C3%A9_de_Namur","https://thumb.wikimedia.org/wikipedia/fr/thumb/1/14/Universit%C3%A9_de_Namur.svg/langfr-500px-Universit%C3%A9_de_Namur.svg.png"],["Q1539341",523,"tradition","Union Namur","C","L'Union Royale Namur est un club de football belge, localisé à Namur. Porteur du matricule 156, le club porte les couleurs noir et jaune, d'où le surnom de \"Merles\". Il évolue en Nationale 2 FFA, quatrième niveau national, lors de la saison 2026-2027. C'est sa 92e saison dans les divisions nationales.",113,"fr:Union_Namur","c:3/36/Logo_Union_Namur.png"],["Q3143139",524,"ville","Marche-les-Dames","C","Marche-les-Dames est une section de la ville belge de Namur située en Wallonie dans la province de Namur. C'était une commune à part entière avant la fusion des communes de 1977. Le village est situé sur la rive gauche de Meuse, à l'embouchure de la Gelbressée.",113,"fr:Marche-les-Dames","c:2/23/Marche-lesDames_AB1aJPG.jpg"],["Q2012137",525,"monument","Abbaye de Marche-les-Dames","C","L'abbaye de Marche-les-Dames est un édifice monastique fondé en 1103 et supprimé en 1796. L'abbaye était située dans la section Marche-les-Dames de la commune de Namur, en Belgique. La communauté de moniales s'est affiliée à l'ordre cistercien un siècle après la fondation de leur couvent.",116,"fr:Abbaye_de_Marche-les-Dames","https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Marche-les-Dames_-_abbaye_Notre-Dame_du_Vivier_-_2023-10-22_-_vue_depuis_la_cour_d%27honneur_-_01.jpg/3840px-Marche-les-Dames_-_abbaye_Notre-Dame_du_Vivier_-_2023-10-22_-_vue_depuis_la_cour_d%27honneur_-_01.jpg"],["Q39657983",526,"monument","Grognon","C","Le Grognon est le cœur historique de la ville belge de Namur, capitale de la Wallonie, chef-lieu de la province du même nom, prenant la forme d’une pointe de terre à la confluence de la Sambre et de la Meuse. L'ancien hospice Saint-Gilles abrite le Parlement wallon.",114,"fr:Grognon","c:1/11/La_Citadelle_de_Namur.JPG"],["Q28040633",527,"monument","Place d'Armes","C","La place d’Armes, autrefois Grand Place, est une place pavée située à Namur en Belgique.",null,"fr:Place_d%27Armes_%28Namur%29","c:e/eb/Namur_2007_04.JPG"],["Q1957513",528,"ville","Salzinnes","C","Salzinnes est un ancien village devenu faubourg occidental de la ville belge de Namur, située en Région wallonne dans la province de Namur.",112,"fr:Salzinnes","c:6/68/Place_Wiertz.jpg"],["Q2557883",529,"monument","Église Saint-Loup de Namur","C","L'église Saint-Loup est un édifice religieux catholique sis dans le centre de la ville de Namur (Belgique). De style baroque, elle est construite au XVIIe siècle comme église Saint-Ignace au service du collège jésuite y attenant.",116,"fr:%C3%89glise_Saint-Loup_de_Namur","c:c/c0/%C3%89glise_Saint-Loup%2C_Namur_3.jpg"],["Q1334526",530,"personnalite","Philippe Lafontaine","PC","Philippe Lafontaine, né le 24 mai 1955 à Gosselies (Charleroi), est un auteur-compositeur et interprète belge. Il connaît le succès en 1989 grâce à la chanson Cœur de loup.",113,"fr:Philippe_Lafontaine",""],["Q2579840",531,"personnalite","Georgette Magritte","R","Georgette Magritte, née Georgette Berger à Marcinelle le 22 février 1901 et morte à Schaerbeek le 26 février 1986, est l'épouse et le principal modèle du peintre belge René Magritte.",114,"fr:Georgette_Magritte","c:f/f0/Georgette_Berger_%28Remini_enhanced%29.jpg"],["Q236173",532,"personnalite","Chantal Mouffe","PC","Chantal Mouffe, née le 17 juin 1943 à Charleroi (Belgique), est une philosophe politique belge.",null,"fr:Chantal_Mouffe","https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Chantal_Mouffe_2013.jpg/3840px-Chantal_Mouffe_2013.jpg"],["Q212363",533,"personnalite","Silvio Proto","PC","Silvestro Proto, plus connu sous le nom de Silvio Proto, né le 23 mai 1983 à Charleroi en Belgique, est un footballeur international belge, actif des années 2000 à 2020, qui joue au poste le poste de gardien de but. Il est actuellement entraîneur des gardiens au RSC Anderlecht.",106,"fr:Silvio_Proto","c:4/49/Silvio_Proto_2011.jpg"],["Q14107962",534,"personnalite","Felice Mazzù","C","Felice Mazzù, né le 12 mars 1966 à Charleroi en Belgique, est un entraîneur italo-belge de football. Il est actuellement l'entraîneur de la KAS Eupen.",107,"fr:Felice_Mazz%C3%B9","c:7/7d/Felice_Mazzu.jpg"],["Q3176173",535,"personnalite","Jeanne Toussaint","C","Jeanne Toussaint, née le 13 janvier 1887 à Charleroi et morte le 7 mai 1976 en son domicile dans le 16e arrondissement de Paris, est une joaillière franco-belge.",103,"fr:Jeanne_Toussaint","c:3/31/Jeanne_Toussaint_1920_by_Adolf_de_Meyer.jpg"],["Q3193120",536,"personnalite","Karen Minier","C","Karen Minier, née le 22 mars 1973 à Charleroi en Belgique est une animatrice de télévision en France.",null,"fr:Karen_Minier",""],["Q3086494",537,"personnalite","Françoise Gillard","C","Françoise Gillard, née à Charleroi le 6 mai 1973, est une actrice belgo-française, sociétaire de la Comédie-Française.",null,"fr:Fran%C3%A7oise_Gillard",""],["Q2062274",538,"tradition","Royal Olympic Club de Charleroi","C","Le (Royal) Olympic Club de Charleroi est un club belge de football basé à Montignies-sur-Sambre. Porteur du matricule 246, le club évolue en Challenger Pro League lors de la saison 2025-2026.",107,"fr:Royal_Olympic_Club_de_Charleroi","https://thumb.wikimedia.org/wikipedia/fr/thumb/5/5d/Logo_Olympic_Charleroi.svg/langfr-960px-Logo_Olympic_Charleroi.svg.png"],["Q2426936",539,"tradition","Groupe Louis Delhaize","C","Le groupe Louis Delhaize est une société de distribution belge de commerce alimentaire et d'enseignes de jardineries, comme les Jardineries Truffaut, en Belgique, en France et au Luxembourg et au travers de franchises en Hongrie et en Roumanie.",104,"fr:Groupe_Louis_Delhaize","c:e/e0/Logo_de_la_cha%C3%AEne_de_supermarch%C3%A9_Louis_Delhaize.jpg"],["Q16011240",540,"histoire","Forteresse de Charleroi","C","La forteresse de Charleroi est une ancienne place forte, située sur la Sambre, qui est à l'origine de la ville de Charleroi, en Belgique. Édifiée par les Espagnols en 1666, elle a été agrandie par les Français, partiellement démantelée au XVIIIe siècle, puis reconstruite par le royaume uni des Pays-Bas au début du XIXe siècle comme l'un des éléments de la barrière Wellington, avant d'être démantelée définitivement en 1871.",113,"fr:Forteresse_de_Charleroi","c:f/f2/Charleroy_-_paysage_au_17e_si%C3%A8cle.jpg"],["Q848270",541,"histoire","Ateliers de constructions électriques de Charleroi","C","Les Ateliers de constructions électriques de Charleroi est une importante entreprise belge. Sa section spécialisée dans le matériel roulant ferroviaire fondée en 1904, devient Alstom Belgium en 1989, filiale du groupe français Alstom.",114,"fr:Ateliers_de_constructions_%C3%A9lectriques_de_Charleroi","c:d/dd/ACEC_-_Logo_venant_des_sacs_plastique_du_Service_Technique.jpg",{"cats":["belgique","urbex"]}],["Q725633",542,"ville","Monceau-sur-Sambre","C","Monceau-sur-Sambre est une section de la ville belge de Charleroi située en Wallonie dans la province de Hainaut.",null,"fr:Monceau-sur-Sambre","c:e/ea/Monceau-sur-Sambre_240410_%283%29.JPG"],["Q3581178",543,"monument","Église Saint-Christophe de Charleroi","C","L’église Saint-Christophe à Charleroi, en Belgique, se situe sur la place Vauban qu'elle domine avec l'hôtel de ville et le beffroi.",111,"fr:%C3%89glise_Saint-Christophe_de_Charleroi","c:8/89/Charleroi_-_%C3%A9glise_Saint-Christophe_-_2024-10-16_-_01.jpg"],["Q3533027",544,"monument","Tour Bleue","C","La tour Bleue est le nom de l'Hôtel de police de la Zone de police Charleroi. Conçue par l'architecte français Jean Nouvel et Mdw Architecture, elle se situe sur le site de la caserne Defeld, le long du boulevard Mayence et voit le jour en 2014. Avec ses 75 mètres, il est le deuxième bâtiment le plus haut de la ville après le Centre Albert et avant le beffroi de l'hôtel de ville.",115,"fr:Tour_Bleue","c:4/40/Charleroi_-_Tour_bleue_-_2019-12-28_-_05.jpg"],["Q110553494",545,"personnalite","Adrien Dolimont","PC","Adrien Dolimont, né le 18 septembre 1988 à Montigny-le-Tilleul, est un homme politique belge membre du Mouvement réformateur (MR). Il est ministre-président du gouvernement wallon et bourgmestre empêché de Ham-sur-Heure-Nalinnes depuis 2024.",112,"fr:Adrien_Dolimont","https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/DOLIMONT1.jpg/3840px-DOLIMONT1.jpg"],["Q446756",546,"personnalite","Joëlle Milquet","C","Joëlle Milquet, née le 17 février 1961 à Montignies-sur-Sambre (Charleroi), est une femme politique belge.",null,"fr:Jo%C3%ABlle_Milquet","c:7/75/Jo%C3%ABlle_Milquet_2004.jpg"],["Q468290",547,"personnalite","Dominique Wilms","C","Dominique Wilms, de son vrai nom Claudine Maria Célina Wilmes, est une actrice française, née le 8 juin 1930 à Montignies-sur-Sambre (Belgique) et morte le 17 septembre 2025 à Paris 5e.",110,"fr:Dominique_Wilms","c:7/77/Dominque_wilms.jpg"],["Q1401380",548,"bd","Dupa","C","Luc Dupanloup, dit Dupa, né le 12 février 1945 à Montignies-sur-Sambre et mort le 8 novembre 2000 à Ottignies-Louvain-la-Neuve, est un auteur de bande dessinée humoristique belge, connu pour sa série Cubitus.",99,"fr:Dupa","https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Tombe_de_Dupa_%281945%E2%80%932000%29_3.jpg/3840px-Tombe_de_Dupa_%281945%E2%80%932000%29_3.jpg"],["Q25172116",549,"personnalite","Ismaël Debjani","C","Ismaël Debjani est un athlète belge spécialiste du demi-fond. Depuis le 11 juin 2017, il est le détenteur du record de Belgique du 1 500 m",115,"fr:Isma%C3%ABl_Debjani","c:e/e2/Meeting_de_Paris%2C_Stade_Charlety_-_30_juin_2018_%2843129925981%29.jpg"],["Q720791",550,"ville","Jemeppe-sur-Sambre","C","Jemeppe-sur-Sambre est une commune de Wallonie, dans la province de Namur, traversée par la Sambre. Elle regroupe plusieurs villages, dont Spy, célèbre dans le monde entier pour l'« Homme de Spy » : des squelettes de Néandertaliens découverts dans une grotte en 1886. C'est aussi le fief du joueur barb.",113,"fr:Jemeppe-sur-Sambre","c:b/b5/Station_Jemeppe-sur-Sambre_3.jpg"],["Q2655059",551,"ville","Ham-sur-Sambre","C","Ham-sur-Sambre est un village de Wallonie, en bord de Sambre, qui fait partie de la commune de Jemeppe-sur-Sambre dans la province de Namur. C'était une commune à part entière jusqu'à la fusion des communes de 1977.",113,"fr:Ham-sur-Sambre","c:6/60/Ham-sur-Sambre_Vi1a.jpg"],["Q1260067",552,"ville","Spy","PC","Spy est un gros village de la commune de Jemeppe-sur-Sambre, entre l'Orneau et la Sambre. Son nom est connu des préhistoriens du monde entier : on a découvert en 1886, dans la grotte de Spy toute proche, deux squelettes de Néandertaliens, l'une des preuves que l'Homme de Néandertal était bien une espèce humaine.",111,"fr:Spy_(Belgique)","c:8/8c/Spy_-_St-Amand_110114_%281%29.JPG"],["Q3326401",553,"ville","Moustier-sur-Sambre","C","Moustier-sur-Sambre est un village de la commune de Jemeppe-sur-Sambre, en province de Namur, posé au bord de la Sambre. Il était une commune à part entière jusqu'à la fusion des communes de 1977.",112,"fr:Moustier-sur-Sambre","c:6/62/Moustier-sur-Sambre_U1a.jpg"],["Q2780714",554,"ville","Mornimont","C","Mornimont est un petit village de la commune de Jemeppe-sur-Sambre, en province de Namur, en bord de Sambre. Ancienne commune, il a été rattaché à Jemeppe lors de la fusion des communes de 1977.",108,"fr:Mornimont","https://yeswsusaigmiapvmxdmc.supabase.co/storage/v1/object/public/card-art/bfce6be2-aafa-4ca6-abfb-8d07a05e0857/lieu-mornimont.webp"],["Q2666674",555,"ville","Godinne","C","Godinne est un village de bord de Meuse qui fait partie de la commune d'Yvoir, en province de Namur. Il est notamment connu pour son grand hôpital universitaire, le CHU UCL Namur, installé sur les hauteurs du Mont-Godinne.",107,"fr:Godinne","c:3/3d/Godinne_JPG001.jpg"],["Q650163",556,"ville","Yvoir","C","Yvoir est une commune de Wallonie dans la province de Namur, nichée dans la vallée de la Meuse entre Namur et Dinant. Avec ses rochers, ses villages comme Godinne, Durnal et Spontin, et son île en pleine Meuse, c'est un coin prisé des balades et du kayak.",109,"fr:Yvoir","c:3/3b/Yvoir_JPG01.jpg"],["Q289842",557,"ville","Durnal","C","Durnal est un village de la commune d'Yvoir, dans la province de Namur. Ancienne commune, il a été rattaché à Yvoir lors de la fusion des communes de 1977.",109,"fr:Durnal","c:6/6b/Durnal_JPG000.jpg"],["Q545889",558,"ville","Anhée","C","Anhée est une commune de Wallonie située dans la province de Namur, au bord de la Meuse, entre Namur et Dinant. Elle regroupe plusieurs villages, dont Annevoie et ses célèbres jardins, Hun et Rouillon.",111,"fr:Anhée","c:7/77/Anh%C3%A9e_JPG01.jpg"],["Q2409809",559,"ville","Lustin","C","Lustin est un village de la commune de Profondeville, en province de Namur. C'est le seul village de la commune situé sur la rive droite de la Meuse, au pied des impressionnants rochers de Frênes, prisés des grimpeurs.",111,"fr:Lustin","c:c/c3/Lustin_Fontinne_Sint-Lupcin.jpg"],["Q2006902",560,"ville","Crupet","PC","Crupet est un village de la commune d'Assesse, en province de Namur, membre des « Plus beaux villages de Wallonie ». Il est célèbre pour son donjon médiéval entouré d'eau et pour sa grotte dédiée à saint Antoine.",113,"fr:Crupet","c:7/76/Crupet_Castle_donjon%2C_Crupet%2C_Assesse%2C_2025.jpg"],["Q768270",561,"ville","Bouvignes-sur-Meuse","C","Bouvignes-sur-Meuse est un ancien bourg fortifié en bord de Meuse, juste au nord de Dinant, dont il fait aujourd'hui partie. Dominé par les ruines du château de Crèvecœur, il est classé parmi les « Plus beaux villages de Wallonie ».",104,"fr:Bouvignes-sur-Meuse","c:d/d8/Bouvignes.jpg"],["Q1013148",562,"monument","Château de Montaigle","PC","Le château de Montaigle est un château fort médiéval en ruine, perché sur un éperon rocheux à Falaën, dans la province de Namur. Il domine la vallée de la Molignée et fait partie des ruines les plus spectaculaires de Wallonie.",109,"fr:Château_de_Montaigle","c:3/3b/Montaigle_2_Luc_Viatour.jpg"],["Q940240",563,"ville","Auvelais","C","Auvelais est une localité de la commune de Sambreville, en province de Namur, au bord de la Sambre. Ancienne commune, elle a été intégrée à Sambreville lors de sa création en 1977.",108,"fr:Auvelais","c:2/21/Auvelais_view_from_french_cemetery_Belgium_20070101_%282%29_Didier_Misson.JPG"],["Q2010774",564,"ville","Tamines","C","Tamines est une localité de la commune de Sambreville, en province de Namur. Son nom reste lié au massacre de civils commis par l'armée allemande en août 1914, au début de la Première Guerre mondiale.",109,"fr:Tamines","c:8/89/Tamines_E1aJPG.jpg"],["Fbe_hun",565,"ville","Hun","C","Hun est un hameau d'Annevoie-Rouillon, perché au-dessus de la Meuse dans la boucle qu'elle dessine entre Yvoir et Godinne. Il fait aujourd'hui partie de la commune d'Anhée, dans la province de Namur, et veille sur la vallée depuis sa petite chapelle Saint-Christophe.",113,"fr:Hun_(Belgique)","c:1/1b/Hun%2C_chapelle_Saint-Christophe_foto2_2012-06-30_15.52.JPG"]]]);